/// **channel.create, end to end (증보 V3, V6, V11).**
///
/// One approval creates the channel as the approver, seats the proposing agent
/// and the named member, and puts the channel in the agent's approved set — and
/// nothing about the connection's confirm columns moves. A non-admin is refused
/// with the approval intact; the agent reads the new channel's id from its own
/// outcome line and can then post there.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn an_approved_channel_create_is_one_step_for_channel_membership_and_grant() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let plain_jwt = seed_plain_member(&su, &fixture).await;
    let (extra, extra_handle) = seed_extra_member_3706(&su, &fixture, "guest").await;
    // The fixture's generated handle is longer than the 32 a real workspace
    // allows; give the approver a legal one so it can be named in the proposal.
    let approver_handle = format!("boss-{}", &Uuid::new_v4().simple().to_string()[..8]);
    sqlx::query("UPDATE member SET handle=$2 WHERE id=$1")
        .bind(fixture.human)
        .bind(&approver_handle)
        .execute(&su)
        .await
        .unwrap();
    let name = format!("plan-{}", &Uuid::new_v4().simple().to_string()[..8]);

    // The approver's own handle is in the list on purpose: the approver already
    // owns the channel, and re-adding them must not downgrade `owner`.
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "channel.create",
        json!({"name": name, "memberHandles": [extra_handle, approver_handle]}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval_id = proposed_approval_3706(&proposed);
    let card_message_id =
        Uuid::parse_str(structured(&proposed)["cardMessageId"].as_str().unwrap()).unwrap();

    // The card shows the server's names and the widening row, not the handles.
    let card: Value = sqlx::query_scalar("SELECT props FROM message WHERE id=$1")
        .bind(card_message_id)
        .fetch_one(&su)
        .await
        .unwrap();
    let rows = card["action"]["rows"].as_array().expect("rows").clone();
    let row = |label: &str| {
        rows.iter()
            .find(|row| row["label"] == label)
            .unwrap_or_else(|| panic!("no {label} row in {rows:?}"))["value"]
            .as_str()
            .unwrap()
            .to_string()
    };
    assert_eq!(row("채널"), format!("#{name}"));
    assert_eq!(row("공개 범위"), "비공개", "the default kind is private");
    assert!(row("이 에이전트도 참여").starts_with("예"));
    // Display names are not unique, handles are: the card names both, so the
    // approver reads exactly who is being seated.
    assert!(row("함께 넣을 멤버").contains("Extra guest"));
    assert!(
        row("함께 넣을 멤버").contains(&format!("(@{extra_handle})")),
        "{}",
        row("함께 넣을 멤버")
    );
    assert_eq!(card["action"]["required_role"], json!("admin"));
    assert!(channel_row_3706(&su, fixture.workspace, &name)
        .await
        .is_none());

    let approved_before = hosted_approved_3706(&su, &fixture).await;
    let confirm_before = hosted_confirm_columns_3706(&su, &fixture).await;
    let jobs_before = agent_job_count(&su, fixture.workspace, fixture.hosted_agent).await;

    // ---- a non-admin is refused; nothing happens ---------------------------
    let (status, _h, refused) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &plain_jwt,
        approval_id,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 403, "{refused}");
    assert_eq!(refused["status"], "role_required");
    assert!(channel_row_3706(&su, fixture.workspace, &name)
        .await
        .is_none());
    assert_eq!(hosted_approved_3706(&su, &fixture).await, approved_before);
    let pending: String = sqlx::query_scalar("SELECT status::text FROM approval WHERE id=$1")
        .bind(approval_id)
        .fetch_one(&su)
        .await
        .unwrap();
    assert_eq!(pending, "pending");

    // ---- an agent cannot decide -------------------------------------------
    let agent_try = client
        .post(format!(
            "{base}/v1/workspaces/{}/approvals/{approval_id}/decision",
            fixture.workspace
        ))
        .bearer_auth(&fixture.hosted_bearer)
        .json(&json!({"approvalId": approval_id, "approve": true,
                      "clientDecisionId": Uuid::new_v4()}))
        .send()
        .await
        .expect("agent decision responds");
    assert!(
        matches!(agent_try.status().as_u16(), 401 | 403),
        "an agent bearer must not decide: {}",
        agent_try.status()
    );
    assert!(channel_row_3706(&su, fixture.workspace, &name)
        .await
        .is_none());

    // ---- the admin approves ------------------------------------------------
    let (status, headers, approved) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval_id,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(
        headers.get("cache-control").and_then(|v| v.to_str().ok()),
        Some("no-store")
    );
    assert_eq!(approved["result"]["actionId"], json!("channel.create"));
    assert_eq!(approved["result"]["ref"]["type"], json!("channel"));
    assert!(
        approved["result"].get("secretOnce").is_none(),
        "channel.create mints no one-time value: {approved}"
    );
    let (channel_id, kind, created_by) = channel_row_3706(&su, fixture.workspace, &name)
        .await
        .expect("the channel exists");
    assert_eq!(
        approved["result"]["ref"]["id"],
        json!(channel_id.to_string())
    );
    assert_eq!(kind, "private");
    assert_eq!(created_by, fixture.human, "the APPROVER created it");

    let roles: Vec<(Uuid, String)> = sqlx::query_as(
        "SELECT member_id, role::text FROM membership \
          WHERE workspace_id=$1 AND channel_id=$2 AND left_at IS NULL",
    )
    .bind(fixture.workspace)
    .bind(channel_id)
    .fetch_all(&su)
    .await
    .unwrap();
    let role_of = |member: Uuid| {
        roles
            .iter()
            .find(|(id, _)| *id == member)
            .map(|(_, role)| role.as_str())
    };
    assert_eq!(role_of(fixture.human), Some("owner"), "{roles:?}");
    assert_eq!(role_of(fixture.hosted_agent), Some("member"), "{roles:?}");
    assert_eq!(role_of(extra), Some("member"), "{roles:?}");
    assert_eq!(roles.len(), 3, "{roles:?}");

    let approved_after = hosted_approved_3706(&su, &fixture).await;
    assert!(approved_after.contains(&channel_id));
    assert_eq!(approved_after.len(), approved_before.len() + 1);
    assert_eq!(
        hosted_confirm_columns_3706(&su, &fixture).await,
        confirm_before,
        "a grant never touches the confirm columns"
    );
    let covered: Vec<Uuid> =
        sqlx::query_scalar("SELECT unnest(hosted_connection_channel_ids($1,$2))")
            .bind(fixture.workspace)
            .bind(fixture.hosted_connection)
            .fetch_all(&su)
            .await
            .unwrap();
    assert!(covered.contains(&channel_id));

    // ---- audit -------------------------------------------------------------
    assert_eq!(
        audit_count_3706(&su, fixture.workspace, "channel.created").await,
        1
    );
    assert_eq!(
        audit_count_3706(&su, fixture.workspace, "hosted_connection.channels_granted").await,
        1
    );
    let detail: Value = sqlx::query_scalar(
        "SELECT detail FROM audit_log WHERE workspace_id=$1 AND action='channel.created'",
    )
    .bind(fixture.workspace)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(detail["name"], json!(name));
    assert_eq!(
        detail["member_count"],
        json!(1),
        "only the one actually seated"
    );
    assert_eq!(
        detail["member_ids"],
        json!([extra.to_string()]),
        "the audit row names who got in; the approver and the agent are not 'added'"
    );
    assert_eq!(detail["add_proposer"], json!(true));
    assert_eq!(detail["via_agent"], json!(fixture.hosted_agent.to_string()));
    assert_eq!(detail["approval_id"], json!(approval_id.to_string()));

    // ---- the run ended, with no job behind it ------------------------------
    assert_eq!(
        agent_job_count(&su, fixture.workspace, fixture.hosted_agent).await,
        jobs_before
    );

    // ---- the agent can read the id and then speak in the new channel -------
    let line: (String, Value) = sqlx::query_as(
        "SELECT body, props FROM message WHERE workspace_id=$1 AND channel_id=$2 \
           AND type='approval_request' AND props->'result'->>'status'='executed' ORDER BY seq DESC LIMIT 1",
    )
    .bind(fixture.workspace)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    assert!(line.0.contains(&channel_id.to_string()), "{}", line.0);
    assert!(
        line.1["result"].get("next").is_none(),
        "no dead settings link on a channel result"
    );
    let (status, read) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_conversation_read",
        json!({"channelId": fixture.channel, "limit": 20}),
    )
    .await;
    assert_eq!(status, 200, "{read}");
    assert!(
        structured(&read)
            .to_string()
            .contains(&channel_id.to_string()),
        "the agent must be able to read the new channel's id: {read}"
    );
    let (status, posted) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_message_post",
        json!({"channelId": channel_id, "clientMsgId": Uuid::new_v4(), "body": "첫 인사"}),
    )
    .await;
    assert_eq!(
        status, 200,
        "the agent is a member AND approved there: {posted}"
    );
}

/// `addProposer: false` seats and grants nothing for the agent.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_channel_create_without_the_proposer_widens_nothing() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let name = format!("solo-{}", &Uuid::new_v4().simple().to_string()[..8]);

    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "channel.create",
        json!({"name": name, "kind": "public", "addProposer": false}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let card_message_id =
        Uuid::parse_str(structured(&proposed)["cardMessageId"].as_str().unwrap()).unwrap();
    let card: Value = sqlx::query_scalar("SELECT props FROM message WHERE id=$1")
        .bind(card_message_id)
        .fetch_one(&su)
        .await
        .unwrap();
    assert!(card["action"]["rows"]
        .as_array()
        .unwrap()
        .iter()
        .any(|row| row["label"] == "이 에이전트도 참여" && row["value"] == "아니요"));

    let approved_before = hosted_approved_3706(&su, &fixture).await;
    let (status, _h, approved) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        proposed_approval_3706(&proposed),
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    let (channel_id, kind, _) = channel_row_3706(&su, fixture.workspace, &name)
        .await
        .expect("channel");
    assert_eq!(kind, "public");
    let agent_in: i64 =
        sqlx::query_scalar("SELECT count(*) FROM membership WHERE channel_id=$1 AND member_id=$2")
            .bind(channel_id)
            .bind(fixture.hosted_agent)
            .fetch_one(&su)
            .await
            .unwrap();
    assert_eq!(agent_in, 0, "the agent was not seated");
    assert_eq!(hosted_approved_3706(&su, &fixture).await, approved_before);
    assert_eq!(
        audit_count_3706(&su, fixture.workspace, "hosted_connection.channels_granted").await,
        0
    );
    assert_eq!(
        audit_count_3706(&su, fixture.workspace, "channel.created").await,
        1
    );
}

/// A failure after the channel row exists rolls back **everything**, leaves the
/// approval pending, and a retry after the fault is cleared succeeds. The fault
/// is injected as a trigger that refuses the extra member's `membership` insert,
/// i.e. it fires after the channel, the creator's membership and the agent's
/// membership were already written in the same transaction.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_channel_create_that_fails_midway_leaves_no_trace_and_can_be_retried() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (extra, extra_handle) = seed_extra_member_3706(&su, &fixture, "late").await;
    let name = format!("atomic-{}", &Uuid::new_v4().simple().to_string()[..8]);

    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "channel.create",
        json!({"name": name, "memberHandles": [extra_handle]}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval_id = proposed_approval_3706(&proposed);
    let approved_before = hosted_approved_3706(&su, &fixture).await;

    sqlx::query(&format!(
        "CREATE OR REPLACE FUNCTION fail_membership_3706() RETURNS trigger LANGUAGE plpgsql AS \
         $$ BEGIN IF NEW.member_id = '{extra}' THEN RAISE EXCEPTION 'injected failure'; END IF; \
         RETURN NEW; END $$"
    ))
    .execute(&su)
    .await
    .unwrap();
    sqlx::query(
        "CREATE TRIGGER fail_membership_3706 BEFORE INSERT ON membership \
           FOR EACH ROW EXECUTE FUNCTION fail_membership_3706()",
    )
    .execute(&su)
    .await
    .unwrap();

    let (status, _h, failed) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval_id,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert!(
        status >= 500,
        "an injected fault is a server error: {status} {failed}"
    );
    assert!(
        channel_row_3706(&su, fixture.workspace, &name)
            .await
            .is_none(),
        "the channel row was rolled back"
    );
    assert_eq!(hosted_approved_3706(&su, &fixture).await, approved_before);
    for action in [
        "channel.created",
        "action.approved",
        "hosted_connection.channels_granted",
    ] {
        assert_eq!(
            audit_count_3706(&su, fixture.workspace, action).await,
            0,
            "{action}"
        );
    }
    let (state, run_state): (String, String) = sqlx::query_as(
        "SELECT a.status::text, r.status::text FROM approval a \
           JOIN agent_run r ON r.id = a.run_id WHERE a.id=$1",
    )
    .bind(approval_id)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(
        (state.as_str(), run_state.as_str()),
        ("pending", "awaiting_approval")
    );

    // The fault is cleared; the very same approval can now be decided.
    sqlx::query("DROP TRIGGER fail_membership_3706 ON membership")
        .execute(&su)
        .await
        .unwrap();
    let (status, _h, retried) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval_id,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{retried}");
    assert!(channel_row_3706(&su, fixture.workspace, &name)
        .await
        .is_some());
}

/// Stale or unsound proposals: unresolvable handles are the one
/// `InvalidArguments`; a name taken before the tap, and a connection already at
/// its ceiling, leave the approval pending with `action_args_invalid`.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_stale_or_unsound_channel_proposal_changes_nothing() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let approvals_before: i64 =
        sqlx::query_scalar("SELECT count(*) FROM approval WHERE workspace_id=$1")
            .bind(fixture.workspace)
            .fetch_one(&su)
            .await
            .unwrap();

    // An unknown handle, a malformed one, a deactivated member and an id all
    // fail the same way, and no approval row is written.
    let (gone, gone_handle) = seed_extra_member_3706(&su, &fixture, "gone").await;
    sqlx::query("UPDATE member SET status='suspended' WHERE id=$1")
        .bind(gone)
        .execute(&su)
        .await
        .unwrap_or_else(|_| panic!("deactivate"));
    let mut codes = Vec::new();
    for args in [
        json!({"name": "ok-name", "memberHandles": ["nobody-here"]}),
        json!({"name": "ok-name", "memberHandles": ["Not A Handle"]}),
        json!({"name": "ok-name", "memberHandles": [gone_handle]}),
        json!({"name": "ok-name", "memberHandles": [Uuid::new_v4().to_string()]}),
        json!({"name": "UPPER CASE"}),
    ] {
        let (status, refused) = try_propose_action_3706(
            &client,
            &base,
            &su,
            &fixture,
            "channel.create",
            args.clone(),
        )
        .await;
        codes.push((status, error_code(&refused)));
        assert_eq!(status, 400, "{args}: {refused}");
    }
    assert!(codes.windows(2).all(|pair| pair[0] == pair[1]), "{codes:?}");
    assert_eq!(
        sqlx::query_scalar::<_, i64>("SELECT count(*) FROM approval WHERE workspace_id=$1")
            .bind(fixture.workspace)
            .fetch_one(&su)
            .await
            .unwrap(),
        approvals_before
    );

    // `addProposer: false` while listing the proposer itself would make the card
    // contradict itself: refused like any other unresolvable proposal.
    let agent_handle = format!("agent-{}", &Uuid::new_v4().simple().to_string()[..8]);
    sqlx::query("UPDATE member SET handle=$2 WHERE id=$1")
        .bind(fixture.hosted_agent)
        .bind(&agent_handle)
        .execute(&su)
        .await
        .unwrap();
    let (status, refused) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "channel.create",
        json!({"name": "self-ref", "addProposer": false, "memberHandles": [agent_handle]}),
    )
    .await;
    assert_eq!(status, 400, "{refused}");

    // A name that already exists (even a private channel the agent cannot see)
    // does NOT fail the proposal — that would be an existence oracle — but the
    // tap is refused as stale and the approval stays pending.
    let taken = format!("taken-{}", &Uuid::new_v4().simple().to_string()[..8]);
    let existing = Uuid::new_v4();
    sqlx::query(
        "INSERT INTO channel(id, workspace_id, kind, name, created_by) \
         VALUES($1,$2,'private',$3,$4)",
    )
    .bind(existing)
    .bind(fixture.workspace)
    .bind(&taken)
    .bind(fixture.human)
    .execute(&su)
    .await
    .unwrap();
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "channel.create",
        json!({"name": taken}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval_id = proposed_approval_3706(&proposed);
    let (status, _h, stale) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval_id,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{stale}");
    assert_eq!(stale["status"], "action_args_invalid");
    let count: i64 =
        sqlx::query_scalar("SELECT count(*) FROM channel WHERE workspace_id=$1 AND lower(name)=$2")
            .bind(fixture.workspace)
            .bind(&taken)
            .fetch_one(&su)
            .await
            .unwrap();
    assert_eq!(count, 1, "no second channel");
    let state: String = sqlx::query_scalar("SELECT status::text FROM approval WHERE id=$1")
        .bind(approval_id)
        .fetch_one(&su)
        .await
        .unwrap();
    assert_eq!(state, "pending");

    // A connection already at the 50-channel ceiling cannot take one more.
    let name = format!("fifty-{}", &Uuid::new_v4().simple().to_string()[..8]);
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "channel.create",
        json!({"name": name}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    sqlx::query(
        "UPDATE hosted_agent_connection SET approved_channel_ids = \
            ARRAY(SELECT gen_random_uuid() FROM generate_series(1,50)) WHERE id=$1",
    )
    .bind(fixture.hosted_connection)
    .execute(&su)
    .await
    .unwrap();
    let (status, _h, capped) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        proposed_approval_3706(&proposed),
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{capped}");
    assert_eq!(capped["status"], "action_args_invalid");
    assert!(channel_row_3706(&su, fixture.workspace, &name)
        .await
        .is_none());
    assert_eq!(hosted_approved_3706(&su, &fixture).await.len(), 50);
}

// ---------------------------------------------------------------------------
// ADR-0186 증보 2026-10-11 S2 (#3707) — channel.member.add
// ---------------------------------------------------------------------------

/// A channel made by the fixture's human, with `members` seated (role `member`
/// unless named otherwise).
async fn seed_channel_3707(
    pool: &PgPool,
    fixture: &Fixture,
    kind: &str,
    members: &[(Uuid, &str)],
) -> (Uuid, String) {
    let channel = Uuid::new_v4();
    let name = format!("room-{}", &channel.simple().to_string()[..10]);
    sqlx::query(
        "INSERT INTO channel(id, workspace_id, kind, name, created_by) \
         VALUES($1,$2,$3::channel_kind,$4,$5)",
    )
    .bind(channel)
    .bind(fixture.workspace)
    .bind(kind)
    .bind(&name)
    .bind(fixture.human)
    .execute(pool)
    .await
    .expect("seed channel");
    sqlx::query("INSERT INTO channel_seq(channel_id, workspace_id, last_seq) VALUES($1,$2,0)")
        .bind(channel)
        .bind(fixture.workspace)
        .execute(pool)
        .await
        .expect("seed channel seq");
    sqlx::query(
        "INSERT INTO membership(workspace_id, channel_id, member_id, role) \
         VALUES($1,$2,$3,'owner')",
    )
    .bind(fixture.workspace)
    .bind(channel)
    .bind(fixture.human)
    .execute(pool)
    .await
    .expect("seed owner");
    for (member, role) in members {
        sqlx::query(
            "INSERT INTO membership(workspace_id, channel_id, member_id, role) \
             VALUES($1,$2,$3,$4::membership_role)",
        )
        .bind(fixture.workspace)
        .bind(channel)
        .bind(member)
        .bind(role)
        .execute(pool)
        .await
        .expect("seed member");
    }
    (channel, name)
}

async fn membership_role_3707(pool: &PgPool, channel: Uuid, member: Uuid) -> Option<String> {
    sqlx::query_scalar(
        "SELECT role::text FROM membership WHERE channel_id=$1 AND member_id=$2 AND left_at IS NULL",
    )
    .bind(channel)
    .bind(member)
    .fetch_optional(pool)
    .await
    .expect("membership role")
}

/// **channel.member.add (증보 V1-b, V6, V11).**
///
/// Visible = public, or private with the agent as a live member. Anything else
/// is one indistinguishable `InvalidArguments`. Approving seats the new members
/// as `member` only — an existing channel admin is skipped, never demoted — and
/// a proposal gone stale (the agent left the room) is refused with the approval
/// still pending.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn an_approved_member_add_seats_members_in_a_channel_the_agent_can_see() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let plain_jwt = seed_plain_member(&su, &fixture).await;
    let (x1, x1_handle) = seed_extra_member_3706(&su, &fixture, "one").await;
    let (x2, x2_handle) = seed_extra_member_3706(&su, &fixture, "two").await;
    let (y, y_handle) = seed_extra_member_3706(&su, &fixture, "adm").await;

    // P: private, the agent is in it, `y` is already its channel admin.
    let (p, p_name) = seed_channel_3707(
        &su,
        &fixture,
        "private",
        &[(fixture.hosted_agent, "member"), (y, "admin")],
    )
    .await;
    // Q: public, the agent is not in it. R: private, the agent is not in it.
    let (q, q_name) = seed_channel_3707(&su, &fixture, "public", &[]).await;
    let (_r, r_name) = seed_channel_3707(&su, &fixture, "private", &[]).await;

    // ---- P: card, gate, execution -----------------------------------------
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "channel.member.add",
        json!({"channel": format!("#{}", p_name.to_uppercase()), "memberHandles": [x1_handle, y_handle]}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval_p = proposed_approval_3706(&proposed);
    let card: Value = sqlx::query_scalar("SELECT props FROM message WHERE id=$1")
        .bind(Uuid::parse_str(structured(&proposed)["cardMessageId"].as_str().unwrap()).unwrap())
        .fetch_one(&su)
        .await
        .unwrap();
    let rows = card["action"]["rows"].as_array().unwrap().clone();
    let row = |label: &str| {
        rows.iter()
            .find(|row| row["label"] == label)
            .unwrap_or_else(|| panic!("no {label} row in {rows:?}"))["value"]
            .as_str()
            .unwrap()
            .to_string()
    };
    assert_eq!(
        row("채널"),
        format!("#{p_name}"),
        "the server's name, not the agent's spelling"
    );
    assert_eq!(row("공개 범위"), "비공개");
    assert_eq!(row("현재 인원"), "3명");
    assert_eq!(
        row("추가할 멤버"),
        format!("Extra one (@{x1_handle})"),
        "only the new member is listed, by name and handle"
    );
    assert_eq!(row("이미 있는 멤버"), "1명");

    let (status, _h, refused) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &plain_jwt,
        approval_p,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 403, "{refused}");
    assert_eq!(refused["status"], "role_required");
    assert_eq!(membership_role_3707(&su, p, x1).await, None);

    let (status, _h, approved) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval_p,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(approved["result"]["actionId"], json!("channel.member.add"));
    assert_eq!(
        approved["result"]["ref"],
        json!({"type": "channel", "id": p.to_string()})
    );
    assert!(approved["result"].get("secretOnce").is_none());
    assert_eq!(
        membership_role_3707(&su, p, x1).await.as_deref(),
        Some("member")
    );
    assert_eq!(
        membership_role_3707(&su, p, y).await.as_deref(),
        Some("admin"),
        "an existing channel admin is skipped, never demoted"
    );
    assert_eq!(
        audit_count_3706(&su, fixture.workspace, "channel.member_added").await,
        1,
        "one row per member actually seated"
    );
    let detail: Value = sqlx::query_scalar(
        "SELECT detail FROM audit_log WHERE workspace_id=$1 AND action='channel.member_added'",
    )
    .bind(fixture.workspace)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(detail["role"], json!("member"));
    assert_eq!(detail["via_agent"], json!(fixture.hosted_agent.to_string()));
    assert_eq!(detail["approval_id"], json!(approval_p.to_string()));

    // ---- Q: a public channel is visible without membership ----------------
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "channel.member.add",
        json!({"channel": q_name, "memberHandles": [x2_handle]}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let (status, _h, approved) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        proposed_approval_3706(&proposed),
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(
        membership_role_3707(&su, q, x2).await.as_deref(),
        Some("member")
    );
    assert_eq!(
        membership_role_3707(&su, q, fixture.hosted_agent).await,
        None,
        "adding someone else does not seat the agent, and does not widen its approved set"
    );

    // ---- invisible channels are all the same refusal ----------------------
    let other_ws = Uuid::new_v4();
    sqlx::query("INSERT INTO workspace(id, slug, name) VALUES($1,$2,$2)")
        .bind(other_ws)
        .bind(format!("other-{}", other_ws.simple()))
        .execute(&su)
        .await
        .unwrap();
    let foreign_name = format!("foreign-{}", &other_ws.simple().to_string()[..8]);
    let foreign_owner = Uuid::new_v4();
    sqlx::query(
        "INSERT INTO member(id, workspace_id, kind, display_name, handle) \
         VALUES($1,$2,'human','F','foreign-owner')",
    )
    .bind(foreign_owner)
    .bind(other_ws)
    .execute(&su)
    .await
    .unwrap();
    sqlx::query(
        "INSERT INTO channel(workspace_id, kind, name, created_by) VALUES($1,'public',$2,$3)",
    )
    .bind(other_ws)
    .bind(&foreign_name)
    .bind(foreign_owner)
    .execute(&su)
    .await
    .unwrap();
    let archived = {
        let (id, name) = seed_channel_3707(&su, &fixture, "public", &[]).await;
        sqlx::query("UPDATE channel SET archived_at = now() WHERE id=$1")
            .bind(id)
            .execute(&su)
            .await
            .unwrap();
        name
    };
    let approvals_before: i64 =
        sqlx::query_scalar("SELECT count(*) FROM approval WHERE workspace_id=$1")
            .bind(fixture.workspace)
            .fetch_one(&su)
            .await
            .unwrap();
    let mut answers = Vec::new();
    for channel in [r_name, "no-such-room".to_string(), foreign_name, archived] {
        let (status, refused) = try_propose_action_3706(
            &client,
            &base,
            &su,
            &fixture,
            "channel.member.add",
            json!({"channel": channel, "memberHandles": [x1_handle]}),
        )
        .await;
        answers.push((status, refused["error"].clone()));
    }
    assert!(
        answers
            .iter()
            .all(|answer| answer.0 == 400 && answer.1 == answers[0].1),
        "an unseen channel must look exactly like a missing one: {answers:?}"
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>("SELECT count(*) FROM approval WHERE workspace_id=$1")
            .bind(fixture.workspace)
            .fetch_one(&su)
            .await
            .unwrap(),
        approvals_before
    );

    // ---- stale: the agent leaves the private room before the tap ----------
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "channel.member.add",
        json!({"channel": p_name, "memberHandles": [x2_handle]}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval_stale = proposed_approval_3706(&proposed);
    sqlx::query("UPDATE membership SET left_at = now() WHERE channel_id=$1 AND member_id=$2")
        .bind(p)
        .bind(fixture.hosted_agent)
        .execute(&su)
        .await
        .unwrap();
    let (status, _h, stale) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval_stale,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{stale}");
    assert_eq!(stale["status"], "action_args_invalid");
    assert_eq!(membership_role_3707(&su, p, x2).await, None);
    let state: String = sqlx::query_scalar("SELECT status::text FROM approval WHERE id=$1")
        .bind(approval_stale)
        .fetch_one(&su)
        .await
        .unwrap();
    assert_eq!(state, "pending");
}

/// **What the approver read is what runs (증보 V1-d, pins).**
///
/// A handle can be changed and a channel can be renamed after the card is drawn,
/// so "the same name resolves again" is not enough: the ids the names resolved to
/// are pinned in the payload and a different id at the tap is `action_args_invalid`
/// with nothing written. Also: an agent target is marked on the card, a proposal
/// with nobody new to add is refused, and unseen channels (DM, left room,
/// archived twin) look exactly like a missing one without writing a card or an
/// audit row.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_member_add_card_is_pinned_to_the_ids_it_was_drawn_from() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (x2, x2_handle) = seed_extra_member_3706(&su, &fixture, "pin").await;
    let (x3, _x3_handle) = seed_extra_member_3706(&su, &fixture, "swap").await;
    let (p, p_name) = seed_channel_3707(
        &su,
        &fixture,
        "private",
        &[(fixture.hosted_agent, "member")],
    )
    .await;

    // ---- a handle moved to somebody else after the card was drawn ----------
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "channel.member.add",
        json!({"channel": p_name, "memberHandles": [x2_handle]}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval = proposed_approval_3706(&proposed);
    sqlx::query("UPDATE member SET handle=$2 WHERE id=$1")
        .bind(x2)
        .bind(format!("moved-{}", &x2.simple().to_string()[..8]))
        .execute(&su)
        .await
        .unwrap();
    sqlx::query("UPDATE member SET handle=$2 WHERE id=$1")
        .bind(x3)
        .bind(&x2_handle)
        .execute(&su)
        .await
        .unwrap();
    let (status, _h, stale) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{stale}");
    assert_eq!(stale["status"], "action_args_invalid");
    assert_eq!(
        membership_role_3707(&su, p, x3).await,
        None,
        "the swapped-in member"
    );
    assert_eq!(membership_role_3707(&su, p, x2).await, None);

    // ---- a channel renamed away and its name reused ------------------------
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "channel.member.add",
        json!({"channel": p_name, "memberHandles": [x2_handle]}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval = proposed_approval_3706(&proposed);
    let (decoy, _) = seed_channel_3707(
        &su,
        &fixture,
        "private",
        &[(fixture.hosted_agent, "member")],
    )
    .await;
    sqlx::query("UPDATE channel SET name=$2 WHERE id=$1")
        .bind(p)
        .bind(format!("renamed-{}", &p.simple().to_string()[..8]))
        .execute(&su)
        .await
        .unwrap();
    sqlx::query("UPDATE channel SET name=$2 WHERE id=$1")
        .bind(decoy)
        .bind(&p_name)
        .execute(&su)
        .await
        .unwrap();
    let (status, _h, stale) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{stale}");
    assert_eq!(stale["status"], "action_args_invalid");
    assert_eq!(membership_role_3707(&su, decoy, x3).await, None);

    // ---- an agent as the member to add is marked on the card ---------------
    let agent_handle = format!("bot-{}", &Uuid::new_v4().simple().to_string()[..8]);
    sqlx::query("UPDATE member SET handle=$2 WHERE id=$1")
        .bind(fixture.managed_agent)
        .bind(&agent_handle)
        .execute(&su)
        .await
        .unwrap();
    sqlx::query(
        "INSERT INTO workspace_membership(workspace_id, member_id, role) VALUES($1,$2,'member') \
         ON CONFLICT DO NOTHING",
    )
    .bind(fixture.workspace)
    .bind(fixture.managed_agent)
    .execute(&su)
    .await
    .unwrap();
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "channel.member.add",
        json!({"channel": p_name, "memberHandles": [agent_handle]}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let card: Value = sqlx::query_scalar("SELECT props FROM message WHERE id=$1")
        .bind(Uuid::parse_str(structured(&proposed)["cardMessageId"].as_str().unwrap()).unwrap())
        .fetch_one(&su)
        .await
        .unwrap();
    let shown = card["action"]["rows"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["label"] == "추가할 멤버")
        .unwrap()["value"]
        .as_str()
        .unwrap()
        .to_string();
    assert!(
        shown.contains("에이전트") && shown.contains(&agent_handle),
        "{shown}"
    );

    // ---- unseen channels write nothing and look like a missing one ---------
    let dm = Uuid::new_v4();
    let dm_name = format!("dm-{}", &dm.simple().to_string()[..10]);
    sqlx::query(
        "INSERT INTO channel(id, workspace_id, kind, name, dm_key, created_by) \
         VALUES($1,$2,'dm',$3,$4,$5)",
    )
    .bind(dm)
    .bind(fixture.workspace)
    .bind(&dm_name)
    .bind(format!("{dm}"))
    .bind(fixture.human)
    .execute(&su)
    .await
    .expect("seed dm");
    sqlx::query("INSERT INTO membership(workspace_id, channel_id, member_id) VALUES($1,$2,$3)")
        .bind(fixture.workspace)
        .bind(dm)
        .bind(fixture.hosted_agent)
        .execute(&su)
        .await
        .unwrap();
    let (left_room, left_name) = seed_channel_3707(
        &su,
        &fixture,
        "private",
        &[(fixture.hosted_agent, "member")],
    )
    .await;
    sqlx::query("UPDATE membership SET left_at=now() WHERE channel_id=$1 AND member_id=$2")
        .bind(left_room)
        .bind(fixture.hosted_agent)
        .execute(&su)
        .await
        .unwrap();
    let twin = format!("twin-{}", &Uuid::new_v4().simple().to_string()[..8]);
    for archived in [true, false] {
        let id = Uuid::new_v4();
        sqlx::query(
            "INSERT INTO channel(id, workspace_id, kind, name, created_by, archived_at) \
             VALUES($1,$2,'private',$3,$4, CASE WHEN $5 THEN now() END)",
        )
        .bind(id)
        .bind(fixture.workspace)
        .bind(&twin)
        .bind(fixture.human)
        .bind(archived)
        .execute(&su)
        .await
        .unwrap();
        if !archived {
            // The live twin is private and the agent is not in it.
            continue;
        }
    }
    let count_state = |su: PgPool, ws: Uuid| async move {
        let rows: (i64, i64, i64) = sqlx::query_as(
            "SELECT (SELECT count(*) FROM approval WHERE workspace_id=$1), \
                    (SELECT count(*) FROM message WHERE workspace_id=$1 AND type::text='approval_request'), \
                    (SELECT count(*) FROM audit_log WHERE workspace_id=$1 AND action IN \
                       ('action.approved','channel.member_added','channel.created',\
                        'hosted_connection.channels_granted'))",
        )
        .bind(ws)
        .fetch_one(&su)
        .await
        .unwrap();
        rows
    };
    let before = count_state(su.clone(), fixture.workspace).await;
    let mut answers = Vec::new();
    for channel in [dm_name, left_name, twin, "no-such-room-at-all".to_string()] {
        let (status, refused) = try_propose_action_3706(
            &client,
            &base,
            &su,
            &fixture,
            "channel.member.add",
            json!({"channel": channel, "memberHandles": [x2_handle]}),
        )
        .await;
        answers.push((status, refused["error"].clone()));
    }
    assert!(
        answers.iter().all(|a| a.0 == 400 && a.1 == answers[0].1),
        "{answers:?}"
    );
    assert_eq!(count_state(su.clone(), fixture.workspace).await, before);

    // ---- nobody new to add is not a proposal -------------------------------
    sqlx::query("INSERT INTO membership(workspace_id, channel_id, member_id) VALUES($1,$2,$3)")
        .bind(fixture.workspace)
        .bind(decoy)
        .bind(x3)
        .execute(&su)
        .await
        .unwrap();
    let x3_handle: String = sqlx::query_scalar("SELECT handle FROM member WHERE id=$1")
        .bind(x3)
        .fetch_one(&su)
        .await
        .unwrap();
    let (status, refused) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "channel.member.add",
        json!({"channel": p_name, "memberHandles": [x3_handle]}),
    )
    .await;
    assert_eq!(status, 400, "{refused}");
}

// ---------------------------------------------------------------------------
// ADR-0186 증보 2026-10-11 S3 (#3708) — agent.rename + PATCH …/agents/{agent}
// ---------------------------------------------------------------------------

/// A human with a session token, a workspace role and a seat in the fixture's
/// approved channel (so it can decide approvals raised there).
async fn seed_human_3708(
    pool: &PgPool,
    fixture: &Fixture,
    tag: &str,
    role: &str,
) -> (Uuid, String) {
    let member = Uuid::new_v4();
    sqlx::query(
        "INSERT INTO member(id, workspace_id, kind, display_name, handle) \
         VALUES($1,$2,'human',$3,$4)",
    )
    .bind(member)
    .bind(fixture.workspace)
    .bind(format!("Person {tag}"))
    .bind(format!("{tag}-{}", &member.simple().to_string()[..8]))
    .execute(pool)
    .await
    .expect("seed person");
    sqlx::query(
        "INSERT INTO human(member_id, workspace_id, email, email_verified) VALUES($1,$2,$3,true)",
    )
    .bind(member)
    .bind(fixture.workspace)
    .bind(format!("{member}@tools.test"))
    .execute(pool)
    .await
    .expect("seed person identity");
    sqlx::query(
        "INSERT INTO workspace_membership(workspace_id, member_id, role) \
         VALUES($1,$2,$3::membership_role)",
    )
    .bind(fixture.workspace)
    .bind(member)
    .bind(role)
    .execute(pool)
    .await
    .expect("seed person role");
    sqlx::query("INSERT INTO membership(workspace_id, channel_id, member_id) VALUES($1,$2,$3)")
        .bind(fixture.workspace)
        .bind(fixture.channel)
        .bind(member)
        .execute(pool)
        .await
        .expect("seed person seat");
    let jwt = momo_auth::sign_access(member, fixture.workspace, &[], TEST_JWT_SECRET)
        .expect("sign person JWT")
        .token;
    sqlx::query(
        "INSERT INTO token(workspace_id, kind, actor_member_id, token_hash, scopes, label) \
         VALUES($1,'session',$2,digest($3::text,'sha256'),ARRAY[]::text[],'tools-conformance')",
    )
    .bind(fixture.workspace)
    .bind(member)
    .bind(&jwt)
    .execute(pool)
    .await
    .expect("record person token");
    (member, jwt)
}

async fn set_agent_owner_3708(pool: &PgPool, agent: Uuid, owner: Option<Uuid>) {
    sqlx::query("UPDATE agent SET owner_human_id=$2 WHERE member_id=$1")
        .bind(agent)
        .bind(owner)
        .execute(pool)
        .await
        .expect("set owner");
}

/// Give an agent a legal short handle and display name (the fixture's are the
/// long generated ones) and return the handle.
async fn tidy_agent_3708(pool: &PgPool, agent: Uuid, display: &str) -> String {
    let handle = format!("bot-{}", &agent.simple().to_string()[..8]);
    sqlx::query("UPDATE member SET handle=$2, display_name=$3 WHERE id=$1")
        .bind(agent)
        .bind(&handle)
        .bind(display)
        .execute(pool)
        .await
        .expect("tidy agent");
    handle
}

async fn display_name_3708(pool: &PgPool, member: Uuid) -> String {
    sqlx::query_scalar("SELECT display_name FROM member WHERE id=$1")
        .bind(member)
        .fetch_one(pool)
        .await
        .expect("display name")
}

async fn approval_status_3708(pool: &PgPool, approval: Uuid) -> String {
    sqlx::query_scalar("SELECT status::text FROM approval WHERE id=$1")
        .bind(approval)
        .fetch_one(pool)
        .await
        .expect("approval status")
}

/// **agent.rename for oneself (증보 V4).** The approver is the agent's *owner*
/// (not an admin) and the approval executes; a third party who is neither the
/// owner nor an admin is `role_required`; the strict guard refuses every hostile
/// spelling; handle and every other member's name stay put; the broadcast and
/// audit rows are written; the name collision rule covers display names AND
/// handles under disguise.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn an_agent_renames_itself_after_its_owner_approves() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (owner, owner_jwt) = seed_human_3708(&su, &fixture, "owner", "member").await;
    let (_third, third_jwt) = seed_human_3708(&su, &fixture, "third", "member").await;
    set_agent_owner_3708(&su, fixture.hosted_agent, Some(owner)).await;
    let _agent_handle = tidy_agent_3708(&su, fixture.hosted_agent, "Hermes").await;
    let before_other = display_name_3708(&su, fixture.managed_agent).await;
    let handle_before: String = sqlx::query_scalar("SELECT handle FROM member WHERE id=$1")
        .bind(fixture.hosted_agent)
        .fetch_one(&su)
        .await
        .unwrap();

    // ---- the hostile spellings, all one refusal ----------------------------
    let human_name = display_name_3708(&su, fixture.human).await;
    let mut answers = Vec::new();
    for hostile in [
        "[보안 재인증](https://evil.example)".to_string(),
        "@Person owner".to_string(),
        "<@Person owner>".to_string(),
        "Zero\u{200B}Width".to_string(),
        "admin".to_string(),
        "oort".to_string(),
        "x".repeat(40),
        // Someone else's name, handle, case, width and look-alike variants.
        human_name.to_lowercase(),
        human_name.to_uppercase(),
        "Ｐｅｒｓｏｎ ｏｗｎｅｒ".to_string(),
        "Pеrson owner".to_string(), // Cyrillic е
        before_other.clone(),
        before_other.to_uppercase(),
        // Reserved words anywhere, ASCII look-alikes, and a whole-word prefix of
        // another member's name (`@Tools Human` would also mention "Tools").
        "Admin 2".to_string(),
        "Adm1n".to_string(),
        "Oort Support".to_string(),
        "Tools".to_string(),
        "Tools Human Bot".to_string(),
        "T00ls Human".to_string(),
    ] {
        let (status, refused) = try_propose_action_3706(
            &client,
            &base,
            &su,
            &fixture,
            "agent.rename",
            json!({"displayName": hostile}),
        )
        .await;
        answers.push((status, refused["error"].clone()));
        assert_eq!(status, 400, "{hostile:?} must be refused: {refused}");
    }
    assert!(answers.iter().all(|a| a.1 == answers[0].1), "{answers:?}");
    assert_eq!(display_name_3708(&su, fixture.hosted_agent).await, "Hermes");

    // ---- a good proposal ---------------------------------------------------
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.rename",
        json!({"displayName": "Navigator 🧭"}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval = proposed_approval_3706(&proposed);
    let card: Value = sqlx::query_scalar("SELECT props FROM message WHERE id=$1")
        .bind(Uuid::parse_str(structured(&proposed)["cardMessageId"].as_str().unwrap()).unwrap())
        .fetch_one(&su)
        .await
        .unwrap();
    assert_eq!(card["action"]["required_role"], json!("agent_editor"));
    let rows = card["action"]["rows"].as_array().unwrap().clone();
    let row = |label: &str| {
        rows.iter().find(|r| r["label"] == label).unwrap()["value"]
            .as_str()
            .unwrap()
            .to_string()
    };
    assert!(row("대상 에이전트").contains("Hermes") && row("대상 에이전트").contains("에이전트"));
    assert_eq!(row("이름 변경"), "Hermes → Navigator 🧭");
    assert!(
        !card["summary"].as_str().unwrap().contains("다른 에이전트"),
        "a self-rename does not claim to rename another agent"
    );

    // ---- a third party who is neither the owner nor an admin ---------------
    let (status, _h, refused) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &third_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 403, "{refused}");
    assert_eq!(refused["status"], "role_required");
    assert_eq!(display_name_3708(&su, fixture.hosted_agent).await, "Hermes");
    assert_eq!(approval_status_3708(&su, approval).await, "pending");

    // ---- the agent cannot approve its own rename ---------------------------
    let agent_try = client
        .post(format!(
            "{base}/v1/workspaces/{}/approvals/{approval}/decision",
            fixture.workspace
        ))
        .bearer_auth(&fixture.hosted_bearer)
        .json(&json!({"approvalId": approval, "approve": true,
                      "clientDecisionId": Uuid::new_v4()}))
        .send()
        .await
        .expect("agent decision responds");
    assert!(matches!(agent_try.status().as_u16(), 401 | 403));
    assert_eq!(display_name_3708(&su, fixture.hosted_agent).await, "Hermes");

    // ---- the OWNER (not an admin) approves ---------------------------------
    let (status, _h, approved) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &owner_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(approved["result"]["actionId"], json!("agent.rename"));
    assert_eq!(
        approved["result"]["ref"],
        json!({"type": "agent", "id": fixture.hosted_agent.to_string()})
    );
    assert!(approved["result"].get("secretOnce").is_none());
    assert_eq!(
        display_name_3708(&su, fixture.hosted_agent).await,
        "Navigator 🧭"
    );
    let handle_after: String = sqlx::query_scalar("SELECT handle FROM member WHERE id=$1")
        .bind(fixture.hosted_agent)
        .fetch_one(&su)
        .await
        .unwrap();
    assert_eq!(handle_after, handle_before, "the handle is never renamed");
    assert_eq!(
        display_name_3708(&su, fixture.managed_agent).await,
        before_other
    );

    let detail: Value = sqlx::query_scalar(
        "SELECT detail FROM audit_log WHERE workspace_id=$1 AND action='member.renamed'",
    )
    .bind(fixture.workspace)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(detail["old"], json!("Hermes"));
    assert_eq!(detail["new"], json!("Navigator 🧭"));
    assert_eq!(detail["kind"], json!("agent"));
    assert_eq!(detail["managed"], json!(false));
    assert_eq!(detail["via_agent"], json!(fixture.hosted_agent.to_string()));
    assert_eq!(detail["approval_id"], json!(approval.to_string()));
    assert_eq!(
        audit_count_3706(&su, fixture.workspace, "action.approved").await,
        1
    );

    let broadcasts: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM outbox WHERE workspace_id=$1 \
           AND payload->'data'->>'type' = 'member.renamed' \
           AND payload->'data'->'payload'->>'member_id' = upper($2)",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent.to_string())
    .fetch_one(&su)
    .await
    .unwrap();
    let channels: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM membership WHERE member_id=$1 AND left_at IS NULL",
    )
    .bind(fixture.hosted_agent)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(
        broadcasts, channels,
        "one roster broadcast per channel the agent is in"
    );
    assert!(broadcasts > 0);

    // ---- the same name again is a no-op, not an error (own current name) ---
    let (status, again) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.rename",
        json!({"displayName": "navigator 🧭"}),
    )
    .await;
    assert_eq!(
        status, 200,
        "an agent may propose its own current name: {again}"
    );
}

/// **Managing another agent (증보 V4-M).** Only an active agent with the same,
/// non-NULL, active human owner is a target; everything else is one refusal. The
/// approver is judged against the TARGET: a person who owns only the proposer is
/// `role_required`. A target whose owner changed after the card was drawn is
/// stale. A second pending rename of the same target is a conflict, and
/// concurrent renames are serialised by the workspace display-name lock.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn an_agent_can_rename_only_agents_with_the_same_owner() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app.clone(), true).await;
    let client = reqwest::Client::new();
    let (owner, owner_jwt) = seed_human_3708(&su, &fixture, "owner", "member").await;
    let (other, other_jwt) = seed_human_3708(&su, &fixture, "other", "member").await;
    let _a = tidy_agent_3708(&su, fixture.hosted_agent, "Alpha").await;
    let b_handle = tidy_agent_3708(&su, fixture.managed_agent, "Beta").await;
    let c_handle = tidy_agent_3708(&su, fixture.connect_only_agent, "Gamma").await;
    set_agent_owner_3708(&su, fixture.hosted_agent, Some(owner)).await;
    set_agent_owner_3708(&su, fixture.managed_agent, Some(owner)).await;
    set_agent_owner_3708(&su, fixture.connect_only_agent, Some(other)).await;
    let human_handle: String = sqlx::query_scalar("SELECT handle FROM member WHERE id=$1")
        .bind(fixture.human)
        .fetch_one(&su)
        .await
        .unwrap();

    // ---- targets that are not managed all look the same --------------------
    let mut answers = Vec::new();
    for target in [
        c_handle.clone(),     // another owner
        human_handle.clone(), // a human
        "no-such-handle".to_string(),
        "Not A Handle".to_string(),
    ] {
        let (status, refused) = try_propose_action_3706(
            &client,
            &base,
            &su,
            &fixture,
            "agent.rename",
            json!({"displayName": "Renamed", "targetHandle": target}),
        )
        .await;
        assert_eq!(status, 400, "{target}: {refused}");
        answers.push(refused["error"].clone());
    }
    // An ownerless target is not managed either.
    set_agent_owner_3708(&su, fixture.managed_agent, None).await;
    let (status, refused) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.rename",
        json!({"displayName": "Renamed", "targetHandle": b_handle}),
    )
    .await;
    assert_eq!(status, 400, "{refused}");
    answers.push(refused["error"].clone());
    set_agent_owner_3708(&su, fixture.managed_agent, Some(owner)).await;
    // The proposer cannot take its own name onto the target.
    let (status, refused) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.rename",
        json!({"displayName": "alpha", "targetHandle": b_handle}),
    )
    .await;
    assert_eq!(status, 400, "{refused}");
    answers.push(refused["error"].clone());
    assert!(answers.iter().all(|a| *a == answers[0]), "{answers:?}");

    // ---- a managed target ---------------------------------------------------
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.rename",
        json!({"displayName": "Beta Prime", "targetHandle": b_handle}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval = proposed_approval_3706(&proposed);
    let card: Value = sqlx::query_scalar("SELECT props FROM message WHERE id=$1")
        .bind(Uuid::parse_str(structured(&proposed)["cardMessageId"].as_str().unwrap()).unwrap())
        .fetch_one(&su)
        .await
        .unwrap();
    assert!(
        card["summary"].as_str().unwrap().contains("다른 에이전트"),
        "the card says it renames ANOTHER agent: {card}"
    );
    let rows = card["action"]["rows"].as_array().unwrap();
    assert!(rows
        .iter()
        .any(|r| r["label"] == "이름 변경" && r["value"] == "Beta → Beta Prime"));

    // A second pending rename of the same target is a conflict.
    let (status, dup) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.rename",
        json!({"displayName": "Beta Again", "targetHandle": b_handle}),
    )
    .await;
    assert_eq!(status, 409, "{dup}");

    // The owner of the PROPOSER only is not an approver once the target moved:
    // the target changes hands, `other` (neither owner nor admin) tries, then
    // the real new owner is judged against the target and the card is stale.
    set_agent_owner_3708(&su, fixture.managed_agent, Some(other)).await;
    let (status, _h, refused) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &owner_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 403, "owns the proposer, not the target: {refused}");
    assert_eq!(refused["status"], "role_required");
    assert_eq!(display_name_3708(&su, fixture.managed_agent).await, "Beta");
    // The target's new owner is eligible, but the relationship the card was
    // drawn from no longer holds: stale, nothing spent.
    let (status, _h, stale) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &other_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    // A non-admin is told only `role_required` while the card is unresolvable.
    assert_eq!(status, 403, "{stale}");
    assert_eq!(stale["status"], "role_required");
    // An admin sees the truth: the proposal is stale.
    let (status, _h, stale) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{stale}");
    assert_eq!(stale["status"], "action_args_invalid");
    assert_eq!(approval_status_3708(&su, approval).await, "pending");
    assert_eq!(display_name_3708(&su, fixture.managed_agent).await, "Beta");

    // ---- restore the relationship: the target's owner approves -------------
    set_agent_owner_3708(&su, fixture.managed_agent, Some(owner)).await;
    let (status, _h, approved) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &owner_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(
        display_name_3708(&su, fixture.managed_agent).await,
        "Beta Prime"
    );
    assert_eq!(display_name_3708(&su, fixture.hosted_agent).await, "Alpha");
    let detail: Value = sqlx::query_scalar(
        "SELECT detail FROM audit_log WHERE workspace_id=$1 AND action='member.renamed'",
    )
    .bind(fixture.workspace)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(detail["managed"], json!(true));
    assert_eq!(
        detail["target_agent"],
        json!(fixture.managed_agent.to_string())
    );
    assert_eq!(detail["owner_member_id"], json!(owner.to_string()));
    assert_eq!(detail["via_agent"], json!(fixture.hosted_agent.to_string()));
}

/// The workspace display-name lock is real: while another transaction holds it,
/// an approved rename waits instead of racing the collision check.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn renames_are_serialised_by_the_workspace_display_name_lock() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let _a = tidy_agent_3708(&su, fixture.hosted_agent, "Alpha").await;
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.rename",
        json!({"displayName": "Zeta"}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval = proposed_approval_3706(&proposed);

    let mut holder = su.begin().await.expect("holder transaction");
    momo_messaging::lock_display_name_namespace_in_tx(&mut holder, fixture.workspace)
        .await
        .expect("take the namespace lock");
    let (base2, jwt, workspace) = (base.clone(), fixture.human_jwt.clone(), fixture.workspace);
    let mut decision = tokio::spawn(async move {
        let client = reqwest::Client::new();
        decide_as(
            &client,
            &base2,
            workspace,
            &jwt,
            approval,
            true,
            Uuid::new_v4(),
        )
        .await
    });
    assert!(
        tokio::time::timeout(std::time::Duration::from_millis(900), &mut decision)
            .await
            .is_err(),
        "the rename ran while another transaction held the display-name lock"
    );
    assert_eq!(display_name_3708(&su, fixture.hosted_agent).await, "Alpha");
    holder.commit().await.expect("release the lock");
    let (status, _h, body) = decision.await.expect("decision task");
    assert_eq!(status, 200, "{body}");
    assert_eq!(display_name_3708(&su, fixture.hosted_agent).await, "Zeta");
}

/// **The human route (증보 V4).** Owner or admin only; the person's own choice
/// follows the join rule (parentheses allowed) but may not collide with another
/// member's name or handle; an agent bearer cannot use it; only agents can be
/// renamed through it.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn the_human_rename_route_is_for_the_owner_or_an_admin_only() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (owner, owner_jwt) = seed_human_3708(&su, &fixture, "owner", "member").await;
    let (_third, third_jwt) = seed_human_3708(&su, &fixture, "third", "member").await;
    set_agent_owner_3708(&su, fixture.hosted_agent, Some(owner)).await;
    let _ = tidy_agent_3708(&su, fixture.hosted_agent, "Hermes").await;
    let other_name = tidy_agent_3708(&su, fixture.managed_agent, "Managed One").await;
    let url = format!(
        "{base}/v1/workspaces/{}/agents/{}",
        fixture.workspace, fixture.hosted_agent
    );
    let patch = |jwt: &str, body: Value| client.patch(&url).bearer_auth(jwt).json(&body).send();

    // A third party: 403. An agent bearer: refused. Nothing changed.
    let response = patch(&third_jwt, json!({"displayName": "Hijack"}))
        .await
        .unwrap();
    assert_eq!(response.status().as_u16(), 403);
    let response = patch(&fixture.hosted_bearer, json!({"displayName": "Self"}))
        .await
        .unwrap();
    assert!(
        matches!(response.status().as_u16(), 401 | 403),
        "{}",
        response.status()
    );
    assert_eq!(display_name_3708(&su, fixture.hosted_agent).await, "Hermes");

    // A collision (another member's handle, name, disguise) is 409.
    for taken in [
        other_name.clone(),
        "managed one".to_string(),
        "ＭＡＮＡＧＥＤ ＯＮＥ".to_string(),
        "Mаnaged One".to_string(), // Cyrillic а
    ] {
        let response = patch(&owner_jwt, json!({"displayName": taken}))
            .await
            .unwrap();
        assert_eq!(response.status().as_u16(), 409, "{taken}");
    }
    // Invisible, reordering and line-breaking characters are refused even though
    // a person chose them.
    for hidden in ["Zero\u{200B}Width", "Flip\u{202E}ped", "two\nlines", "ㅤ"] {
        let response = patch(&owner_jwt, json!({"displayName": hidden}))
            .await
            .unwrap();
        assert_eq!(response.status().as_u16(), 400, "{hidden:?}");
    }
    // A non-admin cannot tell a human id or an unknown id from a real agent:
    // 403 for all three (the 404 is only for someone allowed to know).
    for target in [Uuid::new_v4(), fixture.human, fixture.managed_agent] {
        let response = client
            .patch(format!(
                "{base}/v1/workspaces/{}/agents/{target}",
                fixture.workspace
            ))
            .bearer_auth(&third_jwt)
            .json(&json!({"displayName": "Nope"}))
            .send()
            .await
            .unwrap();
        assert_eq!(response.status().as_u16(), 403, "{target}");
    }
    // Empty and unknown keys are 400/422, a human id is 404 for an admin.
    let response = patch(&owner_jwt, json!({"displayName": "   "}))
        .await
        .unwrap();
    assert_eq!(response.status().as_u16(), 400);
    let response = patch(
        &owner_jwt,
        json!({"displayName": "Ok", "handle": "newhandle"}),
    )
    .await
    .unwrap();
    assert!(matches!(response.status().as_u16(), 400 | 422));
    let human_url = format!(
        "{base}/v1/workspaces/{}/agents/{}",
        fixture.workspace, fixture.human
    );
    let response = client
        .patch(&human_url)
        .bearer_auth(&fixture.human_jwt)
        .json(&json!({"displayName": "Not An Agent"}))
        .send()
        .await
        .unwrap();
    assert_eq!(
        response.status().as_u16(),
        404,
        "a human is not renamable here"
    );
    assert_eq!(display_name_3708(&su, fixture.hosted_agent).await, "Hermes");

    // The owner (not an admin) renames it — the person's choice, parentheses and all.
    let response = patch(&owner_jwt, json!({"displayName": "  김 인턴 (비서)  "}))
        .await
        .unwrap();
    assert_eq!(response.status().as_u16(), 200);
    let body: Value = response.json().await.unwrap();
    assert_eq!(body["member"]["displayName"], json!("김 인턴 (비서)"));
    assert_eq!(body["member"]["kind"], json!("agent"));
    assert_eq!(
        display_name_3708(&su, fixture.hosted_agent).await,
        "김 인턴 (비서)"
    );
    // An admin may too; renaming to its own current name is allowed.
    let response = client
        .patch(&url)
        .bearer_auth(&fixture.human_jwt)
        .json(&json!({"displayName": "김 인턴 (비서)"}))
        .send()
        .await
        .unwrap();
    assert_eq!(response.status().as_u16(), 200);

    let detail: Value = sqlx::query_scalar(
        "SELECT detail FROM audit_log WHERE workspace_id=$1 AND action='member.renamed' \
          ORDER BY created_at LIMIT 1",
    )
    .bind(fixture.workspace)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(detail["kind"], json!("agent"));
    assert_eq!(detail["new"], json!("김 인턴 (비서)"));
}

// ---------------------------------------------------------------------------
// ADR-0186 증보 2026-10-11 S4 (#3709) — hosted.channels.grant
// ---------------------------------------------------------------------------

async fn approved_of_3709(pool: &PgPool, agent: Uuid) -> Vec<Uuid> {
    sqlx::query_scalar(
        "SELECT approved_channel_ids FROM hosted_agent_connection WHERE agent_member_id=$1",
    )
    .bind(agent)
    .fetch_one(pool)
    .await
    .expect("approved channels")
}

/// **hosted.channels.grant (증보 V5, V11).**
///
/// The only way an agent asks for more reach, and the narrowest one: its OWN
/// connection, channels it can already see (public, or private with it inside),
/// admin approval, a 50-channel ceiling, one indistinguishable refusal for
/// everything else. The confirm columns and every other agent's connection are
/// untouched; the grant also seats the agent, so it can actually post.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_channel_grant_widens_only_the_proposers_own_connection() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let plain_jwt = seed_plain_member(&su, &fixture).await;

    // Q: public, the agent is not in it. R: private, the agent IS in it.
    // S: private, the agent is not in it. D: a DM the agent is in.
    let (q, q_name) = seed_channel_3707(&su, &fixture, "public", &[]).await;
    let (r, r_name) = seed_channel_3707(
        &su,
        &fixture,
        "private",
        &[(fixture.hosted_agent, "member")],
    )
    .await;
    let (_s, s_name) = seed_channel_3707(&su, &fixture, "private", &[]).await;
    let dm = Uuid::new_v4();
    let dm_name = format!("dm-{}", &dm.simple().to_string()[..10]);
    sqlx::query(
        "INSERT INTO channel(id, workspace_id, kind, name, dm_key, created_by) \
         VALUES($1,$2,'dm',$3,$4,$5)",
    )
    .bind(dm)
    .bind(fixture.workspace)
    .bind(&dm_name)
    .bind(dm.to_string())
    .bind(fixture.human)
    .execute(&su)
    .await
    .unwrap();
    sqlx::query("INSERT INTO membership(workspace_id, channel_id, member_id) VALUES($1,$2,$3)")
        .bind(fixture.workspace)
        .bind(dm)
        .bind(fixture.hosted_agent)
        .execute(&su)
        .await
        .unwrap();

    let own_before = approved_of_3709(&su, fixture.hosted_agent).await;
    let other_before = approved_of_3709(&su, fixture.connect_only_agent).await;
    let confirm_before = hosted_confirm_columns_3706(&su, &fixture).await;

    // ---- unseen / ineligible channels: one refusal, nothing written --------
    let approvals_before: i64 =
        sqlx::query_scalar("SELECT count(*) FROM approval WHERE workspace_id=$1")
            .bind(fixture.workspace)
            .fetch_one(&su)
            .await
            .unwrap();
    let mut answers = Vec::new();
    for channels in [
        json!([s_name]),
        json!([dm_name]),
        json!(["no-such-room"]),
        json!([q_name, s_name]), // one bad name poisons the whole call
        json!([fixture_channel_name(&su, fixture.channel).await]), // already approved
    ] {
        let (status, refused) = try_propose_action_3706(
            &client,
            &base,
            &su,
            &fixture,
            "hosted.channels.grant",
            json!({"channels": channels}),
        )
        .await;
        answers.push((status, refused["error"].clone()));
    }
    assert!(
        answers.iter().all(|a| a.0 == 400 && a.1 == answers[0].1),
        "{answers:?}"
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>("SELECT count(*) FROM approval WHERE workspace_id=$1")
            .bind(fixture.workspace)
            .fetch_one(&su)
            .await
            .unwrap(),
        approvals_before
    );
    // No key can point at another agent's connection.
    let (status, refused) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "hosted.channels.grant",
        json!({"channels": [q_name], "connectionId": Uuid::new_v4()}),
    )
    .await;
    assert_eq!(status, 400, "{refused}");

    // ---- a good proposal: Q (public) and R (private, member) ----------------
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "hosted.channels.grant",
        json!({"channels": [format!("#{q_name}"), r_name]}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval = proposed_approval_3706(&proposed);
    let card: Value = sqlx::query_scalar("SELECT props FROM message WHERE id=$1")
        .bind(Uuid::parse_str(structured(&proposed)["cardMessageId"].as_str().unwrap()).unwrap())
        .fetch_one(&su)
        .await
        .unwrap();
    assert_eq!(card["action"]["required_role"], json!("admin"));
    let rows = card["action"]["rows"].as_array().unwrap().clone();
    assert!(rows.iter().any(|r| r["label"] == "채널"
        && r["value"]
            .as_str()
            .unwrap()
            .starts_with(&format!("#{q_name} · 공개 · "))));
    assert!(rows.iter().any(|r| r["label"] == "채널"
        && r["value"]
            .as_str()
            .unwrap()
            .starts_with(&format!("#{r_name} · 비공개 · "))));
    assert!(rows.iter().any(|r| r["label"] == "승인 채널 수"
        && r["value"] == format!("{}개 → {}개", own_before.len(), own_before.len() + 2)));
    assert_eq!(
        approved_of_3709(&su, fixture.hosted_agent).await,
        own_before
    );

    // ---- a non-admin cannot widen the agent's reach ------------------------
    let (status, _h, refused) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &plain_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 403, "{refused}");
    assert_eq!(refused["status"], "role_required");
    assert_eq!(
        approved_of_3709(&su, fixture.hosted_agent).await,
        own_before
    );
    assert_eq!(
        membership_role_3707(&su, q, fixture.hosted_agent).await,
        None
    );

    // ---- the admin approves ------------------------------------------------
    let (status, _h, approved) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(
        approved["result"]["actionId"],
        json!("hosted.channels.grant")
    );
    assert_eq!(
        approved["result"]["ref"],
        json!({"type": "hosted_connection", "id": fixture.hosted_connection.to_string()})
    );
    assert!(approved["result"].get("secretOnce").is_none());
    let own_after = approved_of_3709(&su, fixture.hosted_agent).await;
    assert_eq!(own_after.len(), own_before.len() + 2);
    assert!(own_after.contains(&q) && own_after.contains(&r));
    assert_eq!(
        membership_role_3707(&su, q, fixture.hosted_agent)
            .await
            .as_deref(),
        Some("member"),
        "the grant seats the agent: approved AND a member"
    );
    assert_eq!(
        membership_role_3707(&su, r, fixture.hosted_agent)
            .await
            .as_deref(),
        Some("member")
    );
    // The confirm columns and the DM approvals never move; nor does any other
    // agent's connection.
    assert_eq!(
        hosted_confirm_columns_3706(&su, &fixture).await,
        confirm_before
    );
    assert_eq!(
        approved_of_3709(&su, fixture.connect_only_agent).await,
        other_before
    );
    let covered: Vec<Uuid> =
        sqlx::query_scalar("SELECT unnest(hosted_connection_channel_ids($1,$2))")
            .bind(fixture.workspace)
            .bind(fixture.hosted_connection)
            .fetch_all(&su)
            .await
            .unwrap();
    assert!(covered.contains(&q) && covered.contains(&r));

    let detail: Value = sqlx::query_scalar(
        "SELECT detail FROM audit_log WHERE workspace_id=$1 \
           AND action='hosted_connection.channels_granted'",
    )
    .bind(fixture.workspace)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(
        detail["connection_id"],
        json!(fixture.hosted_connection.to_string())
    );
    assert_eq!(detail["via_agent"], json!(fixture.hosted_agent.to_string()));
    let mut granted: Vec<String> = detail["channel_ids"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    granted.sort();
    let mut expected = vec![q.to_string(), r.to_string()];
    expected.sort();
    assert_eq!(granted, expected);

    // The agent reads the ids from its outcome line and can post in Q.
    let (status, posted) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_message_post",
        json!({"channelId": q, "clientMsgId": Uuid::new_v4(), "body": "안녕하세요"}),
    )
    .await;
    assert_eq!(status, 200, "{posted}");
    let line: String = sqlx::query_scalar(
        "SELECT body FROM message WHERE workspace_id=$1 AND channel_id=$2 \
           AND type='approval_request' AND props->'result'->>'status'='executed' ORDER BY seq DESC LIMIT 1",
    )
    .bind(fixture.workspace)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    assert!(
        line.contains(&q.to_string()) && line.contains(&r.to_string()),
        "{line}"
    );
}

async fn fixture_channel_name(pool: &PgPool, channel: Uuid) -> String {
    sqlx::query_scalar("SELECT name FROM channel WHERE id=$1")
        .bind(channel)
        .fetch_one(pool)
        .await
        .expect("channel name")
}

/// The 50-channel ceiling holds at proposal time AND at the tap, and a refused
/// grant writes neither the array nor the membership.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_channel_grant_cannot_pass_fifty_approved_channels() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (c1, n1) = seed_channel_3707(&su, &fixture, "public", &[]).await;
    let (_c2, n2) = seed_channel_3707(&su, &fixture, "public", &[]).await;
    let (c3, n3) = seed_channel_3707(&su, &fixture, "public", &[]).await;
    let set_to = |count: usize| {
        let su = su.clone();
        let connection = fixture.hosted_connection;
        let base_channel = fixture.channel;
        async move {
            sqlx::query(
                // The channel the agent is mentioned in stays approved (or no job
                // would reach it); the rest are filler ids up to `count`.
                "UPDATE hosted_agent_connection SET approved_channel_ids = \
                   ARRAY[$3::uuid] || ARRAY(SELECT gen_random_uuid() \
                                              FROM generate_series(1,$2::int - 1)) \
                 WHERE id=$1",
            )
            .bind(connection)
            .bind(count as i32)
            .bind(base_channel)
            .execute(&su)
            .await
            .unwrap();
        }
    };

    // 49 + 2 > 50: refused when proposed.
    set_to(49).await;
    let (status, refused) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "hosted.channels.grant",
        json!({"channels": [n1.clone(), n2]}),
    )
    .await;
    assert_eq!(status, 400, "{refused}");
    // 49 + 1 = 50: allowed.
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "hosted.channels.grant",
        json!({"channels": [n1]}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    // …but the set grew to 50 before the tap: stale, nothing written.
    set_to(50).await;
    let (status, _h, capped) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        proposed_approval_3706(&proposed),
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{capped}");
    assert_eq!(capped["status"], "action_args_invalid");
    assert_eq!(approved_of_3709(&su, fixture.hosted_agent).await.len(), 50);
    assert_eq!(
        membership_role_3707(&su, c1, fixture.hosted_agent).await,
        None
    );

    // The same at the database function itself: the 51st is refused and the
    // membership is not written (the array is checked first).
    let mut tx = su.begin().await.unwrap();
    let outcome = momo_auth::grant_hosted_channels_in_tx(
        &mut tx,
        fixture.workspace,
        fixture.hosted_connection,
        fixture.hosted_agent,
        &[c3],
    )
    .await
    .unwrap();
    assert!(outcome.is_none(), "the 51st channel must be refused");
    tx.commit().await.unwrap();
    assert_eq!(
        membership_role_3707(&su, c3, fixture.hosted_agent).await,
        None
    );
    let _ = n3;

    // The function also refuses another agent's connection id.
    let other_connection: Uuid =
        sqlx::query_scalar("SELECT id FROM hosted_agent_connection WHERE agent_member_id=$1")
            .bind(fixture.connect_only_agent)
            .fetch_one(&su)
            .await
            .unwrap();
    set_to(1).await;
    let mut tx = su.begin().await.unwrap();
    let outcome = momo_auth::grant_hosted_channels_in_tx(
        &mut tx,
        fixture.workspace,
        other_connection,
        fixture.hosted_agent, // the proposer is NOT this connection's agent
        &[c3],
    )
    .await
    .unwrap();
    assert!(
        outcome.is_none(),
        "a connection of another agent is not grantable"
    );
    tx.commit().await.unwrap();
    assert_eq!(
        membership_role_3707(&su, c3, fixture.hosted_agent).await,
        None
    );
}

/// A grant gone stale, or reached by the wrong caller, writes nothing: the
/// connection stopped being live, the agent left the private room, an agent tries
/// to decide, and the database function itself refuses a private room the agent is
/// not in (the visibility rule is enforced there too, not only by the resolver).
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_stale_channel_grant_changes_nothing() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (q, q_name) = seed_channel_3707(&su, &fixture, "public", &[]).await;
    let (r, r_name) = seed_channel_3707(
        &su,
        &fixture,
        "private",
        &[(fixture.hosted_agent, "member")],
    )
    .await;
    let (hidden, _) = seed_channel_3707(&su, &fixture, "private", &[]).await;
    let before = approved_of_3709(&su, fixture.hosted_agent).await;

    // The connection stops being live before the tap.
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "hosted.channels.grant",
        json!({"channels": [q_name]}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let first = proposed_approval_3706(&proposed);
    // An agent bearer cannot decide it.
    let agent_try = client
        .post(format!(
            "{base}/v1/workspaces/{}/approvals/{first}/decision",
            fixture.workspace
        ))
        .bearer_auth(&fixture.hosted_bearer)
        .json(&json!({"approvalId": first, "approve": true, "clientDecisionId": Uuid::new_v4()}))
        .send()
        .await
        .unwrap();
    assert!(matches!(agent_try.status().as_u16(), 401 | 403));
    assert_eq!(approved_of_3709(&su, fixture.hosted_agent).await, before);

    // (`proved_at` cannot be cleared on an active connection — the shape check
    // forbids it — so the credential is revoked instead.)
    sqlx::query("UPDATE token SET revoked_at = now() WHERE id=$1")
        .bind(fixture.hosted_token)
        .execute(&su)
        .await
        .unwrap();
    let (status, _h, stale) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        first,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{stale}");
    assert_eq!(stale["status"], "action_args_invalid");
    assert_eq!(approved_of_3709(&su, fixture.hosted_agent).await, before);
    assert_eq!(
        membership_role_3707(&su, q, fixture.hosted_agent).await,
        None
    );
    sqlx::query("UPDATE token SET revoked_at = NULL WHERE id=$1")
        .bind(fixture.hosted_token)
        .execute(&su)
        .await
        .unwrap();

    // The agent leaves the private room before the tap.
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "hosted.channels.grant",
        json!({"channels": [r_name]}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    sqlx::query("UPDATE membership SET left_at = now() WHERE channel_id=$1 AND member_id=$2")
        .bind(r)
        .bind(fixture.hosted_agent)
        .execute(&su)
        .await
        .unwrap();
    let (status, _h, stale) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        proposed_approval_3706(&proposed),
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{stale}");
    assert_eq!(approved_of_3709(&su, fixture.hosted_agent).await, before);

    // The function refuses a private room the agent is not in, on its own.
    let mut tx = su.begin().await.unwrap();
    let outcome = momo_auth::grant_hosted_channels_in_tx(
        &mut tx,
        fixture.workspace,
        fixture.hosted_connection,
        fixture.hosted_agent,
        &[hidden],
    )
    .await
    .unwrap();
    assert!(outcome.is_none(), "a private room the agent cannot see");
    tx.commit().await.unwrap();
    assert_eq!(
        membership_role_3707(&su, hidden, fixture.hosted_agent).await,
        None
    );
    assert_eq!(approved_of_3709(&su, fixture.hosted_agent).await, before);
}

// ---------------------------------------------------------------------------
// ADR-0186 증보 2026-10-11 S5 (#3710) — workspace.settings.update
// ---------------------------------------------------------------------------

async fn settings_bag_3710(pool: &PgPool, workspace: Uuid) -> Value {
    sqlx::query_scalar("SELECT settings FROM workspace WHERE id=$1")
        .bind(workspace)
        .fetch_one(pool)
        .await
        .expect("settings bag")
}

/// **workspace.settings.update (증보 V7, V11).**
///
/// Two keys only, operator-gated, replaced whole for `role_labels`, cleared by
/// `null`; every other key of the bag is byte-identical before and after; the
/// audit row names the keys and carries no value; a stale card (the old value
/// moved) is refused with the approval still pending.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn an_approved_settings_update_changes_only_the_two_keys() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (_plain, plain_jwt) = seed_human_3708(&su, &fixture, "plain", "member").await;
    let start = json!({
        "allowed_agent_models": ["hermes-agent"],
        "role_labels": {"member": "팀원"},
        "welcome_prompt": "예전 문구"
    });
    sqlx::query("UPDATE workspace SET settings=$2 WHERE id=$1")
        .bind(fixture.workspace)
        .bind(&start)
        .execute(&su)
        .await
        .unwrap();

    // ---- keys this action does not own: refused before any card ------------
    let approvals_before: i64 =
        sqlx::query_scalar("SELECT count(*) FROM approval WHERE workspace_id=$1")
            .bind(fixture.workspace)
            .fetch_one(&su)
            .await
            .unwrap();
    for args in [
        json!({"allowedAgentModels": ["anything"]}),
        json!({"welcomeAgentMemberId": fixture.hosted_agent}),
        json!({"welcomePrompt": "ok", "allowedAgentModels": []}),
        json!({"welcomePrompt": "가".repeat(501)}),
        json!({}),
    ] {
        let (status, refused) = try_propose_action_3706(
            &client,
            &base,
            &su,
            &fixture,
            "workspace.settings.update",
            args.clone(),
        )
        .await;
        assert_eq!(status, 400, "{args}: {refused}");
    }
    assert_eq!(
        sqlx::query_scalar::<_, i64>("SELECT count(*) FROM approval WHERE workspace_id=$1")
            .bind(fixture.workspace)
            .fetch_one(&su)
            .await
            .unwrap(),
        approvals_before
    );

    // ---- a good proposal ----------------------------------------------------
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "workspace.settings.update",
        json!({"welcomePrompt": "새 환영 문구", "roleLabels": {"owner": "대표"}}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval = proposed_approval_3706(&proposed);
    let card: Value = sqlx::query_scalar("SELECT props FROM message WHERE id=$1")
        .bind(Uuid::parse_str(structured(&proposed)["cardMessageId"].as_str().unwrap()).unwrap())
        .fetch_one(&su)
        .await
        .unwrap();
    assert_eq!(card["action"]["required_role"], json!("workspace_operator"));
    let rows = card["action"]["rows"].as_array().unwrap().clone();
    let row = |label: &str| {
        rows.iter().find(|r| r["label"] == label).unwrap()["value"]
            .as_str()
            .unwrap()
            .to_string()
    };
    assert_eq!(row("환영 문구"), "\"예전 문구\" → \"새 환영 문구\"");
    assert_eq!(row("역할 이름"), "member=\"팀원\" → owner=\"대표\"");
    assert_eq!(settings_bag_3710(&su, fixture.workspace).await, start);

    // ---- a non-operator and an agent cannot approve ------------------------
    let (status, _h, refused) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &plain_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 403, "{refused}");
    assert_eq!(refused["status"], "role_required");
    let agent_try = client
        .post(format!(
            "{base}/v1/workspaces/{}/approvals/{approval}/decision",
            fixture.workspace
        ))
        .bearer_auth(&fixture.hosted_bearer)
        .json(&json!({"approvalId": approval, "approve": true,
                      "clientDecisionId": Uuid::new_v4()}))
        .send()
        .await
        .unwrap();
    assert!(matches!(agent_try.status().as_u16(), 401 | 403));
    assert_eq!(settings_bag_3710(&su, fixture.workspace).await, start);

    // ---- the admin approves ------------------------------------------------
    let (status, _h, approved) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(
        approved["result"]["actionId"],
        json!("workspace.settings.update")
    );
    assert_eq!(
        approved["result"]["ref"],
        json!({"type": "workspace_settings", "id": fixture.workspace.to_string()})
    );
    assert!(approved["result"].get("secretOnce").is_none());
    assert_eq!(
        settings_bag_3710(&su, fixture.workspace).await,
        json!({
            "allowed_agent_models": ["hermes-agent"],
            "role_labels": {"owner": "대표"},
            "welcome_prompt": "새 환영 문구"
        }),
        "role_labels is replaced whole; every other key is untouched"
    );

    // ---- audit names the keys and carries no value --------------------------
    let detail: Value = sqlx::query_scalar(
        "SELECT detail FROM audit_log WHERE workspace_id=$1 AND action='workspace_setting.updated'",
    )
    .bind(fixture.workspace)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(detail["keys"], json!(["welcome_prompt", "role_labels"]));
    assert_eq!(detail["via_agent"], json!(fixture.hosted_agent.to_string()));
    assert_eq!(detail["approval_id"], json!(approval.to_string()));
    let rendered = detail.to_string();
    assert!(
        !rendered.contains("새 환영 문구")
            && !rendered.contains("대표")
            && !rendered.contains("예전"),
        "the audit row must not carry the values: {rendered}"
    );
    assert_eq!(
        audit_count_3706(&su, fixture.workspace, "action.approved").await,
        1
    );
    let line: String = sqlx::query_scalar(
        "SELECT body FROM message WHERE workspace_id=$1 AND channel_id=$2 \
           AND type='approval_request' AND props->'result'->>'status'='executed' ORDER BY seq DESC LIMIT 1",
    )
    .bind(fixture.workspace)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(line, "설정을 바꿨어요: 환영 문구, 역할 이름");

    // ---- `null` clears one key and leaves the other -------------------------
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "workspace.settings.update",
        json!({"welcomePrompt": Value::Null}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let (status, _h, cleared) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        proposed_approval_3706(&proposed),
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{cleared}");
    assert_eq!(
        settings_bag_3710(&su, fixture.workspace).await,
        json!({"allowed_agent_models": ["hermes-agent"], "role_labels": {"owner": "대표"}})
    );

    // ---- a card whose old value moved is stale ------------------------------
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "workspace.settings.update",
        json!({"roleLabels": {"admin": "관리자"}}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let stale_approval = proposed_approval_3706(&proposed);
    sqlx::query(
        "UPDATE workspace SET settings = jsonb_set(settings, '{role_labels}', '{\"guest\":\"손님\"}') \
          WHERE id=$1",
    )
    .bind(fixture.workspace)
    .execute(&su)
    .await
    .unwrap();
    let moved = settings_bag_3710(&su, fixture.workspace).await;
    let (status, _h, stale) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        stale_approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{stale}");
    assert_eq!(stale["status"], "action_args_invalid");
    assert_eq!(settings_bag_3710(&su, fixture.workspace).await, moved);
    assert_eq!(approval_status_3708(&su, stale_approval).await, "pending");
}

/// The operator gate is `require_workspace_operator`'s set: a workspace admin OR a
/// principal carrying the platform operator scope — and a plain member with
/// neither is refused (covered above). Here: a non-admin member whose session
/// carries `platform:read` may approve.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_platform_operator_who_is_not_an_admin_may_approve_a_settings_update() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (operator, _plain_jwt) = seed_human_3708(&su, &fixture, "operator", "member").await;
    let jwt = momo_auth::sign_access(
        operator,
        fixture.workspace,
        &["platform:read".to_string()],
        TEST_JWT_SECRET,
    )
    .expect("sign an operator JWT")
    .token;
    sqlx::query(
        "INSERT INTO token(workspace_id, kind, actor_member_id, token_hash, scopes, label) \
         VALUES($1,'session',$2,digest($3::text,'sha256'),ARRAY['platform:read']::text[],'operator')",
    )
    .bind(fixture.workspace)
    .bind(operator)
    .bind(&jwt)
    .execute(&su)
    .await
    .unwrap();
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "workspace.settings.update",
        json!({"roleLabels": {"guest": "손님"}}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let (status, _h, approved) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &jwt,
        proposed_approval_3706(&proposed),
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(
        settings_bag_3710(&su, fixture.workspace).await["role_labels"],
        json!({"guest": "손님"})
    );
}

// ---------------------------------------------------------------------------
// (#3740 S1, ADR-0200 D2) the run event ledger
// ---------------------------------------------------------------------------

type LedgerRow = (i64, String, Option<String>, Option<String>, Option<Uuid>);

/// The lifecycle/stage ledger of one run. `tool_call` rows (#3840, ADR-0200 증보
/// 2026-10-15) are left out: every Agent Port call that points at the run adds one, and
/// they have their own tests (`tool_calls_3840`) — the assertions written against this
/// helper are about lifecycle and stage rows.
async fn ledger_3740(pool: &PgPool, workspace: Uuid, run: Uuid) -> Vec<LedgerRow> {
    sqlx::query_as(
        "SELECT seq, kind, stage, code, actor_member_id FROM agent_run_event \
          WHERE workspace_id=$1 AND run_id=$2 AND kind <> 'tool_call' ORDER BY seq",
    )
    .bind(workspace)
    .bind(run)
    .fetch_all(pool)
    .await
    .expect("ledger rows")
}

fn kinds_3740(rows: &[LedgerRow]) -> Vec<&str> {
    rows.iter().map(|row| row.1.as_str()).collect()
}

async fn mention_3740(
    client: &reqwest::Client,
    base: &str,
    su: &PgPool,
    fixture: &Fixture,
    agent: Uuid,
) {
    let sent: Value = client
        .post(format!(
            "{base}/v1/workspaces/{}/channels/{}/messages",
            fixture.workspace, fixture.channel
        ))
        .bearer_auth(&fixture.human_jwt)
        .json(&json!({
            "clientMsgId": Uuid::new_v4(),
            "body": format!("@{} please answer", hosted_handle(su, agent).await)
        }))
        .send()
        .await
        .expect("mention send")
        .json()
        .await
        .expect("mention body");
    assert!(sent["id"].is_string(), "{sent}");
}

/// RED PROOF (ADR-0200 D2, S1). A hosted mention run leaves exactly the rows the
/// panel needs after it was closed — queued, claimed (with WHO), started, the
/// stage markers (folded when repeated), the terminal — in one gapless per-run
/// order. A managed agent's run in the same workspace writes nothing.
///
/// Tamper table (each edit must turn this test red):
///   * drop the `claimed` append in `jobs_claim`             -> kinds lack `claimed`
///   * drop the `Stage` append in `record_gateway_event_in_tx` -> kinds lack `stage`
///   * drop the `hosted_lease` guard around that append        -> (managed run test below) ledger rows for a managed run
///   * drop the fold in `agent_run_event_append`               -> the repeated stage adds a row
///   * drop the hosted predicate in `agent_run_event_on_run`   -> the managed run writes `queued`
///   * drop the AFTER INSERT/UPDATE agent_run triggers         -> no `queued`/`started`/`succeeded`
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn the_run_event_ledger_records_a_hosted_run_in_order() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();

    mention_3740(&client, &base, &su, &fixture, fixture.hosted_agent).await;
    let run: Uuid =
        sqlx::query_scalar("SELECT id FROM agent_run WHERE workspace_id=$1 AND agent_member_id=$2")
            .bind(fixture.workspace)
            .bind(fixture.hosted_agent)
            .fetch_one(&su)
            .await
            .unwrap();
    assert_eq!(
        kinds_3740(&ledger_3740(&su, fixture.workspace, run).await),
        ["queued"],
        "the run row is the first ledger row, written by the trigger"
    );

    let (status, claimed) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_jobs_claim",
        json!({"limit": 10}),
    )
    .await;
    assert_eq!(status, 200, "{claimed}");
    let handle = structured(&claimed)["jobs"][0]["leaseHandle"]
        .as_str()
        .expect("handle")
        .to_string();
    let rows = ledger_3740(&su, fixture.workspace, run).await;
    assert_eq!(kinds_3740(&rows), ["queued", "claimed"]);
    assert_eq!(
        rows[1].4,
        Some(fixture.hosted_agent),
        "`claimed` records WHICH agent took it"
    );
    let status_after_claim: String =
        sqlx::query_scalar("SELECT status::text FROM agent_run WHERE id=$1")
            .bind(run)
            .fetch_one(&su)
            .await
            .unwrap();
    assert_eq!(
        status_after_claim, "queued",
        "claim does not move agent_run.status — the ledger is where 'claimed' lives"
    );

    // A stage report starts the run and adds a marker; the same marker again
    // (a different eventId) folds; a stage-less event adds nothing.
    for (stage, expect_new) in [
        (Some("채널 이름 확인"), true),
        (Some("채널 이름 확인"), false),
        (None, false),
        (Some("승인 카드 제안"), true),
    ] {
        let mut arguments = json!({
            "leaseHandle": handle,
            "status": "running",
            "eventId": Uuid::new_v4(),
        });
        if let Some(stage) = stage {
            arguments["stage"] = json!(stage);
        }
        let before = ledger_3740(&su, fixture.workspace, run).await.len();
        let first_event = before == 2; // queued + claimed so far: this event also starts the run
        let (status, event) = call(
            &client,
            &base,
            &fixture.hosted_bearer,
            "oort_run_event",
            arguments,
        )
        .await;
        assert_eq!(status, 200, "{event}");
        let after = ledger_3740(&su, fixture.workspace, run).await.len();
        assert_eq!(
            after - before,
            usize::from(expect_new) + usize::from(first_event),
            "stage {stage:?}: a new marker adds one row, a repeat or a stage-less event none, \
             and the first event also adds `started`"
        );
    }

    // A rejected marker writes nothing at all.
    let before = ledger_3740(&su, fixture.workspace, run).await.len();
    let (status, _) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_run_event",
        json!({"leaseHandle": handle, "status": "running", "stage": "a/b"}),
    )
    .await;
    assert_eq!(status, 400);
    assert_eq!(ledger_3740(&su, fixture.workspace, run).await.len(), before);

    let (status, done) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_run_complete",
        json!({"leaseHandle": handle, "status": "succeeded", "body": "done"}),
    )
    .await;
    assert_eq!(status, 200, "{done}");

    let rows = ledger_3740(&su, fixture.workspace, run).await;
    assert_eq!(
        kinds_3740(&rows),
        [
            "queued",
            "claimed",
            "started",
            "stage",
            "stage",
            "succeeded"
        ]
    );
    assert!(
        rows.windows(2).all(|pair| pair[0].0 < pair[1].0),
        "seq strictly increases in write order: {rows:?}"
    );
    assert_eq!(rows[3].2.as_deref(), Some("채널 이름 확인"));
    assert_eq!(rows[4].2.as_deref(), Some("승인 카드 제안"));
    assert!(rows
        .iter()
        .filter(|row| row.1 != "stage")
        .all(|row| row.2.is_none()));

    // The managed agent's run in the same workspace writes no ledger row.
    mention_3740(&client, &base, &su, &fixture, fixture.managed_agent).await;
    let managed_rows: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM agent_run_event e JOIN agent_run r \
           ON r.workspace_id=e.workspace_id AND r.id=e.run_id \
          WHERE r.workspace_id=$1 AND r.agent_member_id=$2",
    )
    .bind(fixture.workspace)
    .bind(fixture.managed_agent)
    .fetch_one(&su)
    .await
    .unwrap();
    let managed_runs: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM agent_run WHERE workspace_id=$1 AND agent_member_id=$2",
    )
    .bind(fixture.workspace)
    .bind(fixture.managed_agent)
    .fetch_one(&su)
    .await
    .unwrap();
    assert!(managed_runs >= 1, "the managed mention produced a run");
    assert_eq!(managed_rows, 0, "ADR-0200 D6: hosted agents only");
}

/// RED PROOF (ADR-0200 D2, S1). The approval and sweep paths are covered by the
/// triggers, not by their callers: the notifier's own UPDATE (the approval
/// expiry sweep's role) writes the rows; the stage cap never evicts a lifecycle
/// row; and the table's own CHECKs refuse what the route validator would.
///
/// Tamper table:
///   * drop `agent_run_event_approval_*` triggers   -> no approval_requested/approval_decided
///   * drop the `code` extraction                   -> the timed_out row loses `approval_expired`
///   * drop the notifier GRANT (bootstrap_runtime_roles.sql) -> the notifier UPDATE dies with permission denied
///   * make the cap delete any kind (agent_run_event_trim) -> lifecycle rows vanish at 200
///   * relax `agent_run_event_stage_ck`             -> the `a/b` insert succeeds
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn the_ledger_triggers_cover_the_sweep_and_the_cap_keeps_lifecycle_rows() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let notifier = momo_notifier_pool().await;
    let fixture = seed(&su).await;

    let run: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status) \
         VALUES ($1,$2,$3,'queued') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    let approval: Uuid = sqlx::query_scalar(
        "INSERT INTO approval (workspace_id, run_id, channel_id, requested_by, action_type) \
         VALUES ($1,$2,$3,$4,'workspace_action') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(run)
    .bind(fixture.channel)
    .bind(fixture.hosted_agent)
    .fetch_one(&su)
    .await
    .unwrap();
    sqlx::query("UPDATE agent_run SET status='awaiting_approval' WHERE id=$1")
        .bind(run)
        .execute(&su)
        .await
        .unwrap();

    // The expiry sweep runs as momo_notifier (BYPASSRLS, table-scoped grants):
    // its UPDATEs fire the triggers, which must be able to append as that role.
    let mut tx = notifier.begin().await.expect("notifier tx");
    sqlx::query("UPDATE approval SET status='expired' WHERE id=$1")
        .bind(approval)
        .execute(&mut *tx)
        .await
        .expect("notifier may expire an approval and fire the ledger trigger");
    sqlx::query("UPDATE agent_run SET status='timed_out', error=$2 WHERE id=$1")
        .bind(run)
        .bind(json!({"code": "approval_expired", "approval_id": approval.to_string()}))
        .execute(&mut *tx)
        .await
        .expect("notifier may end the run and fire the ledger trigger");
    tx.commit().await.unwrap();

    let rows = ledger_3740(&su, fixture.workspace, run).await;
    assert_eq!(
        kinds_3740(&rows),
        [
            "queued",
            "approval_requested",
            "approval_decided",
            "timed_out"
        ]
    );
    assert_eq!(rows[2].3.as_deref(), Some("expired"));
    assert_eq!(rows[3].3.as_deref(), Some("approval_expired"));
    assert_eq!(rows[1].4, Some(fixture.hosted_agent), "who asked");

    // The cap: 250 stages, 200 rows kept, every lifecycle row still there.
    for n in 0..250 {
        sqlx::query("SELECT agent_run_event_append($1,$2,'stage',$3,NULL,NULL,$4)")
            .bind(fixture.workspace)
            .bind(run)
            .bind(format!("단계 {n}"))
            .bind(fixture.hosted_agent)
            .execute(&su)
            .await
            .unwrap();
        sqlx::query("SELECT agent_run_event_trim($1,$2)")
            .bind(fixture.workspace)
            .bind(run)
            .execute(&su)
            .await
            .unwrap();
    }
    let rows = ledger_3740(&su, fixture.workspace, run).await;
    assert_eq!(rows.len(), 200);
    assert_eq!(
        rows.iter().filter(|row| row.1 != "stage").count(),
        4,
        "the cap evicts old stage rows only"
    );
    assert_eq!(
        rows.last().unwrap().2.as_deref(),
        Some("단계 249"),
        "the newest marker is the one kept"
    );

    // The table refuses what the route validator would (defence in depth).
    for (stage, code) in [
        (Some("a/b"), None),
        (Some("x"), Some("Bad Code")),
        (None, None),
    ] {
        let result = sqlx::query(
            "INSERT INTO agent_run_event (workspace_id, run_id, seq, kind, stage, code) \
             VALUES ($1,$2,9999,$3,$4,$5)",
        )
        .bind(fixture.workspace)
        .bind(run)
        .bind("stage")
        .bind(stage)
        .bind(code)
        .execute(&su)
        .await;
        let error = result.expect_err("a malformed row must be refused");
        let constraint = error
            .as_database_error()
            .and_then(|db| db.constraint())
            .unwrap_or_default()
            .to_string();
        assert!(
            constraint == "agent_run_event_stage_ck" || constraint == "agent_run_event_code_ck",
            "{stage:?} {code:?} refused by the table's own CHECK, not by something else: {constraint:?} / {error}"
        );
    }
}

/// RED PROOF (ADR-0200 D2, S1). The ledger is tenant-isolated by RLS FORCE on
/// the NOBYPASSRLS app role: no setting sees nothing, another tenant sees
/// nothing, and a write for a workspace other than the bound one is refused.
///
/// Tamper table:
///   * drop `FORCE ROW LEVEL SECURITY` or the policy -> another tenant reads rows
///   * drop WITH CHECK                               -> the cross-tenant INSERT succeeds
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn the_run_event_ledger_is_tenant_isolated() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let other = seed(&su).await;
    let run: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status) \
         VALUES ($1,$2,$3,'queued') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();

    let count_as = |ws: Uuid| {
        let app = app.clone();
        async move {
            let mut tx = app.begin().await.unwrap();
            sqlx::query("SELECT set_config('app.workspace_id', $1, true)")
                .bind(ws.to_string())
                .execute(&mut *tx)
                .await
                .unwrap();
            let n: i64 = sqlx::query_scalar("SELECT count(*) FROM agent_run_event")
                .fetch_one(&mut *tx)
                .await
                .unwrap();
            n
        }
    };
    assert_eq!(count_as(fixture.workspace).await, 1);
    assert_eq!(
        count_as(other.workspace).await,
        0,
        "another tenant sees none"
    );

    let mut tx = app.begin().await.unwrap();
    sqlx::query("SELECT set_config('app.workspace_id', $1, true)")
        .bind(other.workspace.to_string())
        .execute(&mut *tx)
        .await
        .unwrap();
    // Through the function: the run is invisible to the bound tenant (RLS on agent_run),
    // so the append is a NULL — it neither writes nor tells whether the run exists.
    let forged: Option<i64> =
        sqlx::query_scalar("SELECT agent_run_event_append($1,$2,'stage','x',NULL,NULL,NULL)")
            .bind(fixture.workspace)
            .bind(run)
            .fetch_one(&mut *tx)
            .await
            .expect("a foreign run is NULL, the same answer as a missing one");
    assert_eq!(forged, None);
    // Around the function: the table's own WITH CHECK refuses another tenant's row.
    sqlx::query("SAVEPOINT raw_insert")
        .execute(&mut *tx)
        .await
        .unwrap();
    let raw = sqlx::query(
        "INSERT INTO agent_run_event (workspace_id, run_id, kind) VALUES ($1,$2,'queued')",
    )
    .bind(fixture.workspace)
    .bind(run)
    .execute(&mut *tx)
    .await;
    assert!(
        raw.is_err(),
        "an INSERT for a workspace other than the bound one is refused by RLS"
    );
    drop(tx);
    assert_eq!(
        ledger_3740(&su, fixture.workspace, run).await.len(),
        1,
        "the foreign attempts wrote nothing"
    );
}

/// RED PROOF (ADR-0200 D2, S1; security review H1/M1/M3). The append takes no lock, so
/// it cannot close a cycle with the claim/approve/cancel paths; a missing run is a NULL,
/// not an error that would poison a claim; and history cannot be rewritten.
///
/// Tamper table:
///   * re-add `pg_advisory_xact_lock` to `agent_run_event_append`  -> the second transaction
///     blocks behind the open first one and the timeout below fires
///   * drop the `EXISTS (SELECT 1 FROM agent_run ...)` guard        -> the missing-run append raises 23503
///   * drop `agent_run_event_immutable_trg`                         -> the UPDATE succeeds
///   * drop the trim call in `append_run_event_in_tx`               -> a re-claim-only run grows past 200
///   * drop `agent_run_event_del_trg`                               -> the deleted run's ledger survives
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn the_ledger_append_takes_no_lock_and_history_is_immutable() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let fixture = seed(&su).await;
    let run: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status) \
         VALUES ($1,$2,$3,'queued') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    let approval: Uuid = sqlx::query_scalar(
        "INSERT INTO approval (workspace_id, run_id, channel_id, requested_by, action_type) \
         VALUES ($1,$2,$3,$4,'workspace_action') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(run)
    .bind(fixture.channel)
    .bind(fixture.hosted_agent)
    .fetch_one(&su)
    .await
    .unwrap();

    // Transaction A is a "cancel": it moves the run (the trigger appends) and stays OPEN.
    let mut a = su.begin().await.unwrap();
    sqlx::query("UPDATE agent_run SET status='cancelled' WHERE id=$1")
        .bind(run)
        .execute(&mut *a)
        .await
        .unwrap();

    // Transaction B is the opposite order: it holds the approval row, then appends a
    // `claimed` row for the same run and decides the approval (the trigger appends).
    // With any per-run lock in the append, B would wait for A here; A would then wait
    // for B's approval row — the deadlock the review found. It must finish while A is open.
    let b = async {
        let mut tx = su.begin().await.unwrap();
        sqlx::query("SELECT id FROM approval WHERE id=$1 FOR UPDATE")
            .bind(approval)
            .execute(&mut *tx)
            .await
            .unwrap();
        sqlx::query("SELECT agent_run_event_append($1,$2,'claimed',NULL,NULL,NULL,$3)")
            .bind(fixture.workspace)
            .bind(run)
            .bind(fixture.hosted_agent)
            .execute(&mut *tx)
            .await
            .unwrap();
        sqlx::query("UPDATE approval SET status='cancelled' WHERE id=$1")
            .bind(approval)
            .execute(&mut *tx)
            .await
            .unwrap();
        tx.commit().await.unwrap();
    };
    tokio::time::timeout(std::time::Duration::from_secs(5), b)
        .await
        .expect("an append never waits for another transaction's lock");
    a.commit().await.unwrap();

    let rows = ledger_3740(&su, fixture.workspace, run).await;
    assert_eq!(rows.len(), 5, "{rows:?}");
    let mut kinds = kinds_3740(&rows);
    kinds.sort_unstable();
    assert_eq!(
        kinds,
        [
            "approval_decided",
            "approval_requested",
            "cancelled",
            "claimed",
            "queued"
        ]
    );

    // A job pointing at a run that does not exist appends nothing and does not raise.
    let missing: Option<i64> =
        sqlx::query_scalar("SELECT agent_run_event_append($1,$2,'claimed',NULL,NULL,NULL,$3)")
            .bind(fixture.workspace)
            .bind(Uuid::new_v4())
            .bind(fixture.hosted_agent)
            .fetch_one(&su)
            .await
            .expect("a missing run is NULL, not an error");
    assert_eq!(missing, None);

    // History is immutable — even for the superuser's UPDATE.
    let update = sqlx::query("UPDATE agent_run_event SET kind='failed' WHERE run_id=$1")
        .bind(run)
        .execute(&su)
        .await;
    let update = update.expect_err("agent_run_event rows must not be updatable");
    assert_eq!(
        update
            .as_database_error()
            .and_then(|db| db.code())
            .as_deref(),
        Some("23001"),
        "refused by the immutability trigger itself: {update}"
    );

    // The cap, through the PRODUCTION helper (the claim path calls it, not a test): old
    // `claimed` rows are shed, the newest stays, nothing else goes.
    {
        let mut conn = su.acquire().await.unwrap();
        for _ in 0..260 {
            let seq = momo_agent::append_run_event_in_tx(
                &mut conn,
                fixture.workspace,
                run,
                momo_agent::AppendedRunEvent::Claimed,
                fixture.hosted_agent,
            )
            .await
            .unwrap();
            assert!(seq.is_some());
        }
    }
    let rows = ledger_3740(&su, fixture.workspace, run).await;
    assert_eq!(
        rows.len(),
        200,
        "a hard bound even without a single stage row"
    );
    assert!(
        rows.iter().any(|row| row.1 == "queued") && rows.iter().any(|row| row.1 == "cancelled"),
        "only `claimed` rows were shed"
    );

    // No FK means the delete trigger is what removes a deleted run's ledger.
    sqlx::query("DELETE FROM approval WHERE run_id=$1")
        .bind(run)
        .execute(&su)
        .await
        .unwrap();
    sqlx::query("DELETE FROM agent_run WHERE id=$1")
        .bind(run)
        .execute(&su)
        .await
        .unwrap();
    assert!(
        ledger_3740(&su, fixture.workspace, run).await.is_empty(),
        "a deleted run takes its ledger with it"
    );

    // …and under the production API role + RLS (momo_app, bound tenant), not only for the
    // superuser: the trigger's DELETE runs as the invoker.
    let app = momo_app_pool().await;
    let run2: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status) \
         VALUES ($1,$2,$3,'queued') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(ledger_3740(&su, fixture.workspace, run2).await.len(), 1);
    let mut tx = app.begin().await.unwrap();
    sqlx::query("SELECT set_config('app.workspace_id', $1, true)")
        .bind(fixture.workspace.to_string())
        .execute(&mut *tx)
        .await
        .unwrap();
    sqlx::query("DELETE FROM agent_run WHERE id=$1")
        .bind(run2)
        .execute(&mut *tx)
        .await
        .expect("momo_app may delete a run and fire the ledger delete trigger");
    tx.commit().await.unwrap();
    assert!(
        ledger_3740(&su, fixture.workspace, run2).await.is_empty(),
        "…as momo_app under RLS too"
    );
}

// ---------------------------------------------------------------------------
// (#3840, ADR-0200 증보 2026-10-15 T1~T5) the `tool_call` ledger kind
// ---------------------------------------------------------------------------

/// `(tool, code, duration_ms, stage, approval_id, actor, framed, created_at)` of every
/// `tool_call` row of one run, oldest first.
type ToolCallRow3840 = (
    String,
    String,
    i32,
    Option<String>,
    Option<Uuid>,
    Option<Uuid>,
    bool,
    chrono::DateTime<chrono::Utc>,
);

async fn tool_calls_3840(su: &PgPool, workspace: Uuid, run: Uuid) -> Vec<ToolCallRow3840> {
    sqlx::query_as(
        "SELECT tool, code, duration_ms, stage, approval_id, actor_member_id, framed, created_at \
           FROM agent_run_event \
          WHERE workspace_id=$1 AND run_id=$2 AND kind='tool_call' ORDER BY seq",
    )
    .bind(workspace)
    .bind(run)
    .fetch_all(su)
    .await
    .expect("tool_call rows")
}

/// `(tool, ok, error, duration_ms_sum)` of one run's tally, by tool name.
async fn tally_3840(su: &PgPool, workspace: Uuid, run: Uuid) -> Vec<(String, i64, i64, i64)> {
    sqlx::query_as(
        "SELECT tool, ok_count, error_count, duration_ms_sum FROM agent_run_tool_tally \
          WHERE workspace_id=$1 AND run_id=$2 ORDER BY tool",
    )
    .bind(workspace)
    .bind(run)
    .fetch_all(su)
    .await
    .expect("tally rows")
}

async fn workspace_tool_call_count_3840(su: &PgPool, workspace: Uuid) -> i64 {
    sqlx::query_scalar(
        "SELECT (SELECT count(*) FROM agent_run_event WHERE workspace_id=$1 AND kind='tool_call') \
              + (SELECT count(*) FROM agent_run_tool_tally WHERE workspace_id=$1)",
    )
    .bind(workspace)
    .fetch_one(su)
    .await
    .unwrap()
}

async fn columns_3840(su: &PgPool, table: &str) -> Vec<String> {
    sqlx::query_scalar(
        "SELECT column_name::text FROM information_schema.columns \
          WHERE table_schema='public' AND table_name=$1 ORDER BY column_name",
    )
    .bind(table)
    .fetch_all(su)
    .await
    .unwrap()
}

async fn events_with_3840(
    client: &reqwest::Client,
    base: &str,
    fixture: &Fixture,
    run: Uuid,
    query: &str,
) -> (u16, Value) {
    let response = client
        .get(format!(
            "{base}/v1/workspaces/{}/agent-runs/{run}/events{query}",
            fixture.workspace
        ))
        .bearer_auth(&fixture.human_jwt)
        .send()
        .await
        .expect("events responds");
    let status = response.status().as_u16();
    (status, response.json().await.unwrap_or(Value::Null))
}

fn kinds_of_3840(body: &Value) -> Vec<String> {
    body["events"]
        .as_array()
        .expect("events array")
        .iter()
        .map(|event| event["kind"].as_str().unwrap().to_string())
        .collect()
}

/// RED PROOF (ADR-0200 증보 2026-10-15 T1/T2/T4/T5, T-S1 ①②③, T-S2 ①②③). One hosted
/// run, driven through the real Agent Port: every call that points at the run —
/// through the handle it handed out or one it was given, refused or not — is one
/// `tool_call` row carrying the tool name, the server's duration and a closed code,
/// and NOTHING else. Calls that point at no run write nothing. The rows put no
/// realtime frame on the channel, do move the panel's 「마지막 보고」, and are served
/// only behind `?include=tools`.
///
/// Tamper table (each edit turns this test red):
///   * drop the handle-argument branch of `attributed_runs`     -> renew/release rows missing
///   * drop the answer branch (`oort_job_start` job handle)     -> job_start row missing
///   * attribute calls with no handle to "the one lease"         -> inbox_read/ping rows appear
///   * drop `tool_call` from `agent_run_event_set_framed`        -> framed = true, a frame row
///   * drop `AND ($4 OR e.kind <> 'tool_call')` in the read      -> default read holds tool_call
///   * add any column to `agent_run_event`/the tally             -> the fixed column lists differ
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn an_oort_call_on_a_run_is_one_row_of_name_time_and_code_and_nothing_else() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();

    // ② the columns are fixed: there is nowhere for an argument or a body to go.
    assert_eq!(
        columns_3840(&su, "agent_run_event").await,
        [
            "actor_member_id",
            "approval_id",
            "code",
            "created_at",
            "duration_ms",
            "framed",
            "kind",
            "run_id",
            "seq",
            "stage",
            "tool",
            "workspace_id"
        ]
    );
    assert_eq!(
        columns_3840(&su, "agent_run_tool_tally").await,
        [
            "duration_ms_sum",
            "error_count",
            "ok_count",
            "run_id",
            "tool",
            "updated_at",
            "workspace_id"
        ]
    );

    // A start with nothing to claim points at no run: nothing is written.
    let (status, nothing) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_job_start",
        json!({}),
    )
    .await;
    assert_eq!(status, 200, "{nothing}");
    assert_eq!(structured(&nothing)["job"], Value::Null);
    assert_eq!(
        workspace_tool_call_count_3840(&su, fixture.workspace).await,
        0
    );

    let run = raise_mention_3831(&client, &base, &su, &fixture, "작업해줘 3840").await;
    let (status, started) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_job_start",
        json!({"stage": "고유표지 확인 중"}),
    )
    .await;
    assert_eq!(status, 200, "{started}");
    let handle = structured(&started)["job"]["leaseHandle"]
        .as_str()
        .expect("lease handle")
        .to_string();

    let renew = |handle: String| {
        let client = client.clone();
        let base = base.clone();
        let bearer = fixture.hosted_bearer.clone();
        async move {
            call(
                &client,
                &base,
                &bearer,
                "oort_job_renew",
                json!({"leaseHandle": handle}),
            )
            .await
        }
    };
    let (status, renewed) = renew(handle.clone()).await;
    assert_eq!(status, 200, "{renewed}");
    let (status, released) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_job_release",
        json!({"leaseHandle": handle}),
    )
    .await;
    assert_eq!(status, 200, "{released}");
    // The lease is gone: the tool refuses — and the call is still this agent's call on
    // this run, so it is recorded with its closed code.
    let (status, lost) = renew(handle.clone()).await;
    assert_eq!(status, 409, "{lost}");
    assert_eq!(error_code(&lost), -32005, "{lost}");

    // Calls that point at no run: a handle that does not open, the inbox, a ping.
    let (status, forged) = renew(format!("momo_lease_v1.{}", "A".repeat(120))).await;
    assert_ne!(status, 200, "{forged}");
    let (status, inbox) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_inbox_read",
        json!({"limit": 5}),
    )
    .await;
    assert_eq!(status, 200, "{inbox}");
    let (status, pinged) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_ping",
        json!({}),
    )
    .await;
    assert_eq!(status, 200, "{pinged}");

    // ① one row per attributed call, in call order, with nothing but name/time/code.
    let rows = tool_calls_3840(&su, fixture.workspace, run).await;
    let shape: Vec<(&str, &str)> = rows
        .iter()
        .map(|row| (row.0.as_str(), row.1.as_str()))
        .collect();
    assert_eq!(
        shape,
        [
            ("oort_job_start", "ok"),
            ("oort_job_renew", "ok"),
            ("oort_job_release", "ok"),
            ("oort_job_renew", "conflict"),
        ],
        "③ the forged handle, the inbox read and the ping wrote nothing"
    );
    for row in &rows {
        assert!((0..=600_000).contains(&row.2), "duration {}", row.2);
        assert_eq!(row.3, None, "no stage on a tool_call row");
        assert_eq!(row.4, None, "no approval on a tool_call row");
        assert_eq!(row.5, Some(fixture.hosted_agent), "the acting agent");
        assert!(!row.6, "T5: a tool_call row is never framed");
    }
    assert_eq!(
        workspace_tool_call_count_3840(&su, fixture.workspace).await,
        4 + 3,
        "four rows and three tally lines in the whole workspace — nothing elsewhere"
    );
    assert_eq!(
        tally_3840(&su, fixture.workspace, run).await,
        [
            ("oort_job_release".to_string(), 1, 0, i64::from(rows[2].2)),
            (
                "oort_job_renew".to_string(),
                1,
                1,
                i64::from(rows[1].2) + i64::from(rows[3].2)
            ),
            ("oort_job_start".to_string(), 1, 0, i64::from(rows[0].2)),
        ]
    );
    // ② no handle, no argument and no channel/message id sits in any tool_call row.
    let dumps: Vec<String> = sqlx::query_scalar(
        "SELECT row_to_json(e)::text FROM agent_run_event e \
          WHERE workspace_id=$1 AND run_id=$2 AND kind='tool_call'",
    )
    .bind(fixture.workspace)
    .bind(run)
    .fetch_all(&su)
    .await
    .unwrap();
    for dump in &dumps {
        for secret in [
            handle.as_str(),
            "고유표지",
            "작업해줘",
            &fixture.channel.to_string(),
        ] {
            assert!(!dump.contains(secret), "{secret} leaked into {dump}");
        }
    }
    // T5: no realtime frame names `tool_call`.
    let frames: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM outbox WHERE workspace_id=$1 \
            AND payload #>> '{data,type}' = 'agent.run.event' \
            AND payload #>> '{data,payload,kind}' = 'tool_call'",
    )
    .bind(fixture.workspace)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(frames, 0);
    // T5: the panel's 「마지막 보고」 does include the call (the last row is a tool_call).
    let (status, progress) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "",
    )
    .await;
    assert_eq!(status, 200, "{progress}");
    let last_call_ms = rows[3].7.timestamp_millis();
    let line = progress["runs"]
        .as_array()
        .unwrap()
        .iter()
        .find(|line| line["id"] == json!(run.to_string()))
        .expect("the run's progress line");
    assert_eq!(line["lastEventAtMs"], json!(last_call_ms), "{line}");

    // T-S2 ①: a client that predates the kind reads a ledger it can parse.
    let (status, plain) = events_with_3840(&client, &base, &fixture, run, "").await;
    assert_eq!(status, 200, "{plain}");
    assert!(
        !kinds_of_3840(&plain).contains(&"tool_call".to_string()),
        "{plain}"
    );
    let object = plain.as_object().unwrap();
    assert!(!object.contains_key("toolTally") && !object.contains_key("toolCallRowsCapped"));
    assert!(!plain.to_string().contains("durationMs"));

    // `include=tools`: the rows, the tally, and whether the cap was reached.
    let (status, with_tools) =
        events_with_3840(&client, &base, &fixture, run, "?include=tools").await;
    assert_eq!(status, 200, "{with_tools}");
    let tool_events: Vec<&Value> = with_tools["events"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|event| event["kind"] == json!("tool_call"))
        .collect();
    assert_eq!(tool_events.len(), 4, "{with_tools}");
    assert_eq!(tool_events[3]["tool"], json!("oort_job_renew"));
    assert_eq!(tool_events[3]["code"], json!("conflict"));
    assert_eq!(tool_events[3]["durationMs"], json!(rows[3].2));
    assert!(tool_events[0].get("stage").is_none());
    assert_eq!(
        with_tools["toolTally"],
        json!([
            {"tool": "oort_job_release", "ok": 1, "error": 0, "durationMsSum": rows[2].2},
            {"tool": "oort_job_renew", "ok": 1, "error": 1, "durationMsSum": rows[1].2 + rows[3].2},
            {"tool": "oort_job_start", "ok": 1, "error": 0, "durationMsSum": rows[0].2},
        ])
    );
    assert_eq!(with_tools["toolCallRowsCapped"], json!(false));
    assert!(!kinds_of_3840(&with_tools).contains(&"doorbell_rung".to_string()));

    // T-S2 ②: the two opt-ins combine.
    sqlx::query("SELECT agent_run_event_append($1,$2,'doorbell_rung',NULL,'leading_ok',NULL,NULL)")
        .bind(fixture.workspace)
        .bind(run)
        .execute(&su)
        .await
        .unwrap();
    let (status, both) =
        events_with_3840(&client, &base, &fixture, run, "?include=doorbell,tools").await;
    assert_eq!(status, 200, "{both}");
    let kinds = kinds_of_3840(&both);
    assert!(
        kinds.contains(&"tool_call".to_string()) && kinds.contains(&"doorbell_rung".to_string())
    );
    let (_, doorbell_only) =
        events_with_3840(&client, &base, &fixture, run, "?include=doorbell").await;
    let kinds = kinds_of_3840(&doorbell_only);
    assert!(
        !kinds.contains(&"tool_call".to_string()) && kinds.contains(&"doorbell_rung".to_string())
    );
    assert!(doorbell_only.get("toolTally").is_none());

    // T-S2 ③: an unknown value is a 400, alone or beside a known one.
    for query in ["?include=bogus", "?include=tools,bogus", "?include=tool"] {
        let (status, refused) = events_with_3840(&client, &base, &fixture, run, query).await;
        assert_eq!(status, 400, "{query}: {refused}");
    }
}

/// RED PROOF (ADR-0200 증보 2026-10-15 T3, T-S1 ④⑤). Past 100 `tool_call` rows on a run
/// the ledger stops growing and only the tally moves — and nothing is deleted to make
/// room: the 200-row trim neither counts nor deletes `tool_call` rows.
///
/// Tamper table:
///   * drop `IF v_rows >= 100` in `agent_run_tool_call_record`  -> 102 rows, not 100
///   * move the tally UPSERT below the cap's RETURN              -> tally sum 100, not 102
///   * drop `AND kind <> 'tool_call'` from the trim's count     -> only 100 stage/lifecycle rows survive
///   * add `tool_call` to the trim's DELETE                      -> tool_call rows vanish
///   * drop the tally DELETE from `delete_expired_run_events_in_tx` -> a swept run keeps its tally
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn the_hundred_and_first_call_moves_only_the_tally_and_nothing_is_deleted() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (handle, run) = claimed_run_3516(&client, &base, &su, &fixture).await;

    for n in 0..101 {
        let (status, renewed) = call(
            &client,
            &base,
            &fixture.hosted_bearer,
            "oort_job_renew",
            json!({"leaseHandle": handle}),
        )
        .await;
        assert_eq!(status, 200, "renew {n}: {renewed}");
    }
    // 1 claim + 101 renews = 102 calls; the ledger keeps the first 100.
    let rows = tool_calls_3840(&su, fixture.workspace, run).await;
    assert_eq!(rows.len() as i64, momo_agent::TOOL_CALL_ROWS_PER_RUN);
    assert_eq!(
        rows[0].0, "oort_jobs_claim",
        "jobs_claim attributes through its answer"
    );
    let tally = tally_3840(&su, fixture.workspace, run).await;
    assert_eq!(
        tally
            .iter()
            .map(|row| (row.0.as_str(), row.1, row.2))
            .collect::<Vec<_>>(),
        [("oort_job_renew", 101, 0), ("oort_jobs_claim", 1, 0)],
        "every call is counted, past the row cap too"
    );
    let (status, ledger) = events_with_3840(&client, &base, &fixture, run, "?include=tools").await;
    assert_eq!(status, 200, "{ledger}");
    assert_eq!(ledger["toolCallRowsCapped"], json!(true));
    assert_eq!(
        kinds_of_3840(&ledger)
            .iter()
            .filter(|kind| *kind == "tool_call")
            .count(),
        100
    );

    // ⑤ 250 stage markers: the trim keeps 200 non-tool rows and never touches the
    // 100 tool_call rows — not counting them, not deleting them.
    for n in 0..250 {
        sqlx::query("SELECT agent_run_event_append($1,$2,'stage',$3,NULL,NULL,$4)")
            .bind(fixture.workspace)
            .bind(run)
            .bind(format!("단계 {n}"))
            .bind(fixture.hosted_agent)
            .execute(&su)
            .await
            .unwrap();
        sqlx::query("SELECT agent_run_event_trim($1,$2)")
            .bind(fixture.workspace)
            .bind(run)
            .execute(&su)
            .await
            .unwrap();
    }
    let (others, calls): (i64, i64) = sqlx::query_as(
        "SELECT count(*) FILTER (WHERE kind <> 'tool_call'), count(*) FILTER (WHERE kind = 'tool_call') \
           FROM agent_run_event WHERE workspace_id=$1 AND run_id=$2",
    )
    .bind(fixture.workspace)
    .bind(run)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!((others, calls), (200, 100));
    // The read still serves all of it (200 + 100) with `include=tools`, and the default
    // read stays the 200 rows an older client expects.
    let (_, ledger) = events_with_3840(&client, &base, &fixture, run, "?include=tools").await;
    assert_eq!(ledger["events"].as_array().unwrap().len(), 300);
    let (_, plain) = events_with_3840(&client, &base, &fixture, run, "").await;
    assert_eq!(plain["events"].as_array().unwrap().len(), 200);

    // Lifetime, not cap: a run that goes takes its rows and its tally with it — as the
    // production role under RLS (the ledger's delete trigger, the tally's FK CASCADE).
    let gone: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status) \
         VALUES ($1,$2,$3,'queued') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    let app = momo_app_pool().await;
    let mut tx = app.begin().await.unwrap();
    sqlx::query("SELECT set_config('app.workspace_id', $1, true)")
        .bind(fixture.workspace.to_string())
        .execute(&mut *tx)
        .await
        .unwrap();
    let recorded: String =
        sqlx::query_scalar("SELECT agent_run_tool_call_record($1,$2,$3,'oort_job_renew',7,'ok')")
            .bind(fixture.workspace)
            .bind(gone)
            .bind(fixture.hosted_agent)
            .fetch_one(&mut *tx)
            .await
            .unwrap();
    assert_eq!(recorded, "row");
    sqlx::query("DELETE FROM agent_run WHERE id=$1")
        .bind(gone)
        .execute(&mut *tx)
        .await
        .expect("momo_app may delete a run with tool calls");
    tx.commit().await.unwrap();
    assert!(tool_calls_3840(&su, fixture.workspace, gone)
        .await
        .is_empty());
    assert!(tally_3840(&su, fixture.workspace, gone).await.is_empty());

    // …and the retention sweep (ADR-0200 D2) takes a long-finished run's tally along
    // with its ledger: the cross-tenant read finds the workspace by the tally alone, and
    // the RLS-bound delete clears it.
    let old: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status) \
         VALUES ($1,$2,$3,'queued') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    let mut tx = app.begin().await.unwrap();
    sqlx::query("SELECT set_config('app.workspace_id', $1, true)")
        .bind(fixture.workspace.to_string())
        .execute(&mut *tx)
        .await
        .unwrap();
    sqlx::query("SELECT agent_run_tool_call_record($1,$2,$3,'oort_job_renew',7,'ok')")
        .bind(fixture.workspace)
        .bind(old)
        .bind(fixture.hosted_agent)
        .execute(&mut *tx)
        .await
        .unwrap();
    tx.commit().await.unwrap();
    // Only the tally is left (a ledger already swept), and the run finished long ago.
    sqlx::query("DELETE FROM agent_run_event WHERE run_id=$1")
        .bind(old)
        .execute(&su)
        .await
        .unwrap();
    sqlx::query(
        "UPDATE agent_run SET status='succeeded', finished_at = now() - interval '31 days' \
          WHERE id=$1",
    )
    .bind(old)
    .execute(&su)
    .await
    .unwrap();
    let notifier = momo_notifier_pool().await;
    let mut read = notifier.acquire().await.unwrap();
    let due = momo_agent::workspaces_with_expired_run_events(&mut read, 1000)
        .await
        .unwrap();
    drop(read);
    assert!(
        due.contains(&fixture.workspace),
        "the tally alone makes the workspace due"
    );
    let workspace = fixture.workspace;
    momo_db::with_tenant_tx(&app, workspace, move |conn| {
        Box::pin(
            async move { momo_agent::delete_expired_run_events_in_tx(conn, workspace, 1000).await },
        )
    })
    .await
    .unwrap();
    assert!(tally_3840(&su, fixture.workspace, old).await.is_empty());
}

/// RED PROOF (ADR-0200 증보 2026-10-15 T1/T2, T-S1 ⑥). The tally and the rows are
/// tenant data under RLS FORCE: another workspace's `momo_app` session sees none of
/// it and cannot write into it, a foreign handle records nothing, and the recorder
/// refuses a run that is not the acting agent's. The CHECKs refuse any row that is
/// not name/time/closed code.
///
/// Tamper table:
///   * `ALTER TABLE agent_run_tool_tally DISABLE ROW LEVEL SECURITY` -> the other tenant reads/writes it
///   * drop the `agent_member_id = p_actor` test in the recorder     -> the other agent's record lands
///   * drop the workspace/agent test in `attributed_runs` AND the SQL actor test -> the foreign handle records
///   * relax `agent_run_event_tool_call_ck`                          -> the bad rows insert
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn another_tenant_neither_reads_nor_writes_the_tool_call_record() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let other = seed(&su).await;
    let base = start_server(app.clone(), true).await;
    let client = reqwest::Client::new();
    let (handle, run) = claimed_run_3516(&client, &base, &su, &fixture).await;
    assert_eq!(tool_calls_3840(&su, fixture.workspace, run).await.len(), 1);

    // The other tenant's agent presents this tenant's handle: refused, nothing recorded.
    let (status, refused) = call(
        &client,
        &base,
        &other.hosted_bearer,
        "oort_job_renew",
        json!({"leaseHandle": handle}),
    )
    .await;
    assert_ne!(status, 200, "{refused}");
    assert_eq!(tool_calls_3840(&su, fixture.workspace, run).await.len(), 1);
    assert_eq!(
        workspace_tool_call_count_3840(&su, other.workspace).await,
        0
    );

    // Under the other tenant's GUC, as the production role: nothing to read, nothing to write.
    let mut tx = app.begin().await.unwrap();
    sqlx::query("SELECT set_config('app.workspace_id', $1, true)")
        .bind(other.workspace.to_string())
        .execute(&mut *tx)
        .await
        .unwrap();
    let seen: i64 = sqlx::query_scalar(
        "SELECT (SELECT count(*) FROM agent_run_tool_tally WHERE run_id=$1) \
              + (SELECT count(*) FROM agent_run_event WHERE run_id=$1 AND kind='tool_call')",
    )
    .bind(run)
    .fetch_one(&mut *tx)
    .await
    .unwrap();
    assert_eq!(seen, 0, "RLS hides another tenant's tool calls");
    let recorded: String =
        sqlx::query_scalar("SELECT agent_run_tool_call_record($1,$2,$3,'oort_job_renew',5,'ok')")
            .bind(fixture.workspace)
            .bind(run)
            .bind(fixture.hosted_agent)
            .fetch_one(&mut *tx)
            .await
            .unwrap();
    assert_eq!(
        recorded, "skipped",
        "the run is invisible from another tenant"
    );
    let forged = sqlx::query(
        "INSERT INTO agent_run_tool_tally (workspace_id, run_id, tool, ok_count) \
         VALUES ($1,$2,'oort_job_renew',1)",
    )
    .bind(fixture.workspace)
    .bind(run)
    .execute(&mut *tx)
    .await;
    assert!(forged.is_err(), "WITH CHECK refuses a foreign workspace id");
    drop(tx);

    // Same tenant, another agent: the recorder refuses a run that is not the actor's.
    let mut tx = app.begin().await.unwrap();
    sqlx::query("SELECT set_config('app.workspace_id', $1, true)")
        .bind(fixture.workspace.to_string())
        .execute(&mut *tx)
        .await
        .unwrap();
    let recorded: String =
        sqlx::query_scalar("SELECT agent_run_tool_call_record($1,$2,$3,'oort_job_renew',5,'ok')")
            .bind(fixture.workspace)
            .bind(run)
            .bind(fixture.managed_agent)
            .fetch_one(&mut *tx)
            .await
            .unwrap();
    assert_eq!(recorded, "skipped");
    tx.commit().await.unwrap();
    let tally = tally_3840(&su, fixture.workspace, run).await;
    assert_eq!(
        tally
            .iter()
            .map(|row| (row.0.as_str(), row.1, row.2))
            .collect::<Vec<_>>(),
        [("oort_jobs_claim", 1, 0)],
        "neither the foreign handle nor the refused records moved the tally"
    );

    // The CHECKs: a tool_call row is name + time + closed code, and only that.
    for (tool, duration, code, stage) in [
        (Some("evil_tool"), Some(1), Some("ok"), None),
        (Some("oort_job_renew"), Some(-1), Some("ok"), None),
        (Some("oort_job_renew"), Some(600_001), Some("ok"), None),
        (Some("oort_job_renew"), Some(1), Some("timeout"), None),
        (Some("oort_job_renew"), Some(1), None, None),
        (Some("oort_job_renew"), Some(1), Some("ok"), Some("단계")),
        (None, Some(1), Some("ok"), None),
        (Some("oort_job_renew"), None, Some("ok"), None),
    ] {
        let inserted = sqlx::query(
            "INSERT INTO agent_run_event (workspace_id, run_id, kind, tool, duration_ms, code, stage) \
             VALUES ($1,$2,'tool_call',$3,$4,$5,$6)",
        )
        .bind(fixture.workspace)
        .bind(run)
        .bind(tool)
        .bind(duration)
        .bind(code)
        .bind(stage)
        .execute(&su)
        .await;
        assert!(
            inserted.is_err(),
            "{tool:?} {duration:?} {code:?} {stage:?}"
        );
    }
    let inserted = sqlx::query(
        "INSERT INTO agent_run_event (workspace_id, run_id, kind, tool, duration_ms) \
         VALUES ($1,$2,'claimed','oort_job_renew',1)",
    )
    .bind(fixture.workspace)
    .bind(run)
    .execute(&su)
    .await;
    assert!(
        inserted.is_err(),
        "tool/duration exist only on tool_call rows"
    );
}

/// RED PROOF (ADR-0200 증보 2026-10-15 T1, T-S1 ⑦). The record is an observation in
/// its own transaction: when it fails, the tool's answer is exactly what it would have
/// been, the failure is logged, and nothing half-written is left behind.
///
/// Tamper table:
///   * panic / map the record failure into the tool result      -> the renew is not a 200 `renewed`
///   * write the record inside the tool's own transaction        -> the renew rolls back (409/500)
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_failed_tool_call_record_does_not_change_the_tool_answer() {
    ensure_schema_and_roles();
    let capture = log_capture();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (handle, run) = claimed_run_3516(&client, &base, &su, &fixture).await;
    let before = tool_calls_3840(&su, fixture.workspace, run).await.len();

    // Break the recorder for the production role only.
    sqlx::query("REVOKE INSERT, UPDATE ON agent_run_tool_tally FROM momo_app")
        .execute(&su)
        .await
        .unwrap();
    let offset = capture_offset(&capture);
    let (status, renewed) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_job_renew",
        json!({"leaseHandle": handle}),
    )
    .await;
    sqlx::query("GRANT INSERT, UPDATE ON agent_run_tool_tally TO momo_app")
        .execute(&su)
        .await
        .unwrap();
    assert_eq!(status, 200, "{renewed}");
    assert_eq!(
        structured(&renewed)["status"],
        json!("renewed"),
        "{renewed}"
    );
    assert!(
        captured_since(&capture, offset).contains("agent port tool_call record failed"),
        "the failure is logged"
    );
    assert_eq!(
        tool_calls_3840(&su, fixture.workspace, run).await.len(),
        before,
        "the failed record left no half-written row"
    );

    // The grant restored, the next call records again.
    let (status, _) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_job_renew",
        json!({"leaseHandle": handle}),
    )
    .await;
    assert_eq!(status, 200);
    assert_eq!(
        tool_calls_3840(&su, fixture.workspace, run).await.len(),
        before + 1
    );
}

// ---------------------------------------------------------------------------
// (#3741 S2, ADR-0200 D1/D2/D3) the honest read side
// ---------------------------------------------------------------------------

async fn progress_3741(
    client: &reqwest::Client,
    base: &str,
    jwt: &str,
    fixture: &Fixture,
    channel: Uuid,
    query: &str,
) -> (u16, Value) {
    let response = client
        .get(format!(
            "{base}/v1/workspaces/{}/channels/{channel}/agent-runs/progress{query}",
            fixture.workspace
        ))
        .bearer_auth(jwt)
        .send()
        .await
        .expect("progress responds");
    let status = response.status().as_u16();
    (status, response.json().await.unwrap_or(Value::Null))
}

async fn events_3741(
    client: &reqwest::Client,
    base: &str,
    jwt: &str,
    fixture: &Fixture,
    run: &str,
) -> (u16, Value) {
    let response = client
        .get(format!(
            "{base}/v1/workspaces/{}/agent-runs/{run}/events",
            fixture.workspace
        ))
        .bearer_auth(jwt)
        .send()
        .await
        .expect("events responds");
    let status = response.status().as_u16();
    (status, response.json().await.unwrap_or(Value::Null))
}

fn only_run_3741(body: &Value) -> &Value {
    let runs = body["runs"].as_array().expect("runs array");
    assert_eq!(runs.len(), 1, "{body}");
    &runs[0]
}

/// RED PROOF (ADR-0200 D1/D2, S2). The progress read tells the truth at every
/// step of one hosted run — queued (position 1) → claimed (when, lease live) →
/// running (latest stage) → lease stale (expired, not re-claimed) → succeeded —
/// and the ledger endpoint returns the same story with an ordinal and no raw
/// sequence. This is the 2026-10-13 incident reduced to a test: a run nobody has
/// taken is `queued`, never "working" and never "signal lost".
///
/// Tamper table:
///   * derive `claimed` from the run status instead of the job lease -> claimed step shows `queued`
///   * compute lease_state without the expiry compare               -> the expired lease shows `live`
///   * add `seq` to the event DTO                                   -> the no-seq assertion fails
///   * drop the channel-membership check in the events query         -> the outsider gets 200
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn the_progress_read_tells_the_truth_at_every_step_of_a_hosted_run() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();

    // nothing yet
    let (status, empty) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "",
    )
    .await;
    assert_eq!(status, 200, "{empty}");
    assert_eq!(empty["runs"], json!([]));

    mention_3740(&client, &base, &su, &fixture, fixture.hosted_agent).await;
    let (_, body) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "?state=active",
    )
    .await;
    let run = only_run_3741(&body);
    assert_eq!(run["phase"], json!("queued"), "{body}");
    assert_eq!(run["leaseState"], json!("none"));
    assert_eq!(run["queuePosition"], json!(1));
    assert_eq!(run["aheadTotal"], json!(0));
    assert!(run.get("claimedAtMs").is_none());
    let run_id = run["id"].as_str().unwrap().to_string();

    // claimed: the lease is the fact, run.status is still `queued`
    let (_, claimed) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_jobs_claim",
        json!({"limit": 10}),
    )
    .await;
    let handle = structured(&claimed)["jobs"][0]["leaseHandle"]
        .as_str()
        .unwrap()
        .to_string();
    let (_, body) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "",
    )
    .await;
    let run = only_run_3741(&body);
    assert_eq!(run["status"], json!("queued"));
    assert_eq!(run["phase"], json!("claimed"), "{body}");
    assert_eq!(run["leaseState"], json!("live"));
    assert!(run["claimedAtMs"].as_i64().unwrap() > 0);
    assert!(run.get("queuePosition").is_none(), "no position once taken");

    // taken but silent past the lease: still `claimed` (the run has not started), and the
    // lease is `stale` — "not renewed", with no queue position (it is not in the queue)
    sqlx::query(
        "UPDATE outbox SET lease_acquired_at = now() - interval '35 minutes', \
                lease_expires_at = now() - interval '5 minutes' \
          WHERE workspace_id=$1 AND kind='agent_job' AND partition_key=$2",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .execute(&su)
    .await
    .unwrap();
    let (_, body) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "",
    )
    .await;
    let run = only_run_3741(&body);
    assert_eq!(run["phase"], json!("claimed"), "{body}");
    assert_eq!(run["leaseState"], json!("stale"));
    assert!(run.get("queuePosition").is_none());

    // the agent comes back and renews the expired-but-unreclaimed handle (ADR-0162 A3):
    // the lease lives again, same job, same handle
    let (status, renewed) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_job_renew",
        json!({"leaseHandle": handle}),
    )
    .await;
    assert_eq!(status, 200, "{renewed}");
    let (_, body) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "",
    )
    .await;
    assert_eq!(only_run_3741(&body)["leaseState"], json!("live"), "{body}");

    // running with a stage
    let (status, event) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_run_event",
        json!({"leaseHandle": handle, "status": "running", "stage": "채널 이름 확인",
               "eventId": Uuid::new_v4()}),
    )
    .await;
    assert_eq!(status, 200, "{event}");
    let (_, body) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "",
    )
    .await;
    let run = only_run_3741(&body);
    assert_eq!(run["phase"], json!("running"));
    assert_eq!(run["latestStage"], json!("채널 이름 확인"));
    assert_eq!(run["leaseState"], json!("live"));

    // the lease expires and nobody re-claims: stale, and still `running` — a server
    // fact ("lease not renewed"), never the client's "signal lost"
    sqlx::query(
        "UPDATE outbox SET lease_acquired_at = now() - interval '35 minutes', \
                lease_expires_at = now() - interval '5 minutes' \
          WHERE workspace_id=$1 AND kind='agent_job' AND partition_key=$2",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .execute(&su)
    .await
    .unwrap();
    let (_, body) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "",
    )
    .await;
    let run = only_run_3741(&body);
    assert_eq!(run["phase"], json!("running"));
    assert_eq!(run["leaseState"], json!("stale"), "{body}");

    // finished
    let (status, done) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_run_complete",
        json!({"leaseHandle": handle, "status": "succeeded", "body": "done"}),
    )
    .await;
    assert_eq!(status, 200, "{done}");
    let (_, body) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "?state=active",
    )
    .await;
    assert_eq!(body["runs"], json!([]), "a finished run is not active");
    let (_, body) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "?state=all",
    )
    .await;
    let run = only_run_3741(&body);
    assert_eq!(run["phase"], json!("succeeded"));
    assert!(run["finishedAtMs"].as_i64().unwrap() > 0);

    // the ledger: same story, ordinals, no raw sequence
    let (status, ledger) = events_3741(&client, &base, &fixture.human_jwt, &fixture, &run_id).await;
    assert_eq!(status, 200, "{ledger}");
    let events = ledger["events"].as_array().unwrap();
    let kinds: Vec<&str> = events.iter().map(|e| e["kind"].as_str().unwrap()).collect();
    assert_eq!(
        kinds,
        ["queued", "claimed", "started", "stage", "succeeded"]
    );
    assert_eq!(
        events
            .iter()
            .map(|e| e["ordinal"].as_i64().unwrap())
            .collect::<Vec<_>>(),
        [1, 2, 3, 4, 5]
    );
    assert_eq!(events[3]["stage"], json!("채널 이름 확인"));
    let rendered = serde_json::to_string(&ledger).unwrap();
    assert!(
        !rendered.contains("\"seq\""),
        "the global sequence never leaves: {rendered}"
    );

    // a stranger to the channel and an unknown run are the same 404; a bad id is a 400
    let outsider = seed_outsider_3741(&su, &fixture).await;
    let (status, _) = events_3741(&client, &base, &outsider, &fixture, &run_id).await;
    assert_eq!(status, 404);
    let (status, _) = events_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        &Uuid::new_v4().to_string(),
    )
    .await;
    assert_eq!(status, 404);
    let (status, _) = events_3741(&client, &base, &fixture.human_jwt, &fixture, "nope").await;
    assert_eq!(status, 400);
    let (status, _) = progress_3741(&client, &base, &outsider, &fixture, fixture.channel, "").await;
    assert_eq!(status, 403, "progress is for channel members");
    let (status, _) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "?state=bogus",
    )
    .await;
    assert_eq!(status, 400);
}

/// A workspace member who is in NO channel with the agent.
async fn seed_outsider_3741(pool: &PgPool, fixture: &Fixture) -> String {
    let jwt = seed_plain_member(pool, fixture).await;
    // seed_plain_member joins `channel`; this outsider leaves it again
    sqlx::query(
        "UPDATE membership SET left_at = now() \
          WHERE workspace_id=$1 AND channel_id=$2 AND member_id <> $3 \
            AND member_id NOT IN (SELECT id FROM member WHERE kind='agent') \
            AND member_id <> $4",
    )
    .bind(fixture.workspace)
    .bind(fixture.channel)
    .bind(fixture.human)
    .bind(fixture.human)
    .execute(pool)
    .await
    .unwrap();
    jwt
}

/// RED PROOF (ADR-0200 D3, S2). Two members ask the same agent for work in two
/// different channels. The queue is the agent's real claim order; the second run
/// is position 2 for everyone; but a member of only the second channel is never
/// told WHICH run is ahead — a count, never a name — while a member of both is.
///
/// Tamper table:
///   * order the queue by anything other than `outbox.id`            -> positions swap
///   * return `ahead` without the viewer's membership filter          -> the outsider sees the other channel's run id
///   * count only the viewer's visible runs for `aheadTotal`          -> the outsider is told position 1 / total 0
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn the_queue_shows_the_claim_order_and_names_only_runs_the_viewer_can_see() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    // both channels are approved for the hosted agent
    sqlx::query(
        "UPDATE hosted_agent_connection SET approved_channel_ids = $3 \
          WHERE workspace_id=$1 AND id=$2",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_connection)
    .bind(vec![fixture.channel, fixture.private_channel])
    .execute(&su)
    .await
    .unwrap();
    let plain_jwt = seed_plain_member(&su, &fixture).await; // member of `channel` only
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let handle = hosted_handle(&su, fixture.hosted_agent).await;

    for channel in [fixture.private_channel, fixture.channel] {
        let sent: Value = client
            .post(format!(
                "{base}/v1/workspaces/{}/channels/{channel}/messages",
                fixture.workspace
            ))
            .bearer_auth(&fixture.human_jwt)
            .json(&json!({"clientMsgId": Uuid::new_v4(), "body": format!("@{handle} go")}))
            .send()
            .await
            .unwrap()
            .json()
            .await
            .unwrap();
        assert!(sent["id"].is_string(), "{sent}");
    }
    // The queue is the CLAIM order (outbox.id), not creation time: make the second run
    // look OLDER than the first, so ordering by created_at would swap the positions.
    sqlx::query(
        "UPDATE agent_run SET created_at = created_at - interval '2 hours' \
          WHERE workspace_id=$1 AND channel_id=$2",
    )
    .bind(fixture.workspace)
    .bind(fixture.channel)
    .execute(&su)
    .await
    .unwrap();
    let private_run: String = sqlx::query_scalar(
        "SELECT id::text FROM agent_run WHERE workspace_id=$1 AND channel_id=$2",
    )
    .bind(fixture.workspace)
    .bind(fixture.private_channel)
    .fetch_one(&su)
    .await
    .unwrap();

    // the plain member sees position 2 and ONE run ahead — as a count only
    let (status, body) =
        progress_3741(&client, &base, &plain_jwt, &fixture, fixture.channel, "").await;
    assert_eq!(status, 200, "{body}");
    let run = only_run_3741(&body);
    assert_eq!(run["queuePosition"], json!(2), "{body}");
    assert_eq!(run["aheadTotal"], json!(1));
    assert!(
        run.get("ahead").is_none(),
        "the other channel's run is not named: {body}"
    );
    assert!(
        !serde_json::to_string(&body).unwrap().contains(&private_run),
        "the other channel's run id never reaches a non-member"
    );

    // the human is in both channels: the same run, now named
    let (_, body) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "",
    )
    .await;
    let run = only_run_3741(&body);
    assert_eq!(run["queuePosition"], json!(2));
    assert_eq!(run["ahead"].as_array().unwrap().len(), 1, "{body}");
    assert_eq!(
        run["ahead"][0]["runId"].as_str().unwrap().to_lowercase(),
        private_run.to_lowercase()
    );

    // once the agent takes the first job the second moves up
    let (_, claimed) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_jobs_claim",
        json!({"limit": 1}),
    )
    .await;
    assert_eq!(structured(&claimed)["jobs"].as_array().unwrap().len(), 1);
    let (_, body) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "",
    )
    .await;
    let run = only_run_3741(&body);
    assert_eq!(run["phase"], json!("queued"));
    assert_eq!(run["queuePosition"], json!(1), "{body}");
    assert_eq!(run["aheadTotal"], json!(0));

    // A job the agent could NOT claim (its token was revoked) is waiting but has no honest
    // position: none is given, instead of a confident "1st" for work nobody can take.
    sqlx::query("UPDATE token SET revoked_at = now() WHERE id=$1")
        .bind(fixture.hosted_token)
        .execute(&su)
        .await
        .unwrap();
    let (_, body) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "",
    )
    .await;
    let run = only_run_3741(&body);
    assert_eq!(run["phase"], json!("queued"), "{body}");
    assert!(
        run.get("queuePosition").is_none(),
        "unclaimable => no position: {body}"
    );
}

/// RED PROOF (ADR-0200 D1/D2, S2). A finished run's `endReason` is the closed machine
/// code the server wrote and nothing else (a malformed or non-string code is dropped,
/// not echoed); `limit` bounds the page; and another tenant's channel and runs are
/// invisible — 403 for the channel, 404 for the ledger.
///
/// Tamper table:
///   * drop the `end_reason` regex                           -> the malformed code is echoed
///   * select `end_reason` for non-terminal runs too          -> the running run shows a reason
///   * drop the `LIMIT $4`                                    -> `limit=1` returns two runs
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn the_end_reason_is_a_closed_code_and_other_tenants_are_invisible() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let other = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();

    for (status, error) in [
        ("timed_out", Some(json!({"code": "approval_expired"}))),
        ("failed", Some(json!({"code": "Bad Code!"}))),
        ("failed", Some(json!({"code": 5}))),
        ("succeeded", None),
        ("running", Some(json!({"code": "ignored_while_running"}))),
    ] {
        sqlx::query(
            "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status, error) \
             VALUES ($1,$2,$3,$4::run_status,$5)",
        )
        .bind(fixture.workspace)
        .bind(fixture.hosted_agent)
        .bind(fixture.channel)
        .bind(status)
        .bind(error)
        .execute(&su)
        .await
        .unwrap();
    }
    let (status, body) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "?limit=200",
    )
    .await;
    assert_eq!(status, 200, "{body}");
    let mut reasons: Vec<Option<String>> = body["runs"]
        .as_array()
        .unwrap()
        .iter()
        .map(|run| run["endReason"].as_str().map(str::to_string))
        .collect();
    reasons.sort();
    assert_eq!(
        reasons,
        [None, None, None, None, Some("approval_expired".to_string())],
        "only the well-formed code of a FINISHED run is shown: {body}"
    );
    let (_, one) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        fixture.channel,
        "?limit=1",
    )
    .await;
    assert_eq!(one["runs"].as_array().unwrap().len(), 1);

    // another tenant's channel is not mine; its run's ledger is a 404, same as nothing
    let foreign_run: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status) \
         VALUES ($1,$2,$3,'queued') RETURNING id",
    )
    .bind(other.workspace)
    .bind(other.hosted_agent)
    .bind(other.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    let (status, _) = progress_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        other.channel,
        "",
    )
    .await;
    assert_eq!(status, 403);
    let (status, _) = events_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        &foreign_run.to_string(),
    )
    .await;
    assert_eq!(status, 404);
}

// ---------------------------------------------------------------------------
// (#3742 S3, ADR-0200 D4) liveness and oort_ping
// ---------------------------------------------------------------------------

async fn connection_liveness_3742(
    client: &reqwest::Client,
    base: &str,
    fixture: &Fixture,
) -> Value {
    let response: Value = client
        .get(format!(
            "{base}/v1/workspaces/{}/hosted-agent-connections/{}",
            fixture.workspace, fixture.hosted_connection
        ))
        .bearer_auth(&fixture.human_jwt)
        .send()
        .await
        .expect("connection get")
        .json()
        .await
        .expect("connection body");
    response["connection"]["liveness"].clone()
}

async fn liveness_row_3742(
    pool: &PgPool,
    fixture: &Fixture,
) -> Option<(
    Option<chrono::DateTime<chrono::Utc>>,
    Option<chrono::DateTime<chrono::Utc>>,
    Option<chrono::DateTime<chrono::Utc>>,
    Option<chrono::DateTime<chrono::Utc>>,
    Option<String>,
)> {
    sqlx::query_as(
        "SELECT last_inbox_read_at, last_claim_at, last_ping_at, last_tool_error_at, \
                last_tool_error_code \
           FROM hosted_agent_liveness WHERE workspace_id=$1 AND connection_id=$2",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_connection)
    .fetch_optional(pool)
    .await
    .expect("liveness row")
}

/// RED PROOF (ADR-0200 D4-5, S3; 성재 결재 「생존 신호도 추가」). `oort_ping` proves a
/// runtime is up and nothing more: on its own it is `alive_idle` — "alive, takes no
/// work" — never `responsive`; a second ping inside 30 s is a harmless `recorded:false`
/// that moves nothing; and the work signals (inbox read, a claim that took a job)
/// are what make it `responsive`. Connect-only credentials cannot ping at all.
///
/// Tamper table:
///   * let a ping set a work column / count as work in `derive_liveness` -> ping alone shows `responsive`
///   * drop the 30 s throttle in `record_ping_in_tx`                      -> the second ping is `recorded:true`
///   * record a claim even when the claim returned no job                 -> `last_claim_at` set on an empty claim
///   * require no scope for the tool (drop `SCOPE_INBOX_READ`)            -> the connect-only credential pings
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_ping_proves_alive_not_working_and_the_work_signals_are_throttled() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();

    // never heard from: not "connected", not "alive"
    let liveness = connection_liveness_3742(&client, &base, &fixture).await;
    assert_eq!(liveness["state"], json!("unresponsive"), "{liveness}");
    assert_eq!(liveness["workWaiting"], json!(false));
    assert!(liveness_row_3742(&su, &fixture).await.is_none());

    // the tool is advertised to a credential with the inbox scope, and to nobody else
    assert!(list_tools(&client, &base, &fixture.hosted_bearer)
        .await
        .contains(&"oort_ping".to_string()));
    let (status, refused) = call(
        &client,
        &base,
        &fixture.connect_only_bearer,
        "oort_ping",
        json!({}),
    )
    .await;
    assert!(
        status >= 400,
        "a connect-only credential cannot ping: {refused}"
    );
    assert!(liveness_row_3742(&su, &fixture).await.is_none());

    // a ping: recorded, alive but idle
    let (status, pinged) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_ping",
        json!({"state": "idle"}),
    )
    .await;
    assert_eq!(status, 200, "{pinged}");
    assert_eq!(structured(&pinged)["recorded"], json!(true));
    assert_eq!(structured(&pinged)["minIntervalSeconds"], json!(30));
    let liveness = connection_liveness_3742(&client, &base, &fixture).await;
    assert_eq!(liveness["state"], json!("alive_idle"), "{liveness}");
    assert_eq!(liveness["lastPingState"], json!("idle"));
    assert!(
        liveness.get("lastWorkSignalAtMs").is_none(),
        "a ping is not work: {liveness}"
    );
    let first = liveness_row_3742(&su, &fixture).await.expect("row").2;

    // a second ping inside the window: success, recorded:false, nothing moves
    let (status, again) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_ping",
        json!({"state": "working"}),
    )
    .await;
    assert_eq!(status, 200, "a throttled ping is not an error: {again}");
    assert_eq!(structured(&again)["recorded"], json!(false));
    assert_eq!(liveness_row_3742(&su, &fixture).await.unwrap().2, first);
    let stored_state: Option<String> = sqlx::query_scalar(
        "SELECT last_ping_state FROM hosted_agent_liveness WHERE workspace_id=$1 AND connection_id=$2",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_connection)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(
        stored_state.as_deref(),
        Some("idle"),
        "the throttled call changed nothing"
    );

    // closed arguments
    for bad in [
        json!({"state": "sleeping"}),
        json!({"state": 3}),
        json!({"extra": true}),
    ] {
        let (status, _) = call(&client, &base, &fixture.hosted_bearer, "oort_ping", bad).await;
        assert_eq!(status, 400);
    }

    // an empty claim is not a claim
    let (_, empty) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_jobs_claim",
        json!({}),
    )
    .await;
    assert_eq!(structured(&empty)["jobs"], json!([]));
    assert!(liveness_row_3742(&su, &fixture).await.unwrap().1.is_none());

    // the inbox read is work: responsive, and throttled
    let (status, _) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_inbox_read",
        json!({"limit": 5}),
    )
    .await;
    assert_eq!(status, 200);
    let read = liveness_row_3742(&su, &fixture).await.unwrap().0;
    assert!(read.is_some());
    let liveness = connection_liveness_3742(&client, &base, &fixture).await;
    assert_eq!(liveness["state"], json!("responsive"), "{liveness}");
    let (status, _) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_inbox_read",
        json!({"limit": 5}),
    )
    .await;
    assert_eq!(status, 200);
    assert_eq!(
        liveness_row_3742(&su, &fixture).await.unwrap().0,
        read,
        "a poll inside 30 s writes nothing"
    );

    // a claim that took a job is work, and a queued job is "work waiting" before it
    mention_3740(&client, &base, &su, &fixture, fixture.hosted_agent).await;
    let liveness = connection_liveness_3742(&client, &base, &fixture).await;
    assert_eq!(liveness["workWaiting"], json!(true), "{liveness}");
    // a fresh job is just a polling agent's normal queue; one that has waited past the
    // responsive window while the agent keeps reading its inbox is NOT "responsive"
    assert_eq!(liveness["state"], json!("responsive"), "{liveness}");
    sqlx::query(
        "UPDATE outbox SET created_at = now() - interval '30 minutes' \
          WHERE workspace_id=$1 AND kind='agent_job' AND partition_key=$2",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .execute(&su)
    .await
    .unwrap();
    let liveness = connection_liveness_3742(&client, &base, &fixture).await;
    assert_eq!(liveness["state"], json!("work_waiting"), "{liveness}");
    assert!(liveness["oldestWaitingAtMs"].as_i64().unwrap() > 0);
    let (_, claimed) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_jobs_claim",
        json!({}),
    )
    .await;
    assert_eq!(structured(&claimed)["jobs"].as_array().unwrap().len(), 1);
    assert!(liveness_row_3742(&su, &fixture).await.unwrap().1.is_some());
    let liveness = connection_liveness_3742(&client, &base, &fixture).await;
    assert_eq!(liveness["workWaiting"], json!(false));
}

/// RED PROOF (ADR-0200 D4, S3). The refusal that explains "Agent Port unavailable" is
/// kept as a closed code on the caller's own connection, turns the state to `error`
/// while it is the newest fact, and ends with the next accepted call of any kind — the
/// throttle on the work columns must not keep a recovered agent red. A lost lease or a
/// bad argument is the agent's own flow and is not an `error`. Members see the label
/// only; a stranger and a non-hosted agent are the same 404.
///
/// Tamper table:
///   * record every failure kind                          -> the bad-argument call turns the state to `error`
///   * compare the refusal only to the throttled work columns -> the recovery stays `error`
///   * return `lastToolErrorCode` to the member route      -> the member body carries the code
///   * answer 403 for the non-hosted agent                 -> existence of hosting is probeable
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_refusal_is_a_closed_code_that_recovers_and_members_see_the_label_only() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();

    // an accepted call first
    let (status, _) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_inbox_read",
        json!({}),
    )
    .await;
    assert_eq!(status, 200);

    // a bad argument is the agent's flow, not a connection fault
    let (status, _) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_inbox_read",
        json!({"limit": 0}),
    )
    .await;
    assert_eq!(status, 400);
    assert!(liveness_row_3742(&su, &fixture).await.unwrap().3.is_none());

    // …and so is a lost lease: renewing a handle the agent itself released answers 409
    // `Conflict` from INSIDE the tool (the case a record-every-failure bug would catch;
    // the schema 400 above never reaches the tool at all)
    mention_3740(&client, &base, &su, &fixture, fixture.hosted_agent).await;
    let (_, claimed) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_jobs_claim",
        json!({}),
    )
    .await;
    let handle = structured(&claimed)["jobs"][0]["leaseHandle"]
        .as_str()
        .unwrap()
        .to_string();
    let (status, _) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_job_release",
        json!({"leaseHandle": handle}),
    )
    .await;
    assert_eq!(status, 200);
    let (status, lost) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_job_renew",
        json!({"leaseHandle": handle}),
    )
    .await;
    assert_eq!(status, 409, "{lost}");
    assert!(
        liveness_row_3742(&su, &fixture).await.unwrap().3.is_none(),
        "a lost lease is the agent's own flow, not a connection error"
    );

    // a refusal about the connection: an unapproved channel is "unavailable"
    let (status, refused) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_conversation_read",
        json!({"channelId": fixture.private_channel}),
    )
    .await;
    assert!(status >= 400, "{refused}");
    let (_, _, _, errored, code) = liveness_row_3742(&su, &fixture).await.unwrap();
    assert!(errored.is_some());
    assert!(
        matches!(
            code.as_deref(),
            Some("unavailable") | Some("not_authorized")
        ),
        "a closed code: {code:?}"
    );
    let liveness = connection_liveness_3742(&client, &base, &fixture).await;
    assert_eq!(liveness["state"], json!("error"), "{liveness}");
    assert_eq!(liveness["lastToolErrorCode"], json!(code.clone().unwrap()));

    // any accepted call ends it — even one the 30 s work-column throttle would swallow
    let (status, _) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_inbox_read",
        json!({}),
    )
    .await;
    assert_eq!(status, 200);
    let liveness = connection_liveness_3742(&client, &base, &fixture).await;
    assert_ne!(liveness["state"], json!("error"), "recovered: {liveness}");

    // the SAME refusal again, seconds later: a new fact, not swallowed by the 30 s
    // throttle (a flapping "unavailable" must not read as fine)
    let (status, _) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_conversation_read",
        json!({"channelId": fixture.private_channel}),
    )
    .await;
    assert!(status >= 400);
    let liveness = connection_liveness_3742(&client, &base, &fixture).await;
    assert_eq!(
        liveness["state"],
        json!("error"),
        "flapping stays visible: {liveness}"
    );
    let (status, _) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_inbox_read",
        json!({}),
    )
    .await;
    assert_eq!(status, 200);

    // the member-facing label
    let plain_jwt = seed_plain_member(&su, &fixture).await; // shares `channel` with the agent
    let url = format!(
        "{base}/v1/workspaces/{}/agents/{}/liveness",
        fixture.workspace, fixture.hosted_agent
    );
    let member: Value = client
        .get(&url)
        .bearer_auth(&plain_jwt)
        .send()
        .await
        .unwrap()
        .json()
        .await
        .unwrap();
    assert_eq!(
        member["agentMemberId"].as_str().unwrap().to_lowercase(),
        fixture.hosted_agent.to_string()
    );
    assert!(member["state"].is_string());
    let rendered = serde_json::to_string(&member).unwrap();
    for hidden in ["lastToolError", "lastPing", "doorbell", "workWaiting"] {
        assert!(
            !rendered.contains(hidden),
            "members see the label only: {rendered}"
        );
    }

    // a managed agent (no hosted connection) and a stranger: the same 404
    let managed = client
        .get(format!(
            "{base}/v1/workspaces/{}/agents/{}/liveness",
            fixture.workspace, fixture.managed_agent
        ))
        .bearer_auth(&plain_jwt)
        .send()
        .await
        .unwrap();
    assert_eq!(managed.status().as_u16(), 404);
    let stranger = seed_outsider_3741(&su, &fixture).await;
    let outsider = client
        .get(&url)
        .bearer_auth(&stranger)
        .send()
        .await
        .unwrap();
    assert_eq!(outsider.status().as_u16(), 404);
}

// ---------------------------------------------------------------------------
// (#3744 S5, ADR-0200 D1-4 / D2) stall sweep, realtime frame, retention
// ---------------------------------------------------------------------------

/// Age a hosted run as if its agent went quiet `hours` ago: the lease expired then and the
/// run saw its last event then.
async fn age_run_3744(pool: &PgPool, fixture: &Fixture, run: Uuid, hours: i64) {
    sqlx::query(
        "UPDATE outbox SET lease_acquired_at = now() - make_interval(hours => $3 + 1), \
                lease_expires_at = now() - make_interval(hours => $3) \
          WHERE workspace_id=$1 AND kind='agent_job' AND lower(payload->>'run_id') = lower($2::text) \
            AND lease_owner IS NOT NULL",
    )
    .bind(fixture.workspace)
    .bind(run)
    .bind(hours as i32)
    .execute(pool)
    .await
    .unwrap();
    sqlx::query("UPDATE agent_run SET updated_at = now() - make_interval(hours => $2) WHERE id=$1")
        .bind(run)
        .bind(hours as i32)
        .execute(pool)
        .await
        .unwrap();
}

async fn run_status_3744(pool: &PgPool, run: Uuid) -> (String, Option<String>) {
    sqlx::query_as("SELECT status::text, error->>'code' FROM agent_run WHERE id=$1")
        .bind(run)
        .fetch_one(pool)
        .await
        .unwrap()
}

async fn frames_3744(pool: &PgPool, fixture: &Fixture, run: Uuid) -> Vec<Value> {
    sqlx::query_scalar::<_, Value>(
        "SELECT payload->'data' FROM outbox \
          WHERE workspace_id=$1 AND kind='broadcast' \
            AND payload->'data'->>'type' = 'agent.run.event' \
            AND lower(payload->'data'->'payload'->>'run_id') = lower($2::text) \
          ORDER BY id",
    )
    .bind(fixture.workspace)
    .bind(run)
    .fetch_all(pool)
    .await
    .unwrap()
}

/// RED PROOF (ADR-0200 D1-4, S5). A hosted run whose agent went quiet is ended by the
/// SERVER with a closed fact — and only then. Fresh work, a revived lease, an
/// approval-parked run, a managed agent's run and a run inside either grace period are all
/// left alone; the ended run's job is retired so a late agent finds a settled run, not a
/// resurrected one; the channel gets one line and the audit log one row.
///
/// Tamper table (each applied and seen red):
///   * drop the `r.updated_at` staleness condition        -> the run with a recent report is ended
///   * drop the `lease_expires_at < now() - grace` term   -> the run whose lease expired 1 h ago
///     but that has been silent 3 h is ended
///   * drop the job-less branch (`j.id IS NULL`)          -> the disconnect-orphaned run and the
///     ten-day-old ghost are not ended
///   * let `awaiting_approval` through BOTH the candidate filter and `end_stalled_run_in_tx`
///     (either alone is caught by the other: two guards on purpose)
///                                                         -> the parked run (given a dead job) is ended
///   * do not retire the job                              -> a pending job survives the ended run
///   * drop the unclaimed term                            -> the 25-hour queued run stays queued
///   * key the notice by the run id                       -> the notice looks like the run's answer
/// Not covered here (deterministic only with an injected pause): the sweep-vs-reclaim race;
/// its second line of defence is `pending_job_has_live_lease_in_tx`, asserted above.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_run_whose_agent_went_quiet_is_ended_with_a_closed_code_and_nothing_else_is() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let notifier = momo_notifier_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let policy = momo_outbox::StallPolicy::default();
    // The sweep is cross-tenant by design and this database outlives a test run: settle the
    // ghosts earlier runs left in OTHER workspaces so the counts below are this test's own.
    sqlx::query(
        "UPDATE agent_run SET status='cancelled', finished_at=now() \
          WHERE status IN ('queued','running') AND workspace_id <> $1",
    )
    .bind(fixture.workspace)
    .execute(&su)
    .await
    .unwrap();

    // --- the run that goes quiet -----------------------------------------
    mention_3740(&client, &base, &su, &fixture, fixture.hosted_agent).await;
    let (_, claimed) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_jobs_claim",
        json!({}),
    )
    .await;
    let handle = structured(&claimed)["jobs"][0]["leaseHandle"]
        .as_str()
        .unwrap()
        .to_string();
    let (status, _) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_run_event",
        json!({"leaseHandle": handle, "status": "running", "stage": "작업 시작", "eventId": Uuid::new_v4()}),
    )
    .await;
    assert_eq!(status, 200);
    let quiet: Uuid =
        sqlx::query_scalar("SELECT id FROM agent_run WHERE workspace_id=$1 AND agent_member_id=$2")
            .bind(fixture.workspace)
            .bind(fixture.hosted_agent)
            .fetch_one(&su)
            .await
            .unwrap();

    // fresh: nothing to do
    let stats = momo_notifier::run_stall_sweep::sweep_stalled_runs(&notifier, policy, 50)
        .await
        .unwrap();
    assert_eq!(
        stats.lease_abandoned + stats.unclaimed_expired,
        0,
        "{stats:?}"
    );

    // the re-check the sweep makes under the run lock: a LIVE lease is seen as live…
    {
        let mut connection = su.acquire().await.unwrap();
        assert!(
            momo_outbox::pending_job_has_live_lease_in_tx(
                &mut connection,
                fixture.workspace,
                quiet
            )
            .await
            .unwrap(),
            "a freshly claimed job holds a live lease"
        );
    }

    // stale for 1 hour only: inside the 2-hour grace
    age_run_3744(&su, &fixture, quiet, 1).await;
    momo_notifier::run_stall_sweep::sweep_stalled_runs(&notifier, policy, 50)
        .await
        .unwrap();
    assert_eq!(
        run_status_3744(&su, quiet).await.0,
        "running",
        "1 h is inside the grace"
    );

    // the lease expired 3 hours ago but the agent reported 10 minutes ago: alive
    age_run_3744(&su, &fixture, quiet, 3).await;
    sqlx::query("UPDATE agent_run SET updated_at = now() - interval '10 minutes' WHERE id=$1")
        .bind(quiet)
        .execute(&su)
        .await
        .unwrap();
    momo_notifier::run_stall_sweep::sweep_stalled_runs(&notifier, policy, 50)
        .await
        .unwrap();
    assert_eq!(
        run_status_3744(&su, quiet).await.0,
        "running",
        "a recent report keeps it alive"
    );

    // the lease expired only an hour ago although the run has been silent for three: the LEASE
    // grace is separate from the run's own silence, so this one is still inside it
    sqlx::query(
        "UPDATE outbox SET lease_expires_at = now() - interval '1 hour' \
          WHERE workspace_id=$1 AND kind='agent_job' AND lower(payload->>'run_id') = lower($2::text)",
    )
    .bind(fixture.workspace)
    .bind(quiet)
    .execute(&su)
    .await
    .unwrap();
    sqlx::query("UPDATE agent_run SET updated_at = now() - interval '3 hours' WHERE id=$1")
        .bind(quiet)
        .execute(&su)
        .await
        .unwrap();
    momo_notifier::run_stall_sweep::sweep_stalled_runs(&notifier, policy, 50)
        .await
        .unwrap();
    assert_eq!(
        run_status_3744(&su, quiet).await.0,
        "running",
        "a lease that expired inside the grace keeps the run, whatever its own silence"
    );

    // --- decoys that must survive the sweep that ends the quiet run ---------
    // an approval-parked run with an ancient lease
    let parked: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status, updated_at) \
         VALUES ($1,$2,$3,'awaiting_approval', now() - interval '9 hours') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    // …and it holds a job whose lease is long dead, so that ONLY the status filter protects it
    sqlx::query(
        "INSERT INTO outbox(workspace_id,kind,status,method,payload,partition_key, \
                            lease_owner, lease_acquired_at, lease_expires_at) \
         VALUES ($1,'agent_job','pending','gateway',$2,$3, uuidv7(), \
                 now() - interval '10 hours', now() - interval '9 hours')",
    )
    .bind(fixture.workspace)
    .bind(json!({
        "agent_member_id": fixture.hosted_agent.to_string(),
        "run_id": parked.to_string(),
        "channel_id": fixture.channel.to_string(),
    }))
    .bind(fixture.hosted_agent)
    .execute(&su)
    .await
    .unwrap();
    // a queued run nobody took, 23 hours (inside) and another 25 hours (past) old
    let mut queued = Vec::new();
    for hours in [23, 25] {
        let id: Uuid = sqlx::query_scalar(
            "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status, created_at, updated_at) \
             VALUES ($1,$2,$3,'queued', now() - make_interval(hours => $4), now() - make_interval(hours => $4)) \
             RETURNING id",
        )
        .bind(fixture.workspace)
        .bind(fixture.hosted_agent)
        .bind(fixture.channel)
        .bind(hours)
        .fetch_one(&su)
        .await
        .unwrap();
        sqlx::query(
            "INSERT INTO outbox(workspace_id,kind,status,method,payload,partition_key) \
             VALUES ($1,'agent_job','pending','gateway',$2,$3)",
        )
        .bind(fixture.workspace)
        .bind(json!({
            "agent_member_id": fixture.hosted_agent.to_string(),
            "run_id": id.to_string(),
            "channel_id": fixture.channel.to_string(),
        }))
        .bind(fixture.hosted_agent)
        .execute(&su)
        .await
        .unwrap();
        queued.push(id);
    }
    // a managed agent's ancient queued run: not hosted, never this sweep's
    let managed: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status, created_at, updated_at) \
         VALUES ($1,$2,$3,'queued', now() - interval '30 hours', now() - interval '30 hours') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(fixture.managed_agent)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    sqlx::query(
        "INSERT INTO outbox(workspace_id,kind,status,method,payload,partition_key) \
         VALUES ($1,'agent_job','pending','gateway',$2,$3)",
    )
    .bind(fixture.workspace)
    .bind(json!({
        "agent_member_id": fixture.managed_agent.to_string(),
        "run_id": managed.to_string(),
        "channel_id": fixture.channel.to_string(),
    }))
    .bind(fixture.managed_agent)
    .execute(&su)
    .await
    .unwrap();

    // runs whose delivery job was settled by a disconnect (the commonest ghost): no pending
    // job means no agent can ever report on them. Fresh one survives, silent one is ended.
    let mut suppressed = Vec::new();
    for hours_silent in [0_i32, 3] {
        let id: Uuid = sqlx::query_scalar(
            "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status, updated_at) \
             VALUES ($1,$2,$3,'running', now() - make_interval(hours => $4)) RETURNING id",
        )
        .bind(fixture.workspace)
        .bind(fixture.hosted_agent)
        .bind(fixture.channel)
        .bind(hours_silent)
        .fetch_one(&su)
        .await
        .unwrap();
        sqlx::query(
            "INSERT INTO outbox(workspace_id,kind,status,method,payload,partition_key,processed_at) \
             VALUES ($1,'agent_job','done','gateway',$2,$3, now())",
        )
        .bind(fixture.workspace)
        .bind(json!({
            "agent_member_id": fixture.hosted_agent.to_string(),
            "run_id": id.to_string(),
            "channel_id": fixture.channel.to_string(),
        }))
        .bind(fixture.hosted_agent)
        .execute(&su)
        .await
        .unwrap();
        suppressed.push(id);
    }
    // a run whose only delivery path is a non-`gateway` job (a resume job): some consumer
    // still has a job to take, so it is NOT the job-less orphan the sweep ends
    let resumed: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status, created_at, updated_at) \
         VALUES ($1,$2,$3,'queued', now() - interval '3 hours', now() - interval '3 hours') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    sqlx::query(
        "INSERT INTO outbox(workspace_id,kind,status,method,payload,partition_key) \
         VALUES ($1,'agent_job','pending','resume_approval',$2,$3)",
    )
    .bind(fixture.workspace)
    .bind(json!({
        "agent_member_id": fixture.hosted_agent.to_string(),
        "run_id": resumed.to_string(),
        "channel_id": fixture.channel.to_string(),
    }))
    .bind(fixture.hosted_agent)
    .execute(&su)
    .await
    .unwrap();
    // a run silent for ten days: ended, but without a channel line (the first sweep after a
    // deploy must not light up old channels with weeks-old notices)
    let ancient: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status, created_at, updated_at) \
         VALUES ($1,$2,$3,'running', now() - interval '12 days', now() - interval '10 days') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();

    // --- now the quiet run really goes quiet --------------------------------
    age_run_3744(&su, &fixture, quiet, 3).await;
    {
        let mut connection = su.acquire().await.unwrap();
        assert!(
            !momo_outbox::pending_job_has_live_lease_in_tx(
                &mut connection,
                fixture.workspace,
                quiet
            )
            .await
            .unwrap(),
            "…and an expired one is not"
        );
    }
    let stats = momo_notifier::run_stall_sweep::sweep_stalled_runs(&notifier, policy, 50)
        .await
        .unwrap();
    assert_eq!(
        stats.lease_abandoned, 3,
        "the quiet run, the silent run with no delivery job, the ten-day-old one: {stats:?}"
    );
    assert_eq!(stats.unclaimed_expired, 1, "{stats:?}");
    assert_eq!(
        run_status_3744(&su, suppressed[1]).await,
        ("timed_out".to_string(), Some("lease_abandoned".to_string())),
        "a run whose job a disconnect settled is ended when it has been silent"
    );
    assert_eq!(
        run_status_3744(&su, suppressed[0]).await.0,
        "running",
        "…but not while it is fresh"
    );
    assert_eq!(run_status_3744(&su, ancient).await.0, "timed_out");
    assert_eq!(
        run_status_3744(&su, resumed).await.0,
        "queued",
        "a run with a pending resume job still has a delivery path"
    );
    let ancient_lines: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM message WHERE workspace_id=$1 AND run_id=$2 AND type='system'",
    )
    .bind(fixture.workspace)
    .bind(ancient)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(ancient_lines, 0, "an ancient ghost is ended quietly");

    assert_eq!(
        run_status_3744(&su, quiet).await,
        ("timed_out".to_string(), Some("lease_abandoned".to_string()))
    );
    assert_eq!(
        run_status_3744(&su, queued[1]).await,
        (
            "timed_out".to_string(),
            Some("unclaimed_expired".to_string())
        )
    );
    for (survivor, why) in [
        (parked, "an approval-parked run is the approval sweep's"),
        (queued[0], "23 hours is inside the 24-hour window"),
        (managed, "a managed agent's run is not a hosted run"),
    ] {
        let (status, code) = run_status_3744(&su, survivor).await;
        assert!(code.is_none() && status != "timed_out", "{why}: {status}");
    }

    // the ledger says it, the channel says it once, the audit log says why (actor: the clock)
    let ledger = ledger_3740(&su, fixture.workspace, quiet).await;
    let last = ledger.last().unwrap();
    assert_eq!(
        (last.1.as_str(), last.3.as_deref()),
        ("timed_out", Some("lease_abandoned"))
    );
    let lines: Vec<(String, Value)> = sqlx::query_as(
        "SELECT body, props FROM message WHERE workspace_id=$1 AND run_id=$2 AND type='system'",
    )
    .bind(fixture.workspace)
    .bind(quiet)
    .fetch_all(&su)
    .await
    .unwrap();
    assert_eq!(lines.len(), 1, "{lines:?}");
    assert_eq!(lines[0].1["code"], json!("lease_abandoned"));
    let keyed_by_run: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM message WHERE workspace_id=$1 AND client_msg_id=$2",
    )
    .bind(fixture.workspace)
    .bind(quiet)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(
        keyed_by_run, 0,
        "the notice must not look like the run's ANSWER (client_msg_id = run id) to the push judgment"
    );
    let audits: Vec<(Option<Uuid>, Value)> = sqlx::query_as(
        "SELECT actor_member_id, detail FROM audit_log WHERE workspace_id=$1 AND action='agent.run.stalled' \
          AND target_id = $2",
    )
    .bind(fixture.workspace)
    .bind(quiet)
    .fetch_all(&su)
    .await
    .unwrap();
    assert_eq!(audits.len(), 1);
    assert!(audits[0].0.is_none(), "the clock ended it, not a member");

    // the delivery job is settled: a late agent on the old handle finds a finished run
    let pending_jobs: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM outbox WHERE workspace_id=$1 AND kind='agent_job' AND status='pending' \
           AND lower(payload->>'run_id') = lower($2::text)",
    )
    .bind(fixture.workspace)
    .bind(quiet)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(pending_jobs, 0);
    let (status, late) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_run_event",
        json!({"leaseHandle": handle, "status": "running", "eventId": Uuid::new_v4()}),
    )
    .await;
    assert!(
        status >= 400,
        "a late agent does not revive an ended run: {late}"
    );
    assert_eq!(run_status_3744(&su, quiet).await.0, "timed_out");

    // idempotent
    let again = momo_notifier::run_stall_sweep::sweep_stalled_runs(&notifier, policy, 50)
        .await
        .unwrap();
    assert_eq!(again.lease_abandoned + again.unclaimed_expired, 0);

    // realtime: the lifecycle rows produced thin frames — no stage text, no sequence
    let frames = frames_3744(&su, &fixture, quiet).await;
    assert!(!frames.is_empty());
    let rendered = serde_json::to_string(&frames).unwrap();
    assert!(
        !rendered.contains("작업 시작"),
        "no stage text on the wire: {rendered}"
    );
    assert!(
        !rendered.contains("\"seq\""),
        "no raw sequence on the wire: {rendered}"
    );
    let kinds: Vec<&str> = frames
        .iter()
        .map(|frame| frame["payload"]["kind"].as_str().unwrap())
        .collect();
    assert!(kinds.contains(&"timed_out"), "{kinds:?}");
}

/// RED PROOF (ADR-0200 D2, S5). The ledger announces itself with ONE thin frame per
/// lifecycle row, and consecutive `stage` rows inside two seconds collapse to a single
/// frame (the row is still written; a refetch carries it). The frame is addressed to the
/// run's channel topic.
///
/// Tamper table:
///   * drop the 2-second coalescing                    -> every stage row emits a frame
///   * put `stage`/`seq` in the frame                  -> the no-text / no-seq assertions fail
///   * address the frame to a different topic          -> the topic assertion fails
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_ledger_row_emits_one_thin_frame_and_a_stage_burst_is_coalesced() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let fixture = seed(&su).await;
    let run: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status) \
         VALUES ($1,$2,$3,'queued') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    // one transaction: all three stage rows share a timestamp, so they are "within 2 s"
    let mut tx = su.begin().await.unwrap();
    for stage in ["하나", "둘", "셋"] {
        sqlx::query("SELECT agent_run_event_append($1,$2,'stage',$3,NULL,NULL,$4)")
            .bind(fixture.workspace)
            .bind(run)
            .bind(stage)
            .bind(fixture.hosted_agent)
            .execute(&mut *tx)
            .await
            .unwrap();
    }
    tx.commit().await.unwrap();
    let frames = frames_3744(&su, &fixture, run).await;
    let kinds: Vec<&str> = frames
        .iter()
        .map(|frame| frame["payload"]["kind"].as_str().unwrap())
        .collect();
    assert_eq!(
        kinds,
        ["queued", "stage"],
        "three stage rows, one frame: {frames:?}"
    );
    let topic: String = sqlx::query_scalar(
        "SELECT payload->>'channel' FROM outbox WHERE workspace_id=$1 AND kind='broadcast' \
           AND payload->'data'->>'type'='agent.run.event' ORDER BY id LIMIT 1",
    )
    .bind(fixture.workspace)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(
        topic,
        format!(
            "ch:ws{}.{}",
            fixture.workspace.to_string().to_uppercase(),
            fixture.channel.to_string().to_uppercase()
        )
    );
    let rendered = serde_json::to_string(&frames).unwrap();
    for hidden in ["하나", "둘", "셋", "\"seq\"", "stage\":"] {
        assert!(!rendered.contains(hidden), "{hidden}: {rendered}");
    }
    assert_eq!(
        ledger_3740(&su, fixture.workspace, run).await.len(),
        4,
        "all rows are still written"
    );
}

/// RED PROOF (ADR-0200 D2, S5). A FINISHED run's ledger is deleted 30 days after it
/// finished — and only that: a run finished 29 days ago, a run still in progress however
/// old, and the run rows themselves are untouched. Until the sweep deletes, a read past
/// retention answers an empty ledger. The delete runs on the RLS-bound pool; the read
/// half is the notifier's.
///
/// Tamper table:
///   * measure from `created_at` instead of `finished_at`  -> the ancient running run loses its ledger
///   * 30 -> 3 days                                        -> the 29-day-old ledger is deleted
///   * drop the read-time expiry in `list_run_events_in_tx` -> the expired-but-undeleted ledger is returned
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_finished_runs_ledger_is_kept_thirty_days_and_a_running_one_never_expires() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let notifier = momo_notifier_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app.clone(), true).await;
    let client = reqwest::Client::new();

    let mut runs = Vec::new();
    for (status, finished_days_ago, created_days_ago) in [
        ("succeeded", Some(31), 40),
        ("succeeded", Some(29), 40),
        ("running", None, 90),
    ] {
        let run: Uuid = sqlx::query_scalar(
            "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status, created_at, finished_at) \
             VALUES ($1,$2,$3,$4::run_status, now() - make_interval(days => $5), \
                     CASE WHEN $6::int IS NULL THEN NULL ELSE now() - make_interval(days => $6) END) \
             RETURNING id",
        )
        .bind(fixture.workspace)
        .bind(fixture.hosted_agent)
        .bind(fixture.channel)
        .bind(status)
        .bind(created_days_ago)
        .bind(finished_days_ago)
        .fetch_one(&su)
        .await
        .unwrap();
        runs.push(run);
    }
    let [expired, young, ancient_running] = [runs[0], runs[1], runs[2]];
    for run in [expired, young, ancient_running] {
        assert!(!ledger_3740(&su, fixture.workspace, run).await.is_empty());
    }

    // read-time expiry: the sweep has not run, the ledger already reads empty
    let (status, body) = events_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        &expired.to_string(),
    )
    .await;
    assert_eq!(status, 200, "{body}");
    assert_eq!(
        body["events"],
        json!([]),
        "past retention reads empty: {body}"
    );
    let (_, body) = events_3741(
        &client,
        &base,
        &fixture.human_jwt,
        &fixture,
        &young.to_string(),
    )
    .await;
    assert!(
        !body["events"].as_array().unwrap().is_empty(),
        "29 days is kept: {body}"
    );

    let stats =
        momo_notifier::run_event_retention_sweep::sweep_expired_run_events(&notifier, &app, 50)
            .await
            .unwrap();
    assert!(stats.deleted >= 1, "{stats:?}");
    assert!(ledger_3740(&su, fixture.workspace, expired)
        .await
        .is_empty());
    assert!(!ledger_3740(&su, fixture.workspace, young).await.is_empty());
    assert!(
        !ledger_3740(&su, fixture.workspace, ancient_running)
            .await
            .is_empty(),
        "a run still in progress never expires, however old"
    );
    let rows: i64 = sqlx::query_scalar("SELECT count(*) FROM agent_run WHERE id = ANY($1)")
        .bind(&runs)
        .fetch_one(&su)
        .await
        .unwrap();
    assert_eq!(rows, 3, "the run rows themselves are never touched");

    // idempotent
    let again =
        momo_notifier::run_event_retention_sweep::sweep_expired_run_events(&notifier, &app, 50)
            .await
            .unwrap();
    assert_eq!(again.deleted, 0);
}

/// RED PROOF (S5 review M-1). A steady stage stream keeps framing every two seconds — the
/// rate limit is against the last FRAMED stage row, not the last stage row, so it does not
/// fall silent after the first frame.
///
/// Tamper table:
///   * compare against the last stage row instead of the last framed one -> the third row
///     (2.2 s after the first) is not framed
///   * drop the rate limit                                                -> the second row is framed
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_steady_stage_stream_keeps_framing_every_two_seconds() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let fixture = seed(&su).await;
    let run: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status) \
         VALUES ($1,$2,$3,'queued') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    for (n, pause_ms) in [(1, 0_u64), (2, 1100), (3, 1100)] {
        tokio::time::sleep(std::time::Duration::from_millis(pause_ms)).await;
        sqlx::query("SELECT agent_run_event_append($1,$2,'stage',$3,NULL,NULL,$4)")
            .bind(fixture.workspace)
            .bind(run)
            .bind(format!("단계 {n}"))
            .bind(fixture.hosted_agent)
            .execute(&su)
            .await
            .unwrap();
    }
    let framed: Vec<bool> = sqlx::query_scalar(
        "SELECT framed FROM agent_run_event WHERE workspace_id=$1 AND run_id=$2 AND kind='stage' ORDER BY seq",
    )
    .bind(fixture.workspace)
    .bind(run)
    .fetch_all(&su)
    .await
    .unwrap();
    assert_eq!(
        framed,
        [true, false, true],
        "1st framed; 2nd (1.1 s later) not; 3rd (2.2 s after the 1st) framed"
    );
    let frame_kinds: Vec<Value> = frames_3744(&su, &fixture, run).await;
    let stage_frames = frame_kinds
        .iter()
        .filter(|frame| frame["payload"]["kind"] == json!("stage"))
        .count();
    assert_eq!(stage_frames, 2);
}

// ---------------------------------------------------------------------------
// #3771 — a decided card is announced, and a late click names the real decider
// ---------------------------------------------------------------------------

/// The `message.edited` frames the outbox holds for one message.
async fn edited_frames_for(pool: &PgPool, workspace: Uuid, message: Uuid) -> Vec<Value> {
    sqlx::query_scalar(
        "SELECT payload->'data' FROM outbox WHERE workspace_id=$1 AND kind='broadcast' \
           AND payload->'data'->>'type' = 'message.edited' \
           AND payload->'data'->'payload'->>'id' = $2 \
         ORDER BY created_at, id",
    )
    .bind(workspace)
    .bind(message.to_string())
    .fetch_all(pool)
    .await
    .expect("read edited frames")
}

/// **The decision rewrites the card and says so (#3771).**
///
/// Measured on prod 2026-10-13: the decision patched `message.props` and
/// published nothing, so the timeline kept `status: pending`, drew the buttons
/// again, and a second click answered 「이미 승인으로 기록되어 있었어요」 — stamped
/// with the *second* presser and the *second* press time (22:54 for a decision
/// that the ledger holds at 22:52).
///
/// 1. the refused (role_required) attempt announces the card (`last_attempt`);
/// 2. the approval announces it again with `status: approved` and no
///    `last_attempt`;
/// 3. a late click is a 409 whose receipt names the **ledger's** decider and
///    time, not the person pressing.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_decided_card_is_announced_and_a_late_click_names_the_real_decision() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app.clone(), true).await;
    let client = reqwest::Client::new();
    let plain_jwt = seed_plain_member(&su, &fixture).await;

    let (approval_id, card_message_id) = propose_invite(
        &client,
        &base,
        &su,
        &fixture,
        json!({"role": "member", "maxUses": 1, "expiresInDays": 7}),
    )
    .await;
    assert!(
        edited_frames_for(&su, fixture.workspace, card_message_id)
            .await
            .is_empty(),
        "a freshly proposed card has been announced by its own message.new, not an edit"
    );

    // 1. the refusal rewrites the card, so it announces it.
    let (status, _, refused) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &plain_jwt,
        approval_id,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 403, "{refused}");
    let after_refusal = edited_frames_for(&su, fixture.workspace, card_message_id).await;
    assert_eq!(after_refusal.len(), 1, "one frame for the refusal");
    assert_eq!(
        after_refusal[0]["payload"]["props"]["last_attempt"],
        json!("role_required")
    );
    assert_eq!(
        after_refusal[0]["payload"]["props"]["status"],
        json!("pending")
    );

    // 2. the approval announces the decided card.
    let (status, _, approved) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval_id,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    let frames = edited_frames_for(&su, fixture.workspace, card_message_id).await;
    assert_eq!(frames.len(), 2, "one more frame for the decision");
    let decided = &frames[1]["payload"];
    assert_eq!(decided["props"]["status"], json!("approved"));
    assert_eq!(
        decided["props"]["decided_by"],
        json!(fixture.human.to_string())
    );
    assert!(
        decided["props"].get("last_attempt").is_none(),
        "the earlier refusal is pruned from the announced card too: {decided}"
    );
    assert_eq!(
        decided["state"],
        json!("sent"),
        "a server rewrite is not a human edit: no 「수정됨」"
    );
    assert!(decided.get("edited_at_ms").is_none_or(Value::is_null));

    // 3. a late click, with a fresh key (what a re-mounted card sends).
    let ledger_ms: i64 = sqlx::query_scalar(
        "SELECT floor(extract(epoch FROM decided_at) * 1000)::bigint FROM approval \
          WHERE workspace_id=$1 AND id=$2",
    )
    .bind(fixture.workspace)
    .bind(approval_id)
    .fetch_one(&su)
    .await
    .unwrap();
    tokio::time::sleep(std::time::Duration::from_millis(1_100)).await;
    let (status, _, late) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval_id,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{late}");
    assert_eq!(late["status"], json!("approved"));
    assert_eq!(late["decidedBy"], json!(fixture.human.to_string()));
    assert_eq!(
        late["decidedAtMs"].as_i64(),
        Some(ledger_ms),
        "the late click reports the ledger's decision time, not its own: {late}"
    );
    assert_eq!(
        edited_frames_for(&su, fixture.workspace, card_message_id)
            .await
            .len(),
        2,
        "a refused late click rewrites nothing and announces nothing"
    );
}

/// The rejection arm rewrites the card too (#3771), so it announces it too.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_rejected_card_is_announced_as_rejected() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app.clone(), true).await;
    let client = reqwest::Client::new();
    let (approval_id, card_message_id) = propose_invite(
        &client,
        &base,
        &su,
        &fixture,
        json!({"role": "member", "maxUses": 1, "expiresInDays": 7}),
    )
    .await;
    let (status, _, rejected) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval_id,
        false,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{rejected}");
    let frames = edited_frames_for(&su, fixture.workspace, card_message_id).await;
    assert_eq!(frames.len(), 1, "the rejection announces the card once");
    assert_eq!(frames[0]["payload"]["props"]["status"], json!("rejected"));
}

/// **#3784 red proof** (hardened after the #3795 security review): a decision
/// asking `deliverSecretToAgent: true` where it cannot be honoured is refused 400
/// `deliver_secret_not_supported` **before any write**, on both decision routes,
/// both spellings, approve and reject, and on a card whose deadline has passed
/// (an expiry settlement must not outrank the refusal). The approval, the ledger
/// (`approval_decision`), the audit log and the invite table are all unchanged.
/// A decision that does not ask still executes, and a replay of an executed
/// decision that now asks answers the original receipt (documented: the flag is
/// not part of the idempotency key).
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn deliver_secret_to_agent_is_refused_where_the_action_does_not_offer_it() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app.clone(), true).await;
    let client = reqwest::Client::new();

    async fn counts(su: &PgPool, workspace: Uuid, approval_id: Uuid) -> (String, i64, i64, i64) {
        let status: String =
            sqlx::query_scalar("SELECT status::text FROM approval WHERE workspace_id=$1 AND id=$2")
                .bind(workspace)
                .bind(approval_id)
                .fetch_one(su)
                .await
                .unwrap();
        let ledger: i64 = sqlx::query_scalar(
            "SELECT count(*) FROM approval_decision WHERE workspace_id=$1 AND approval_id=$2",
        )
        .bind(workspace)
        .bind(approval_id)
        .fetch_one(su)
        .await
        .unwrap();
        let audits: i64 =
            sqlx::query_scalar("SELECT count(*) FROM audit_log WHERE workspace_id=$1")
                .bind(workspace)
                .fetch_one(su)
                .await
                .unwrap();
        let invites: i64 =
            sqlx::query_scalar("SELECT count(*) FROM invite_code WHERE workspace_id=$1")
                .bind(workspace)
                .fetch_one(su)
                .await
                .unwrap();
        (status, ledger, audits, invites)
    }

    async fn post_decision(
        client: &reqwest::Client,
        url: String,
        bearer: &str,
        body: Value,
    ) -> (u16, Value) {
        let response = client
            .post(url)
            .bearer_auth(bearer)
            .json(&body)
            .send()
            .await
            .expect("decision responds");
        let status = response.status().as_u16();
        (status, response.json().await.unwrap_or(Value::Null))
    }

    let (approval_id, _card) = propose_invite(
        &client,
        &base,
        &su,
        &fixture,
        json!({"role": "member", "maxUses": 1, "expiresInDays": 7}),
    )
    .await;
    let run_id: Uuid =
        sqlx::query_scalar("SELECT run_id FROM approval WHERE workspace_id=$1 AND id=$2")
            .bind(fixture.workspace)
            .bind(approval_id)
            .fetch_one(&su)
            .await
            .unwrap();
    let before = counts(&su, fixture.workspace, approval_id).await;
    assert_eq!(before.0, "pending");

    let workspace_route = format!(
        "{base}/v1/workspaces/{}/approvals/{approval_id}/decision",
        fixture.workspace
    );
    let run_route = format!("{base}/v1/agent-runs/{run_id}/approval-decisions");
    for (route_label, url) in [("workspace", workspace_route.clone()), ("run", run_route)] {
        for approve in [true, false] {
            for spelling in ["deliverSecretToAgent", "deliver_secret_to_agent"] {
                let (status, body) = post_decision(
                    &client,
                    url.clone(),
                    &fixture.human_jwt,
                    json!({
                        "approvalId": approval_id,
                        "approve": approve,
                        "clientDecisionId": Uuid::new_v4(),
                        spelling: true,
                    }),
                )
                .await;
                let label = format!("{route_label}/approve={approve}/{spelling}");
                assert_eq!(status, 400, "{label}: {body}");
                assert_eq!(
                    body["status"], "deliver_secret_not_supported",
                    "{label}: {body}"
                );
                assert!(
                    body.get("result").is_none(),
                    "{label}: executed nothing: {body}"
                );
                assert_eq!(
                    counts(&su, fixture.workspace, approval_id).await,
                    before,
                    "{label}: nothing consumed, nothing written"
                );
            }
        }
    }

    // A non-boolean flag is a malformed body, not a quiet `false`.
    let (status, _body) = post_decision(
        &client,
        workspace_route.clone(),
        &fixture.human_jwt,
        json!({
            "approvalId": approval_id, "approve": true,
            "clientDecisionId": Uuid::new_v4(), "deliverSecretToAgent": "true"
        }),
    )
    .await;
    assert!((400..500).contains(&status), "{status}");
    assert_eq!(counts(&su, fixture.workspace, approval_id).await, before);

    // An approval that is not a workspace action at all (an ordinary tool-call
    // card): a `true` is refused for it too, approve or reject, nothing written.
    let plain_run: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_run (workspace_id, agent_member_id, channel_id, status) \
         VALUES ($1,$2,$3,'awaiting_approval') RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .bind(fixture.channel)
    .fetch_one(&su)
    .await
    .unwrap();
    let plain: Uuid = sqlx::query_scalar(
        "INSERT INTO approval (workspace_id, run_id, channel_id, requested_by, action_type, payload) \
         VALUES ($1,$2,$3,$4,'tool_call','{}'::jsonb) RETURNING id",
    )
    .bind(fixture.workspace)
    .bind(plain_run)
    .bind(fixture.channel)
    .bind(fixture.hosted_agent)
    .fetch_one(&su)
    .await
    .unwrap();
    let plain_before = counts(&su, fixture.workspace, plain).await;
    for approve in [true, false] {
        let (status, body) = post_decision(
            &client,
            format!(
                "{base}/v1/workspaces/{}/approvals/{plain}/decision",
                fixture.workspace
            ),
            &fixture.human_jwt,
            json!({"approvalId": plain, "approve": approve,
                   "clientDecisionId": Uuid::new_v4(), "deliverSecretToAgent": true}),
        )
        .await;
        assert_eq!(status, 400, "tool_call approve={approve}: {body}");
        assert_eq!(body["status"], "deliver_secret_not_supported", "{body}");
        assert_eq!(
            counts(&su, fixture.workspace, plain).await,
            plain_before,
            "tool_call approve={approve}: nothing consumed, nothing written"
        );
    }

    // The deadline has passed: the refusal still wins over the expiry settlement.
    sqlx::query(
        "UPDATE approval SET expires_at = now() - interval '1 minute' \
          WHERE workspace_id=$1 AND id=$2",
    )
    .bind(fixture.workspace)
    .bind(approval_id)
    .execute(&su)
    .await
    .unwrap();
    let expired_before = counts(&su, fixture.workspace, approval_id).await;
    let (status, body) = post_decision(
        &client,
        workspace_route.clone(),
        &fixture.human_jwt,
        json!({
            "approvalId": approval_id, "approve": true,
            "clientDecisionId": Uuid::new_v4(), "deliverSecretToAgent": true
        }),
    )
    .await;
    assert_eq!(status, 400, "{body}");
    assert_eq!(body["status"], "deliver_secret_not_supported", "{body}");
    assert_eq!(
        counts(&su, fixture.workspace, approval_id).await,
        expired_before,
        "an overdue card is not settled by a refused request"
    );

    // A decision that does not ask executes, and a replay that now asks answers
    // the original receipt.
    let (fresh, _card) = propose_invite(
        &client,
        &base,
        &su,
        &fixture,
        json!({"role": "member", "maxUses": 1, "expiresInDays": 7}),
    )
    .await;
    let decision_id = Uuid::new_v4();
    let url = format!(
        "{base}/v1/workspaces/{}/approvals/{fresh}/decision",
        fixture.workspace
    );
    let (status, body) = post_decision(
        &client,
        url.clone(),
        &fixture.human_jwt,
        json!({"approvalId": fresh, "approve": true, "clientDecisionId": decision_id,
               "deliverSecretToAgent": false}),
    )
    .await;
    assert_eq!(status, 200, "{body}");
    assert_eq!(body["status"], "approved", "{body}");
    let (status, replay) = post_decision(
        &client,
        url,
        &fixture.human_jwt,
        json!({"approvalId": fresh, "approve": true, "clientDecisionId": decision_id,
               "deliverSecretToAgent": true}),
    )
    .await;
    assert_eq!(status, 200, "{replay}");
    assert_eq!(replay["status"], "approved", "{replay}");
}

// ---------------------------------------------------------------------------
// ADR-0186 증보 2026-10-13 v3 P1 (#3785) — agent.profile.update
// ---------------------------------------------------------------------------

async fn profile_row_3785(
    pool: &PgPool,
    agent: Uuid,
) -> (
    Option<String>,
    Option<String>,
    Option<String>,
    Option<String>,
) {
    sqlx::query_as(
        "SELECT a.config->>'tagline', a.config->>'roleLabel', m.status_emoji, m.status_text \
           FROM member m JOIN agent a ON a.member_id = m.id WHERE m.id = $1",
    )
    .bind(agent)
    .fetch_one(pool)
    .await
    .expect("profile row")
}

/// **agent.profile.update (증보 v3 V3-2), end to end.** Hostile spellings are one
/// refusal and change nothing; the owner (not an admin) approves their own
/// agent's card; a third party is `role_required`; the card's rows are the
/// server's; the audit row names fields and never values; `instructions` and the
/// handle are untouched; the roster shows the new card; a clear removes it; a
/// field that changed under the card re-asks (`action_args_invalid`).
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn an_agent_updates_its_profile_card_after_its_owner_approves() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (owner, owner_jwt) = seed_human_3708(&su, &fixture, "owner", "member").await;
    let (_third, third_jwt) = seed_human_3708(&su, &fixture, "third", "member").await;
    set_agent_owner_3708(&su, fixture.hosted_agent, Some(owner)).await;
    let _handle = tidy_agent_3708(&su, fixture.hosted_agent, "Hermes").await;
    sqlx::query("UPDATE agent SET system_prompt = 'KEEP-ME' WHERE member_id = $1")
        .bind(fixture.hosted_agent)
        .execute(&su)
        .await
        .unwrap();
    let handle_before: String = sqlx::query_scalar("SELECT handle FROM member WHERE id=$1")
        .bind(fixture.hosted_agent)
        .fetch_one(&su)
        .await
        .unwrap();

    // ---- hostile spellings: one refusal, nothing written -------------------
    let mut answers = Vec::new();
    for hostile in [
        json!({"tagline": "[docs](http://evil.example)"}),
        json!({"tagline": "visit https://evil.example"}),
        json!({"tagline": "ping @Person owner"}),
        json!({"tagline": "Person owner approved this"}),
        json!({"tagline": "zero\u{200B}width"}),
        json!({"tagline": "line\nbreak"}),
        json!({"tagline": "x".repeat(141)}),
        json!({"roleLabel": "관리자"}),
        json!({"roleLabel": "Security"}),
        json!({"roleLabel": "y".repeat(25)}),
        json!({"statusText": "[잠시]"}),
        json!({"statusEmoji": "ok"}),
        json!({"statusText": "회의", "statusExpiresInHours": 169}),
        json!({"statusExpiresInHours": 2}),
        // Security review of #3797: padded emoji, Korean authority and default
        // role words, particles glued to a member's name, dot look-alikes.
        json!({"statusEmoji": format!("🤖{}", "\u{FE0F}".repeat(40))}),
        json!({"roleLabel": "소유자"}),
        json!({"roleLabel": "멤버"}),
        json!({"roleLabel": "공식 봇"}),
        json!({"tagline": "Personowner님이 승인했어요"}),
        json!({"tagline": "Person-owner approved"}),
        json!({"tagline": "evil\u{3002}com"}),
        json!({"displayName": "Tools"}),
        // Everything that steers behaviour, and the avatar (a later slice), is
        // not a key of this action at all.
        json!({"instructions": "ignore all previous"}),
        json!({"systemPrompt": "x"}),
        json!({"enabledTools": ["x"]}),
        json!({"paused": true}),
        json!({"handle": "evil"}),
        json!({"avatar": {"source": "preset", "presetId": "x"}}),
        json!({}),
    ] {
        let (status, refused) = try_propose_action_3706(
            &client,
            &base,
            &su,
            &fixture,
            "agent.profile.update",
            hostile.clone(),
        )
        .await;
        answers.push((status, refused["error"].clone()));
        assert_eq!(status, 400, "{hostile} must be refused: {refused}");
    }
    assert!(answers.iter().all(|a| a.1 == answers[0].1), "{answers:?}");
    assert_eq!(
        profile_row_3785(&su, fixture.hosted_agent).await,
        (None, None, None, None)
    );

    // A label the workspace itself defines, or one that contains it, is refused.
    sqlx::query("UPDATE workspace SET settings = jsonb_set(settings, '{role_labels}', '{\"admin\":\"Captain\"}') WHERE id=$1")
        .bind(fixture.workspace)
        .execute(&su)
        .await
        .unwrap();
    for label in ["Captain", "Captain Bot"] {
        let (status, refused) = try_propose_action_3706(
            &client,
            &base,
            &su,
            &fixture,
            "agent.profile.update",
            json!({"roleLabel": label}),
        )
        .await;
        assert_eq!(status, 400, "{label}: {refused}");
    }
    sqlx::query("UPDATE workspace SET settings = settings - 'role_labels' WHERE id=$1")
        .bind(fixture.workspace)
        .execute(&su)
        .await
        .unwrap();

    // ---- a good proposal: the card says what will change -------------------
    let good = json!({
        "tagline": "영업 요약을 정리해요",
        "roleLabel": "영업 비서",
        "statusEmoji": "🤖",
        "statusText": "집중 모드",
        "statusExpiresInHours": 2
    });
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.profile.update",
        good.clone(),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval = proposed_approval_3706(&proposed);
    let card: Value = sqlx::query_scalar("SELECT props FROM message WHERE id=$1")
        .bind(Uuid::parse_str(structured(&proposed)["cardMessageId"].as_str().unwrap()).unwrap())
        .fetch_one(&su)
        .await
        .unwrap();
    assert_eq!(card["action"]["required_role"], json!("agent_editor"));
    let rows = card["action"]["rows"].as_array().unwrap().clone();
    let row = |label: &str| {
        rows.iter()
            .find(|r| r["label"] == label)
            .unwrap_or_else(|| panic!("{label} in {rows:?}"))["value"]
            .as_str()
            .unwrap()
            .to_string()
    };
    assert!(row("대상 에이전트").contains("Hermes"));
    assert_eq!(row("소개"), "없음 → 영업 요약을 정리해요");
    assert_eq!(row("역할 라벨"), "없음 → 영업 비서");
    assert_eq!(row("상태"), "없음 → 🤖 집중 모드 (2시간 동안)");
    assert!(!card["summary"].as_str().unwrap().contains("다른 에이전트"));

    // ---- a third party is refused; the agent cannot approve ----------------
    let (status, _h, refused) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &third_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 403, "{refused}");
    assert_eq!(refused["status"], "role_required");
    assert_eq!(approval_status_3708(&su, approval).await, "pending");
    assert_eq!(
        profile_row_3785(&su, fixture.hosted_agent).await,
        (None, None, None, None)
    );

    // ---- the owner approves ------------------------------------------------
    let audits_before: i64 =
        sqlx::query_scalar("SELECT count(*) FROM audit_log WHERE workspace_id=$1")
            .bind(fixture.workspace)
            .fetch_one(&su)
            .await
            .unwrap();
    let (status, _h, approved) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &owner_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(
        approved["result"]["actionId"],
        json!("agent.profile.update")
    );
    assert!(approved["result"].get("secretOnce").is_none());
    assert_eq!(
        profile_row_3785(&su, fixture.hosted_agent).await,
        (
            Some("영업 요약을 정리해요".into()),
            Some("영업 비서".into()),
            Some("🤖".into()),
            Some("집중 모드".into())
        )
    );
    let hours_left: f64 = sqlx::query_scalar(
        "SELECT (extract(epoch FROM (status_expires_at - now())) / 3600.0)::float8 FROM member WHERE id=$1",
    )
    .bind(fixture.hosted_agent)
    .fetch_one(&su)
    .await
    .unwrap();
    // Upper bound has 36 s of slack: the app clock sets the expiry and the DB clock
    // measures it, and a Docker VM clock runs tens of ms ahead of the host (2.000014 h).
    assert!((1.9..=2.01).contains(&hours_left), "{hours_left}");
    // Nothing else moved.
    let prompt: Option<String> =
        sqlx::query_scalar("SELECT system_prompt FROM agent WHERE member_id=$1")
            .bind(fixture.hosted_agent)
            .fetch_one(&su)
            .await
            .unwrap();
    assert_eq!(prompt.as_deref(), Some("KEEP-ME"));
    let handle_after: String = sqlx::query_scalar("SELECT handle FROM member WHERE id=$1")
        .bind(fixture.hosted_agent)
        .fetch_one(&su)
        .await
        .unwrap();
    assert_eq!(handle_after, handle_before);
    assert_eq!(display_name_3708(&su, fixture.hosted_agent).await, "Hermes");

    // ---- audit: field names, never values ----------------------------------
    let audit: Value = sqlx::query_scalar(
        "SELECT detail FROM audit_log WHERE workspace_id=$1 AND action='agent.profile.updated' \
          ORDER BY created_at DESC LIMIT 1",
    )
    .bind(fixture.workspace)
    .fetch_one(&su)
    .await
    .expect("audit row");
    assert_eq!(
        audit["fields"],
        json!(["tagline", "roleLabel", "status"]),
        "{audit}"
    );
    let rendered = audit.to_string();
    for value in ["영업 요약", "영업 비서", "집중 모드", "🤖"] {
        assert!(
            !rendered.contains(value),
            "{value} leaked into the audit: {rendered}"
        );
    }
    assert!(
        audits_before
            < sqlx::query_scalar::<_, i64>("SELECT count(*) FROM audit_log WHERE workspace_id=$1")
                .bind(fixture.workspace)
                .fetch_one(&su)
                .await
                .unwrap()
    );

    // ---- the roster shows the card -----------------------------------------
    let roster: Value = client
        .get(format!("{base}/v1/workspaces/{}/roster", fixture.workspace))
        .bearer_auth(&fixture.human_jwt)
        .send()
        .await
        .unwrap()
        .json()
        .await
        .unwrap();
    let members = roster["members"]
        .as_array()
        .or(roster.as_array())
        .expect("roster list");
    let me = members
        .iter()
        .find(|m| m["id"] == json!(fixture.hosted_agent.to_string()))
        .expect("the agent is on the roster");
    assert_eq!(me["tagline"], json!("영업 요약을 정리해요"), "{me}");
    assert_eq!(me["roleLabel"], json!("영업 비서"), "{me}");
    assert_eq!(me["statusText"], json!("집중 모드"), "{me}");
    assert_eq!(me["statusEmoji"], json!("🤖"), "{me}");
    // A human still carries neither.
    let human = members
        .iter()
        .find(|m| m["id"] == json!(fixture.human.to_string()))
        .expect("the human is on the roster");
    assert!(
        human.get("tagline").is_none() && human.get("roleLabel").is_none(),
        "{human}"
    );

    // `config` is also a free bag written at creation: a non-string or oversized
    // value under a card key reads as unset, on the roster and in the card.
    sqlx::query(
        "UPDATE agent SET config = config || jsonb_build_object('roleLabel', 5, \
            'tagline', repeat('x', 200)) WHERE member_id=$1",
    )
    .bind(fixture.hosted_agent)
    .execute(&su)
    .await
    .unwrap();
    let roster: Value = client
        .get(format!("{base}/v1/workspaces/{}/roster", fixture.workspace))
        .bearer_auth(&fixture.human_jwt)
        .send()
        .await
        .unwrap()
        .json()
        .await
        .unwrap();
    let members = roster["members"]
        .as_array()
        .or(roster.as_array())
        .expect("roster list");
    let me = members
        .iter()
        .find(|m| m["id"] == json!(fixture.hosted_agent.to_string()))
        .unwrap();
    assert!(
        me.get("roleLabel").is_none() && me.get("tagline").is_none(),
        "{me}"
    );
    // Put the good card back for the steps below.
    sqlx::query(
        "UPDATE agent SET config = config || jsonb_build_object('roleLabel', '영업 비서'::text, \
            'tagline', '영업 요약을 정리해요'::text) WHERE member_id=$1",
    )
    .bind(fixture.hosted_agent)
    .execute(&su)
    .await
    .unwrap();

    // ---- a field that changed under the card re-asks -----------------------
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.profile.update",
        json!({"tagline": "새 소개예요"}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let stale = proposed_approval_3706(&proposed);
    sqlx::query("UPDATE agent SET config = jsonb_set(config, '{tagline}', '\"바뀐 소개\"') WHERE member_id=$1")
        .bind(fixture.hosted_agent)
        .execute(&su)
        .await
        .unwrap();
    let (status, _h, refused) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &owner_jwt,
        stale,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{refused}");
    assert_eq!(refused["status"], "action_args_invalid");
    assert_eq!(approval_status_3708(&su, stale).await, "pending");
    assert_eq!(
        profile_row_3785(&su, fixture.hosted_agent)
            .await
            .0
            .as_deref(),
        Some("바뀐 소개")
    );

    // The stale card is rejected (a second pending proposal on the same target
    // is a conflict, V4-M-9), then a clear is proposed.
    let (status, _h, rejected) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &owner_jwt,
        stale,
        false,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{rejected}");

    // ---- null clears --------------------------------------------------------
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.profile.update",
        json!({"tagline": null, "roleLabel": null, "statusText": null, "statusEmoji": null}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let clear = proposed_approval_3706(&proposed);
    let (status, _h, approved) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &owner_jwt,
        clear,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(
        profile_row_3785(&su, fixture.hosted_agent).await,
        (None, None, None, None)
    );
    // Clearing what is already clear changes nothing, so it is not a proposal.
    let (status, nothing) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.profile.update",
        json!({"tagline": null}),
    )
    .await;
    assert_eq!(status, 400, "{nothing}");
}

/// The name rides the same card (one approval, two audit rows), and another
/// agent is a target only when it has the **same owner** (V4-M): a stranger's
/// agent, an ownerless one and a human handle are one refusal.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_profile_update_may_rename_and_may_target_only_a_managed_agent() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (owner, owner_jwt) = seed_human_3708(&su, &fixture, "owner", "member").await;
    let (stranger, _stranger_jwt) = seed_human_3708(&su, &fixture, "stranger", "member").await;
    set_agent_owner_3708(&su, fixture.hosted_agent, Some(owner)).await;
    set_agent_owner_3708(&su, fixture.managed_agent, Some(stranger)).await;
    tidy_agent_3708(&su, fixture.hosted_agent, "Hermes").await;
    let other_handle = tidy_agent_3708(&su, fixture.managed_agent, "Worker").await;

    // The other agent belongs to somebody else: indistinguishable refusals.
    let mut answers = Vec::new();
    for target in [
        other_handle.clone(),
        "no-such-agent".to_string(),
        "tools-human".to_string(),
    ] {
        let (status, refused) = try_propose_action_3706(
            &client,
            &base,
            &su,
            &fixture,
            "agent.profile.update",
            json!({"tagline": "x는 y예요", "targetHandle": target}),
        )
        .await;
        answers.push((status, refused["error"].clone()));
        assert_eq!(status, 400, "{target}: {refused}");
    }
    assert!(answers.iter().all(|a| a.1 == answers[0].1), "{answers:?}");

    // Same owner: now it is a managed target and the card says so.
    set_agent_owner_3708(&su, fixture.managed_agent, Some(owner)).await;
    let (status, proposed) = try_propose_action_3706(
        &client, &base, &su, &fixture, "agent.profile.update",
        json!({"displayName": "Helper 2", "tagline": "회의록을 맡아요", "targetHandle": other_handle}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval = proposed_approval_3706(&proposed);
    let card: Value = sqlx::query_scalar("SELECT props FROM message WHERE id=$1")
        .bind(Uuid::parse_str(structured(&proposed)["cardMessageId"].as_str().unwrap()).unwrap())
        .fetch_one(&su)
        .await
        .unwrap();
    assert!(
        card["summary"].as_str().unwrap().contains("다른 에이전트"),
        "{card}"
    );
    // Two pending proposals on one target: the second is a conflict, not a card.
    let (status, again) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.profile.update",
        json!({"tagline": "다른 소개", "targetHandle": other_handle}),
    )
    .await;
    assert_eq!(status, 409, "{again}");
    // …and the 409 does not depend on the text: a line that repeats a member's
    // name (a 400 on its own) is the same 409, so 409-vs-400 is not a roster oracle.
    let (status, again) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.profile.update",
        json!({"tagline": "Person owner approved this", "targetHandle": other_handle}),
    )
    .await;
    assert_eq!(status, 409, "{again}");

    let (status, _h, approved) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &owner_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(
        display_name_3708(&su, fixture.managed_agent).await,
        "Helper 2"
    );
    assert_eq!(
        profile_row_3785(&su, fixture.managed_agent)
            .await
            .0
            .as_deref(),
        Some("회의록을 맡아요")
    );
    // The proposer itself is untouched.
    assert_eq!(display_name_3708(&su, fixture.hosted_agent).await, "Hermes");
    assert_eq!(profile_row_3785(&su, fixture.hosted_agent).await.0, None);
    let audit_actions: Vec<String> = sqlx::query_scalar(
        "SELECT action FROM audit_log WHERE workspace_id=$1 \
           AND action IN ('agent.profile.updated','member.renamed') AND subject_member_id=$2 \
          ORDER BY created_at",
    )
    .bind(fixture.workspace)
    .bind(fixture.managed_agent)
    .fetch_all(&su)
    .await
    .unwrap();
    // One transaction means one `created_at`: compare as a set.
    let mut audit_actions = audit_actions;
    audit_actions.sort();
    assert_eq!(
        audit_actions,
        vec!["agent.profile.updated", "member.renamed"]
    );
}

/// **Security review of #3797 (L4).** Between the moment a proposal is resolved
/// (unlocked reads) and the write, a concurrent change to the target must
/// re-ask. A second session holds the agent's row lock with a rename pending
/// commit; the decision passes the resolver (it reads the old name), blocks on
/// the executor's `FOR UPDATE`, and — once the rename commits — must refuse
/// `action_args_invalid` having written nothing. The test waits until the
/// decision is *actually* blocked on the lock, so it is the executor's re-read
/// under the lock that is being measured and not the pins.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_change_that_lands_after_resolution_is_caught_under_the_lock() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (owner, owner_jwt) = seed_human_3708(&su, &fixture, "owner", "member").await;
    set_agent_owner_3708(&su, fixture.hosted_agent, Some(owner)).await;
    tidy_agent_3708(&su, fixture.hosted_agent, "Hermes").await;

    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.profile.update",
        json!({"tagline": "새 소개예요"}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval = proposed_approval_3706(&proposed);

    // Hold the row lock and stage a rename that has not committed yet.
    let mut blocker = su.begin().await.unwrap();
    sqlx::query("SELECT id FROM member WHERE id=$1 FOR UPDATE")
        .bind(fixture.hosted_agent)
        .execute(&mut *blocker)
        .await
        .unwrap();

    let decision = {
        let (client, base, jwt, ws) = (
            client.clone(),
            base.clone(),
            owner_jwt.clone(),
            fixture.workspace,
        );
        tokio::spawn(async move {
            decide_as(&client, &base, ws, &jwt, approval, true, Uuid::new_v4()).await
        })
    };
    // Wait until the decision transaction is parked on a row lock.
    let mut waited = false;
    for _ in 0..200 {
        let blocked: i64 = sqlx::query_scalar(
            "SELECT count(*) FROM pg_stat_activity \
              WHERE wait_event_type = 'Lock' AND state = 'active' AND query ILIKE '%FOR UPDATE%'",
        )
        .fetch_one(&su)
        .await
        .unwrap();
        if blocked > 0 {
            waited = true;
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
    }
    assert!(waited, "the decision never reached the executor's row lock");
    sqlx::query("UPDATE member SET display_name = 'Renamed Meanwhile' WHERE id=$1")
        .bind(fixture.hosted_agent)
        .execute(&mut *blocker)
        .await
        .unwrap();
    blocker.commit().await.unwrap();

    let (status, _h, refused) = decision.await.unwrap();
    assert_eq!(status, 409, "{refused}");
    assert_eq!(refused["status"], "action_args_invalid");
    assert_eq!(approval_status_3708(&su, approval).await, "pending");
    assert_eq!(
        profile_row_3785(&su, fixture.hosted_agent).await.0,
        None,
        "nothing was written"
    );
    assert_eq!(
        display_name_3708(&su, fixture.hosted_agent).await,
        "Renamed Meanwhile"
    );
}

/// **Security review of #3797 (F1) — lock order.** Proposing takes the
/// display-name advisory lock *before* any member row, exactly as an approval and
/// the human `PATCH …/agents/{agent}` do; the reverse order is a deadlock with a
/// concurrent approval. A second session holds the advisory lock; the proposal
/// parks on it; and while it is parked the agent's member row must still be free
/// (`FOR UPDATE NOWAIT` succeeds) — a proposal that had already taken the row
/// first would make that fail.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_proposal_takes_the_advisory_lock_before_any_member_row() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (owner, _jwt) = seed_human_3708(&su, &fixture, "owner", "member").await;
    set_agent_owner_3708(&su, fixture.hosted_agent, Some(owner)).await;
    tidy_agent_3708(&su, fixture.hosted_agent, "Hermes").await;

    let mut blocker = su.begin().await.unwrap();
    sqlx::query("SELECT pg_advisory_xact_lock(hashtextextended('display-name:' || $1::text, 0))")
        .bind(fixture.workspace.to_string())
        .execute(&mut *blocker)
        .await
        .unwrap();

    let propose = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.profile.update",
        json!({"tagline": "새 소개예요"}),
    );
    let agent = fixture.hosted_agent;
    let control = async {
        let mut parked = false;
        for _ in 0..200 {
            let waiting: i64 = sqlx::query_scalar(
                "SELECT count(*) FROM pg_stat_activity \
                  WHERE wait_event_type = 'Lock' AND wait_event = 'advisory'",
            )
            .fetch_one(&su)
            .await
            .unwrap();
            if waiting > 0 {
                parked = true;
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }
        assert!(parked, "the proposal never parked on the advisory lock");
        // While it is parked, the proposer's row is not held by it.
        let free = sqlx::query("SELECT id FROM member WHERE id = $1 FOR UPDATE NOWAIT")
            .bind(agent)
            .fetch_all(&su)
            .await;
        assert!(
            free.is_ok(),
            "the proposal took the member row before the advisory lock: {free:?}"
        );
        blocker.commit().await.unwrap();
    };
    let ((status, proposed), ()) = tokio::join!(propose, control);
    assert_eq!(status, 200, "{proposed}");
}

// ---------------------------------------------------------------------------
// ADR-0186 증보 2026-10-13 v3 A0 (#3786) — agent_avatar_image (migration 131)
// ---------------------------------------------------------------------------

/// The well-known 1×1 PNG.
const TINY_PNG_B64_3786: &str =
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==";

async fn tenant_3786<T: Send + 'static>(
    pool: &PgPool,
    workspace: Uuid,
    body: impl for<'c> FnOnce(
            &'c mut momo_db::PgConnection,
        ) -> std::pin::Pin<
            Box<dyn std::future::Future<Output = Result<T, momo_db::DbError>> + Send + 'c>,
        > + Send,
) -> Result<T, momo_db::DbError> {
    momo_db::with_tenant_tx(pool, workspace, body).await
}

/// Stage `processed` for `agent` and bind it to a fresh approval id (the order the
/// proposal path uses: stage, create the approval, bind). Returns `(image, approval)`.
async fn stage_bound_3786(
    app: &PgPool,
    ws: Uuid,
    agent: Uuid,
    processed: &momo_messaging::ProcessedAvatar,
) -> (Uuid, Uuid) {
    let p = processed.clone();
    let approval = Uuid::new_v4();
    let image = tenant_3786(app, ws, move |conn| {
        Box::pin(async move {
            let image =
                momo_messaging::stage_avatar_image_in_tx(conn, ws, agent, agent, "generated", &p)
                    .await?;
            assert!(
                momo_messaging::bind_staged_image_to_approval_in_tx(conn, ws, image, approval)
                    .await?
            );
            Ok(image)
        })
    })
    .await
    .expect("stage and bind");
    (image, approval)
}

/// **The stored agent avatar, end to end at the database and the proxy.**
/// staged rows are immutable (trigger) and pinned by a hash the database
/// recomputes; the pointer can only name the member's own image (composite FK);
/// RLS hides another workspace's rows; applying replaces and deletes the previous
/// image; the content proxy serves exactly the re-encoded bytes with the
/// sandbox headers and a version token that must be current; clearing removes it.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn an_agent_avatar_image_is_staged_pinned_applied_and_served() {
    use base64::Engine as _;
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app.clone(), true).await;
    let client = reqwest::Client::new();
    let ws = fixture.workspace;
    let agent = fixture.hosted_agent;
    let other_agent = fixture.managed_agent;

    let input = base64::engine::general_purpose::STANDARD
        .decode(TINY_PNG_B64_3786)
        .unwrap();
    let processed = momo_messaging::process_avatar_image(&input, 1 << 20).expect("a valid image");
    assert_eq!(processed.mime, "image/png");

    // ---- stage (bound to its approval, as the proposal path does) -------------
    let (first, appr_first) = stage_bound_3786(&app, ws, agent, &processed).await;
    let sha = processed.sha256.to_vec();

    // ---- the pin: right hash, wrong hash, wrong member, wrong approval ----------
    let (s1, s2) = (sha.clone(), vec![0u8; 32]);
    // A staged row that was never bound to any approval.
    let p = processed.clone();
    let unbound = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move {
            momo_messaging::stage_avatar_image_in_tx(conn, ws, agent, agent, "generated", &p).await
        })
    })
    .await
    .unwrap();
    let s3 = sha.clone();
    let pins = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move {
            Ok((
                momo_messaging::staged_image_matches_pin_in_tx(
                    conn, ws, first, agent, appr_first, &s1,
                )
                .await?,
                momo_messaging::staged_image_matches_pin_in_tx(
                    conn, ws, first, agent, appr_first, &s2,
                )
                .await?,
                momo_messaging::staged_image_matches_pin_in_tx(
                    conn,
                    ws,
                    first,
                    other_agent,
                    appr_first,
                    &s1,
                )
                .await?,
                momo_messaging::staged_image_matches_pin_in_tx(
                    conn,
                    ws,
                    first,
                    agent,
                    Uuid::new_v4(),
                    &s1,
                )
                .await?,
                momo_messaging::staged_image_matches_pin_in_tx(
                    conn, ws, unbound, agent, appr_first, &s3,
                )
                .await?,
            ))
        })
    })
    .await
    .unwrap();
    assert_eq!(
        pins,
        (true, false, false, false, false),
        "right hash/member/approval only; an unbound row or another approval never matches"
    );
    sqlx::query("DELETE FROM agent_avatar_image WHERE id=$1")
        .bind(unbound)
        .execute(&su)
        .await
        .unwrap();
    // A second image cannot be bound to the same approval (UNIQUE), and a row cannot
    // be bound twice (the function reports it).
    let p = processed.clone();
    let collision = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move {
            let again =
                momo_messaging::stage_avatar_image_in_tx(conn, ws, agent, agent, "generated", &p)
                    .await?;
            Ok((
                again,
                momo_messaging::bind_staged_image_to_approval_in_tx(
                    conn,
                    ws,
                    first,
                    Uuid::new_v4(),
                )
                .await?,
            ))
        })
    })
    .await
    .unwrap();
    assert!(!collision.1, "a bound row is not re-bound");
    let duplicate = sqlx::query("UPDATE agent_avatar_image SET approval_id = $2 WHERE id = $1")
        .bind(collision.0)
        .bind(appr_first)
        .execute(&su)
        .await
        .expect_err("one approval, one image")
        .to_string();
    assert!(
        duplicate.contains("agent_avatar_approval_uniq"),
        "{duplicate}"
    );
    sqlx::query("DELETE FROM agent_avatar_image WHERE id=$1")
        .bind(collision.0)
        .execute(&su)
        .await
        .unwrap();

    // ---- immutability: the trigger refuses every column but status ----------
    //
    // Each replacement is a **valid** value (same length, in range, a real member),
    // so the CHECKs and foreign keys would let it through: only the trigger can say
    // no, and the message must be the trigger's.
    for statement in [
        "UPDATE agent_avatar_image SET bytes = set_byte(bytes, 0, 255) WHERE id = $1",
        "UPDATE agent_avatar_image SET sha256 = decode(repeat('00', 32), 'hex') WHERE id = $1",
        "UPDATE agent_avatar_image SET mime = 'image/jpeg' WHERE id = $1",
        "UPDATE agent_avatar_image SET member_id = $2 WHERE id = $1",
        "UPDATE agent_avatar_image SET proposed_by = $2 WHERE id = $1",
        "UPDATE agent_avatar_image SET width = width - 1 WHERE id = $1",
        "UPDATE agent_avatar_image SET height = height - 1 WHERE id = $1",
        "UPDATE agent_avatar_image SET size_bytes = size_bytes WHERE id = $1 AND false",
        "UPDATE agent_avatar_image SET source = CASE source WHEN 'generated' THEN 'attachment' \
                                                ELSE 'generated' END WHERE id = $1",
        "UPDATE agent_avatar_image SET created_at = created_at - interval '1 day' WHERE id = $1",
    ] {
        let result = sqlx::query(statement)
            .bind(first)
            .bind(other_agent)
            .execute(&su)
            .await;
        if statement.contains("AND false") {
            assert!(result.is_ok(), "a no-op statement is not a change");
            continue;
        }
        let error = result.expect_err(statement).to_string();
        assert!(error.contains("immutable"), "{statement}: {error}");
    }
    // A write-once binding: a bound row is never re-bound or unbound.
    let rebind = sqlx::query("UPDATE agent_avatar_image SET approval_id = $2 WHERE id = $1")
        .bind(first)
        .bind(Uuid::new_v4())
        .execute(&su)
        .await
        .expect_err("a bound row cannot be re-bound")
        .to_string();
    assert!(rebind.contains("write-once"), "{rebind}");
    let unbind = sqlx::query("UPDATE agent_avatar_image SET approval_id = NULL WHERE id = $1")
        .bind(first)
        .execute(&su)
        .await
        .expect_err("a bound row cannot be unbound")
        .to_string();
    assert!(unbind.contains("write-once"), "{unbind}");
    // The status can only move forward.
    sqlx::query("UPDATE agent_avatar_image SET status = 'applied' WHERE id = $1")
        .bind(first)
        .execute(&su)
        .await
        .unwrap();
    let back = sqlx::query("UPDATE agent_avatar_image SET status = 'staged' WHERE id = $1")
        .bind(first)
        .execute(&su)
        .await
        .expect_err("applied cannot go back to staged")
        .to_string();
    assert!(back.contains("staged"), "{back}");
    // An applied row is no longer a pin target.
    let (s0, applied_pin) = (sha.clone(), {
        let sha = sha.clone();
        tenant_3786(&app, ws, move |conn| {
            Box::pin(async move {
                momo_messaging::staged_image_matches_pin_in_tx(
                    conn, ws, first, agent, appr_first, &sha,
                )
                .await
            })
        })
        .await
        .unwrap()
    });
    assert!(
        !applied_pin,
        "only a staged row can satisfy a pin ({} bytes of pin)",
        s0.len()
    );
    // Rows are inserted staged and unbound, for an agent of the same workspace.
    for (label, statement) in [
        (
            "applied on insert",
            "INSERT INTO agent_avatar_image (workspace_id, member_id, proposed_by, source, mime, \
                width, height, size_bytes, sha256, bytes, status) \
             SELECT workspace_id, member_id, proposed_by, source, mime, width, height, size_bytes, \
                    sha256, bytes, 'applied' FROM agent_avatar_image WHERE id = $1",
        ),
        // Migration 148 (ADR-0186 증보 v4): a person MAY be the owner of an image — the one
        // an agent staged for them (`member.avatar.set`) — but never its proposer.
        (
            "a human as the proposer",
            "INSERT INTO agent_avatar_image (workspace_id, member_id, proposed_by, source, mime, \
                width, height, size_bytes, sha256, bytes) \
             SELECT workspace_id, member_id, $2, source, mime, width, height, size_bytes, \
                    sha256, bytes FROM agent_avatar_image WHERE id = $1",
        ),
        (
            "an unknown source",
            "INSERT INTO agent_avatar_image (workspace_id, member_id, proposed_by, source, mime, \
                width, height, size_bytes, sha256, bytes) \
             SELECT workspace_id, member_id, proposed_by, 'url', mime, width, height, size_bytes, \
                    sha256, bytes FROM agent_avatar_image WHERE id = $1",
        ),
        (
            "a size that is not the byte length",
            "INSERT INTO agent_avatar_image (workspace_id, member_id, proposed_by, source, mime, \
                width, height, size_bytes, sha256, bytes) \
             SELECT workspace_id, member_id, proposed_by, source, mime, width, height, \
                    size_bytes + 1, sha256, bytes FROM agent_avatar_image WHERE id = $1",
        ),
        (
            "an out-of-range canvas",
            "INSERT INTO agent_avatar_image (workspace_id, member_id, proposed_by, source, mime, \
                width, height, size_bytes, sha256, bytes) \
             SELECT workspace_id, member_id, proposed_by, source, mime, 513, height, size_bytes, \
                    sha256, bytes FROM agent_avatar_image WHERE id = $1",
        ),
    ] {
        let human = fixture.human;
        let result = sqlx::query(statement)
            .bind(first)
            .bind(human)
            .execute(&su)
            .await;
        assert!(result.is_err(), "{label} must be refused");
    }
    // A member of ANOTHER workspace can be neither the owner nor the proposer of a
    // row here: the composite foreign keys say so, whatever RLS does or does not
    // hide from a foreign-key check.
    let elsewhere = seed(&su).await;
    for column in ["member_id", "proposed_by"] {
        let statement =
            format!(
            "INSERT INTO agent_avatar_image (workspace_id, member_id, proposed_by, source, mime, \
                width, height, size_bytes, sha256, bytes) \
             SELECT workspace_id, {member}, {proposer}, source, mime, width, height, size_bytes, \
                    sha256, bytes FROM agent_avatar_image WHERE id = $1",
            member = if column == "member_id" { "$2" } else { "member_id" },
            proposer = if column == "proposed_by" { "$2" } else { "proposed_by" },
        );
        let error = sqlx::query(&statement)
            .bind(first)
            .bind(elsewhere.hosted_agent)
            .execute(&su)
            .await
            .expect_err("a member of another workspace must be refused")
            .to_string();
        assert!(error.contains("agent_avatar_"), "{column}: {error}");
    }
    // The applied row is the member's pointer target in the next block; for now
    // make it the member's current image, then delete it: the pointer goes NULL.
    sqlx::query("UPDATE member SET avatar_image_id = $1 WHERE id = $2")
        .bind(first)
        .bind(agent)
        .execute(&su)
        .await
        .unwrap();
    // One avatar at a time: an uploaded avatar and an image avatar do not coexist.
    let media: Uuid = sqlx::query_scalar(
        "INSERT INTO member_avatar_media (workspace_id, member_id, drive_file_id, name, mime, \
            size_bytes, status) VALUES ($1,$2,'drive-3786','a.png','image/png',10,'complete') \
         RETURNING id",
    )
    .bind(ws)
    .bind(agent)
    .fetch_one(&su)
    .await
    .unwrap();
    let both = sqlx::query("UPDATE member SET avatar_media_id = $1 WHERE id = $2")
        .bind(media)
        .bind(agent)
        .execute(&su)
        .await
        .expect_err("both pointers set must be refused")
        .to_string();
    assert!(both.contains("member_avatar_exclusive_ck"), "{both}");
    sqlx::query("DELETE FROM member_avatar_media WHERE id = $1")
        .bind(media)
        .execute(&su)
        .await
        .unwrap();
    sqlx::query("DELETE FROM agent_avatar_image WHERE id = $1")
        .bind(first)
        .execute(&su)
        .await
        .unwrap();
    let pointer: Option<Uuid> =
        sqlx::query_scalar("SELECT avatar_image_id FROM member WHERE id=$1")
            .bind(agent)
            .fetch_one(&su)
            .await
            .unwrap();
    assert_eq!(pointer, None, "deleting the image clears the pointer");
    // Re-create a staged row for the tamper check below (the first one is gone).
    let (first, appr_first) = stage_bound_3786(&app, ws, agent, &processed).await;
    // …and if the trigger were somehow bypassed, the pin check still notices,
    // because the database recomputes the digest from the stored bytes.
    sqlx::query("ALTER TABLE agent_avatar_image DISABLE TRIGGER agent_avatar_image_immutable_trg")
        .execute(&su)
        .await
        .unwrap();
    sqlx::query(
        "UPDATE agent_avatar_image SET bytes = '\\x89504e47'::bytea, size_bytes = 4 WHERE id=$1",
    )
    .bind(first)
    .execute(&su)
    .await
    .unwrap();
    let s1 = sha.clone();
    let tampered = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move {
            momo_messaging::staged_image_matches_pin_in_tx(conn, ws, first, agent, appr_first, &s1)
                .await
        })
    })
    .await
    .unwrap();
    assert!(
        !tampered,
        "a row whose bytes changed no longer matches its pin"
    );
    sqlx::query("DELETE FROM agent_avatar_image WHERE id=$1")
        .bind(first)
        .execute(&su)
        .await
        .unwrap();
    sqlx::query("ALTER TABLE agent_avatar_image ENABLE TRIGGER agent_avatar_image_immutable_trg")
        .execute(&su)
        .await
        .unwrap();

    // ---- stage again, then the composite FK and RLS --------------------------
    let p = processed.clone();
    let appr_image = Uuid::new_v4();
    let image = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move {
            let image =
                momo_messaging::stage_avatar_image_in_tx(conn, ws, agent, agent, "attachment", &p)
                    .await?;
            momo_messaging::bind_staged_image_to_approval_in_tx(conn, ws, image, appr_image)
                .await?;
            Ok(image)
        })
    })
    .await
    .unwrap();
    // A pointer at another member's image is not representable.
    let wrong = sqlx::query("UPDATE member SET avatar_image_id = $1 WHERE id = $2")
        .bind(image)
        .bind(other_agent)
        .execute(&su)
        .await;
    assert!(wrong.is_err(), "the pointer FK must be self-only");
    // Row-level security, not the query's own WHERE: the right workspace id is
    // asked for, but under another tenant's GUC — and the same call under the right
    // GUC finds the row, so the only difference is RLS.
    let found = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move { momo_messaging::read_avatar_image_in_tx(conn, ws, image).await })
    })
    .await
    .unwrap();
    assert!(found.is_some(), "control: visible under its own tenant");
    let foreign = tenant_3786(&app, Uuid::new_v4(), move |conn| {
        Box::pin(async move { momo_messaging::read_avatar_image_in_tx(conn, ws, image).await })
    })
    .await
    .unwrap();
    assert!(foreign.is_none(), "invisible under another tenant's GUC");
    // A staged image is not served: the pointer is unset.
    let url = format!("{base}/v1/workspaces/{ws}/members/{agent}/avatar/content");
    let before = client
        .get(&url)
        .bearer_auth(&fixture.human_jwt)
        .send()
        .await
        .unwrap();
    assert_eq!(
        before.status().as_u16(),
        404,
        "a staged image is never served"
    );
    // Even a pointer forced at a staged row (a bug, a manual edit) serves nothing:
    // the read itself requires `applied`.
    sqlx::query("UPDATE member SET avatar_image_id = $1 WHERE id = $2")
        .bind(image)
        .bind(agent)
        .execute(&su)
        .await
        .unwrap();
    let forced = client
        .get(&url)
        .bearer_auth(&fixture.human_jwt)
        .send()
        .await
        .unwrap();
    assert_eq!(
        forced.status().as_u16(),
        404,
        "a staged row behind the pointer is not served"
    );
    sqlx::query("UPDATE member SET avatar_image_id = NULL WHERE id = $1")
        .bind(agent)
        .execute(&su)
        .await
        .unwrap();

    // ---- apply ---------------------------------------------------------------
    let applied = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move {
            // Under another approval's id the same staged row is not applicable.
            let wrong =
                momo_messaging::apply_avatar_image_in_tx(conn, ws, agent, image, Uuid::new_v4())
                    .await?;
            assert_eq!(wrong, None, "another approval cannot apply this image");
            momo_messaging::apply_avatar_image_in_tx(conn, ws, agent, image, appr_image).await
        })
    })
    .await
    .unwrap();
    assert_eq!(applied, Some(None), "applied, with no previous image");
    // Applying something that is not staged (or twice) is refused.
    let again = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move {
            momo_messaging::apply_avatar_image_in_tx(conn, ws, agent, image, appr_image).await
        })
    })
    .await
    .unwrap();
    assert_eq!(again, None);

    // ---- the proxy -----------------------------------------------------------
    let versioned = format!("{url}?v={image}");
    let served = client
        .get(&versioned)
        .bearer_auth(&fixture.human_jwt)
        .send()
        .await
        .unwrap();
    assert_eq!(served.status().as_u16(), 200);
    let headers = served.headers().clone();
    assert_eq!(headers["content-type"], "image/png");
    assert_eq!(headers["x-content-type-options"], "nosniff");
    assert_eq!(
        headers["content-security-policy"],
        "default-src 'none'; sandbox"
    );
    assert!(headers["cache-control"]
        .to_str()
        .unwrap()
        .contains("immutable"));
    assert_eq!(served.bytes().await.unwrap().to_vec(), processed.bytes);
    let stale = client
        .get(format!("{url}?v={}", Uuid::new_v4()))
        .bearer_auth(&fixture.human_jwt)
        .send()
        .await
        .unwrap();
    assert_eq!(
        stale.status().as_u16(),
        404,
        "a version that is not current is not served"
    );
    let bare = client
        .get(&url)
        .bearer_auth(&fixture.human_jwt)
        .send()
        .await
        .unwrap();
    assert_eq!(bare.status().as_u16(), 200);
    assert_eq!(bare.headers()["cache-control"], "private, no-cache");

    // ---- the roster hands out the versioned URL --------------------------------
    let roster: Value = client
        .get(format!("{base}/v1/workspaces/{ws}/roster"))
        .bearer_auth(&fixture.human_jwt)
        .send()
        .await
        .unwrap()
        .json()
        .await
        .unwrap();
    let members = roster["members"]
        .as_array()
        .or(roster.as_array())
        .expect("roster list");
    let me = members
        .iter()
        .find(|m| m["id"] == json!(agent.to_string()))
        .unwrap();
    assert_eq!(
        me["avatarUrl"],
        json!(format!(
            "/v1/workspaces/{ws}/members/{agent}/avatar/content?v={image}"
        ))
    );

    // ---- replace: the previous image row is deleted ------------------------------
    let (second, appr_second) = stage_bound_3786(&app, ws, agent, &processed).await;
    let replaced = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move {
            momo_messaging::apply_avatar_image_in_tx(conn, ws, agent, second, appr_second).await
        })
    })
    .await
    .unwrap();
    assert_eq!(replaced, Some(Some(image)));
    let rows: i64 =
        sqlx::query_scalar("SELECT count(*) FROM agent_avatar_image WHERE member_id=$1")
            .bind(agent)
            .fetch_one(&su)
            .await
            .unwrap();
    assert_eq!(rows, 1, "only the current image remains");

    // ---- stale staged rows are swept; an applied one never is --------------------
    let p = processed.clone();
    let old_staged = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move {
            momo_messaging::stage_avatar_image_in_tx(conn, ws, agent, agent, "generated", &p).await
        })
    })
    .await
    .unwrap();
    sqlx::query("ALTER TABLE agent_avatar_image DISABLE TRIGGER agent_avatar_image_immutable_trg")
        .execute(&su)
        .await
        .unwrap();
    sqlx::query("UPDATE agent_avatar_image SET created_at = now() - interval '25 hours' WHERE id IN ($1,$2)")
        .bind(old_staged)
        .bind(second)
        .execute(&su)
        .await
        .unwrap();
    sqlx::query("ALTER TABLE agent_avatar_image ENABLE TRIGGER agent_avatar_image_immutable_trg")
        .execute(&su)
        .await
        .unwrap();
    let purged = tenant_3786(&app, ws, move |conn| {
        Box::pin(
            async move { momo_messaging::purge_stale_staged_avatar_images_in_tx(conn, ws).await },
        )
    })
    .await
    .unwrap();
    assert_eq!(
        purged, 1,
        "the old staged row goes, the old APPLIED row stays"
    );
    let left: i64 =
        sqlx::query_scalar("SELECT count(*) FROM agent_avatar_image WHERE member_id=$1")
            .bind(agent)
            .fetch_one(&su)
            .await
            .unwrap();
    assert_eq!(left, 1);

    // ---- clear ------------------------------------------------------------------
    let cleared = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move { momo_messaging::clear_avatar_image_in_tx(conn, ws, agent).await })
    })
    .await
    .unwrap();
    assert!(cleared);
    let gone = client
        .get(&url)
        .bearer_auth(&fixture.human_jwt)
        .send()
        .await
        .unwrap();
    assert_eq!(gone.status().as_u16(), 404);
    let pointer: Option<Uuid> =
        sqlx::query_scalar("SELECT avatar_image_id FROM member WHERE id=$1")
            .bind(agent)
            .fetch_one(&su)
            .await
            .unwrap();
    assert_eq!(pointer, None);
}

// ---------------------------------------------------------------------------
// ADR-0186 증보 2026-10-13 v3 A1 (#3787) — avatar sources, staging, pins, preview
// ---------------------------------------------------------------------------

/// An in-memory Drive archive: `file_content` answers the bytes registered under a
/// Drive file id. Everything else is refused (the avatar path only reads).
#[derive(Debug, Default)]
struct MemDrive3787 {
    files: std::sync::Mutex<std::collections::HashMap<String, Vec<u8>>>,
    content_reads: std::sync::atomic::AtomicUsize,
}

#[async_trait::async_trait]
impl momo_drive::DriveArchive for MemDrive3787 {
    async fn create_resumable_upload(
        &self,
        _channel_id: Uuid,
        _name: &str,
        _mime: &str,
        _size_bytes: i64,
    ) -> Result<momo_drive::DriveUploadSession, momo_drive::DriveError> {
        Err(momo_drive::DriveError::Unavailable)
    }

    async fn file_metadata(
        &self,
        file_id: &str,
    ) -> Result<momo_drive::DriveFile, momo_drive::DriveError> {
        let files = self.files.lock().unwrap();
        let bytes = files
            .get(file_id)
            .ok_or(momo_drive::DriveError::FileNotFound)?;
        Ok(momo_drive::DriveFile {
            drive_file_id: file_id.to_string(),
            name: "x".into(),
            mime: "image/png".into(),
            size_bytes: bytes.len() as i64,
        })
    }

    async fn file_content(
        &self,
        file_id: &str,
        _max_bytes: i64,
    ) -> Result<momo_drive::DriveContent, momo_drive::DriveError> {
        self.content_reads
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let bytes = self
            .files
            .lock()
            .unwrap()
            .get(file_id)
            .cloned()
            .ok_or(momo_drive::DriveError::FileNotFound)?;
        let size = bytes.len() as i64;
        Ok(momo_drive::DriveContent {
            mime: "image/png".into(),
            size_bytes: size,
            body: Box::pin(futures::stream::iter(vec![Ok(axum::body::Bytes::from(
                bytes,
            ))])),
        })
    }
}

async fn start_server_with_drive_3787(
    pool: PgPool,
    drive: Arc<dyn momo_drive::DriveArchive>,
) -> String {
    let state = AppState::new(
        pool,
        TEST_JWT_SECRET.to_string(),
        "ws://127.0.0.1:8000/connection/websocket".to_string(),
    )
    .with_drive(drive)
    .with_agent_port(AgentPortConfig {
        external_origin: None,
        window_seconds: 60,
        per_token_limit: 0,
        per_agent_limit: 0,
        per_ip_limit: 0,
        hosted_delivery_enabled: true,
        hosted_lease_seconds: momo_outbox::HOSTED_LEASE_SECONDS_DEFAULT,
        subscription_agents_enabled: true,
        claude_subscription_agents_enabled: true,
        oauth: Default::default(),
    });
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("bind avatar conformance server");
    let address: SocketAddr = listener.local_addr().expect("server address");
    tokio::spawn(async move {
        let _ = axum::serve(
            listener,
            build_app(state).into_make_service_with_connect_info::<SocketAddr>(),
        )
        .await;
    });
    format!("http://{address}")
}

fn b64_3787(bytes: &[u8]) -> String {
    use base64::Engine as _;
    base64::engine::general_purpose::STANDARD.encode(bytes)
}

fn tiny_png_3787() -> Vec<u8> {
    use base64::Engine as _;
    base64::engine::general_purpose::STANDARD
        .decode(TINY_PNG_B64_3786)
        .unwrap()
}

async fn staged_rows_3787(pool: &PgPool, ws: Uuid) -> i64 {
    sqlx::query_scalar("SELECT count(*) FROM agent_avatar_image WHERE workspace_id=$1")
        .bind(ws)
        .fetch_one(pool)
        .await
        .unwrap()
}

/// **An agent proposes an avatar it generated — the whole loop.** Hostile inputs
/// are one refusal and leave no staged row; a good image is re-encoded, staged,
/// bound to its approval, previewed to the approver only (and by hash), pinned;
/// a third party cannot approve; tampered bytes re-ask; a swapped pin re-asks;
/// rejection and expiry delete the staged row; approval serves exactly the server's
/// bytes and the roster says so; a preset replaces it; null removes it.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn an_agent_proposes_a_generated_avatar_and_only_the_approved_bytes_are_served() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server_with_drive_3787(app, Arc::new(MemDrive3787::default())).await;
    let client = reqwest::Client::new();
    let ws = fixture.workspace;
    let agent = fixture.hosted_agent;
    let (owner, owner_jwt) = seed_human_3708(&su, &fixture, "owner", "member").await;
    let (_third, third_jwt) = seed_human_3708(&su, &fixture, "third", "member").await;
    set_agent_owner_3708(&su, agent, Some(owner)).await;
    tidy_agent_3708(&su, agent, "Hermes").await;

    let propose = |avatar: Value| {
        let (client, base, su) = (client.clone(), base.clone(), su.clone());
        let fixture = &fixture;
        async move {
            try_propose_action_3706(
                &client,
                &base,
                &su,
                fixture,
                "agent.profile.update",
                json!({ "avatar": avatar }),
            )
            .await
        }
    };

    // ---- hostile inputs: one refusal, no staged row ---------------------------
    let mut polyglot = tiny_png_3787();
    polyglot.extend_from_slice(b"<script>alert(1)</script>PK\x03\x04");
    let mut bomb_header = tiny_png_3787();
    bomb_header[16..20].copy_from_slice(&60000u32.to_be_bytes());
    let mut answers = Vec::new();
    for hostile in [
        json!({"source": "url", "url": "https://evil.example/a.png"}),
        json!({"source": "generated", "dataBase64": b64_3787(b"GIF89a\x01\x00\x01\x00\x00\x00\x00;")}),
        json!({"source": "generated", "dataBase64": b64_3787(b"<svg xmlns='http://www.w3.org/2000/svg'><script>1</script></svg>")}),
        json!({"source": "generated", "dataBase64": b64_3787(&bomb_header)}),
        json!({"source": "generated", "dataBase64": b64_3787(&[0u8; 44_001])}),
        json!({"source": "generated", "dataBase64": "not base64 !!"}),
        json!({"source": "generated", "dataBase64": format!("{}\n", b64_3787(&tiny_png_3787()))}),
        json!({"source": "generated", "dataBase64": b64_3787(&tiny_png_3787()), "mime": "image/svg+xml"}),
        json!({"source": "generated", "dataBase64": b64_3787(&tiny_png_3787()[..40])}),
        json!({"source": "preset", "presetId": "no-such-preset"}),
        json!({"source": "attachment", "attachmentId": Uuid::new_v4().to_string()}),
        json!({"source": "staged", "imageId": Uuid::new_v4().to_string(),
               "sha256": "0".repeat(64), "origin": "generated"}),
    ] {
        let (status, refused) = propose(hostile.clone()).await;
        answers.push((status, refused["error"].clone()));
        assert_eq!(status, 400, "{hostile} must be refused: {refused}");
    }
    assert!(answers.iter().all(|a| a.1 == answers[0].1), "{answers:?}");
    assert_eq!(
        staged_rows_3787(&su, ws).await,
        0,
        "a refusal stages nothing"
    );

    // ---- a good (and hostile-but-valid) image: re-encoded, staged, bound --------
    let (status, proposed) =
        propose(json!({"source": "generated", "dataBase64": b64_3787(&polyglot)})).await;
    assert_eq!(status, 200, "{proposed}");
    let approval = proposed_approval_3706(&proposed);
    let card: Value = sqlx::query_scalar("SELECT props FROM message WHERE id=$1")
        .bind(Uuid::parse_str(structured(&proposed)["cardMessageId"].as_str().unwrap()).unwrap())
        .fetch_one(&su)
        .await
        .unwrap();
    let preview = &card["action"]["preview"];
    assert_eq!(preview["kind"], "avatar_image", "{card}");
    assert_eq!(preview["origin"], "generated");
    let image_id = Uuid::parse_str(preview["imageId"].as_str().unwrap()).unwrap();
    let sha = preview["sha256"].as_str().unwrap().to_string();
    assert_eq!(sha.len(), 64);
    let rows = card["action"]["rows"].as_array().unwrap().clone();
    let picture_row = rows.iter().find(|r| r["label"] == "프로필 사진").unwrap();
    assert!(picture_row["value"]
        .as_str()
        .unwrap()
        .contains("에이전트가 만든 이미지"));
    // The stored row is the server's bytes, bound to this approval, staged.
    let (stored, status_label, bound, source): (Vec<u8>, String, Option<Uuid>, String) =
        sqlx::query_as(
            "SELECT bytes, status, approval_id, source FROM agent_avatar_image WHERE id=$1",
        )
        .bind(image_id)
        .fetch_one(&su)
        .await
        .unwrap();
    assert_eq!(status_label, "staged");
    assert_eq!(bound, Some(approval));
    assert_eq!(source, "generated");
    assert!(
        !stored.windows(8).any(|w| w == b"<script>")
            && !stored.windows(4).any(|w| w == b"PK\x03\x04"),
        "the appendix did not survive the re-encode"
    );
    assert_ne!(stored, polyglot);
    // No bytes, no base64, no agent-chosen id in the approval payload.
    let payload: Value = sqlx::query_scalar("SELECT payload FROM approval WHERE id=$1")
        .bind(approval)
        .fetch_one(&su)
        .await
        .unwrap();
    let payload_text = payload.to_string();
    assert!(
        !payload_text.contains("dataBase64") && !payload_text.contains(&b64_3787(&polyglot)[..40])
    );
    assert_eq!(payload["action"]["args"]["avatar"]["source"], "staged");
    assert_eq!(payload["action"]["pins"]["avatar"]["sha256"], json!(sha));

    // ---- the preview: the decider only, by hash ---------------------------------
    let preview_url = format!("{base}/v1/workspaces/{ws}/approvals/{approval}/avatar-preview");
    let seen = client
        .get(format!("{preview_url}?v={sha}"))
        .bearer_auth(&owner_jwt)
        .send()
        .await
        .unwrap();
    assert_eq!(seen.status().as_u16(), 200);
    assert_eq!(seen.headers()["x-content-type-options"], "nosniff");
    assert_eq!(
        seen.headers()["content-security-policy"],
        "default-src 'none'; sandbox"
    );
    assert_eq!(seen.bytes().await.unwrap().to_vec(), stored);
    for (label, jwt, query) in [
        ("a third party", third_jwt.as_str(), format!("?v={sha}")),
        (
            "a wrong hash",
            owner_jwt.as_str(),
            format!("?v={}", "0".repeat(64)),
        ),
    ] {
        let denied = client
            .get(format!("{preview_url}{query}"))
            .bearer_auth(jwt)
            .send()
            .await
            .unwrap();
        assert_eq!(denied.status().as_u16(), 404, "{label}");
    }
    let admin = client
        .get(format!("{preview_url}?v={sha}"))
        .bearer_auth(&fixture.human_jwt)
        .send()
        .await
        .unwrap();
    assert_eq!(
        admin.status().as_u16(),
        200,
        "an admin may decide, so may preview"
    );
    let agent_try = client
        .get(format!("{preview_url}?v={sha}"))
        .bearer_auth(&fixture.hosted_bearer)
        .send()
        .await
        .unwrap();
    assert!(matches!(agent_try.status().as_u16(), 401 | 403));
    let unknown = client
        .get(format!(
            "{base}/v1/workspaces/{ws}/approvals/{}/avatar-preview?v={sha}",
            Uuid::new_v4()
        ))
        .bearer_auth(&owner_jwt)
        .send()
        .await
        .unwrap();
    assert_eq!(unknown.status().as_u16(), 404);

    // ---- a third party cannot approve; tampered bytes re-ask --------------------
    let (status, _h, refused) = decide_as(
        &client,
        &base,
        ws,
        &third_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 403, "{refused}");
    assert_eq!(refused["status"], "role_required");
    sqlx::query("ALTER TABLE agent_avatar_image DISABLE TRIGGER agent_avatar_image_immutable_trg")
        .execute(&su)
        .await
        .unwrap();
    sqlx::query("UPDATE agent_avatar_image SET bytes = set_byte(bytes, 0, 7) WHERE id=$1")
        .bind(image_id)
        .execute(&su)
        .await
        .unwrap();
    let (status, _h, refused) = decide_as(
        &client,
        &base,
        ws,
        &owner_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{refused}");
    assert_eq!(refused["status"], "action_args_invalid");
    assert_eq!(approval_status_3708(&su, approval).await, "pending");
    let pointer: Option<Uuid> =
        sqlx::query_scalar("SELECT avatar_image_id FROM member WHERE id=$1")
            .bind(agent)
            .fetch_one(&su)
            .await
            .unwrap();
    assert_eq!(pointer, None, "tampered bytes were not applied");
    sqlx::query("UPDATE agent_avatar_image SET bytes = set_byte(bytes, 0, $2) WHERE id=$1")
        .bind(image_id)
        .bind(stored[0] as i32)
        .execute(&su)
        .await
        .unwrap();
    sqlx::query("ALTER TABLE agent_avatar_image ENABLE TRIGGER agent_avatar_image_immutable_trg")
        .execute(&su)
        .await
        .unwrap();

    // ---- a pin that names ANOTHER approval's image is refused -------------------
    // Reject the first so the target is free for a second proposal, then stage a
    // second image and rewrite its approval to point at the first's row.
    let (status, _h, rejected) = decide_as(
        &client,
        &base,
        ws,
        &owner_jwt,
        approval,
        false,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{rejected}");
    assert_eq!(
        staged_rows_3787(&su, ws).await,
        0,
        "a rejected proposal's staged image is deleted"
    );

    let (status, one) =
        propose(json!({"source": "generated", "dataBase64": b64_3787(&tiny_png_3787())})).await;
    assert_eq!(status, 200, "{one}");
    let approval_one = proposed_approval_3706(&one);
    let image_one: Uuid =
        sqlx::query_scalar("SELECT id FROM agent_avatar_image WHERE approval_id=$1")
            .bind(approval_one)
            .fetch_one(&su)
            .await
            .unwrap();
    let sha_one: Vec<u8> = sqlx::query_scalar("SELECT sha256 FROM agent_avatar_image WHERE id=$1")
        .bind(image_one)
        .fetch_one(&su)
        .await
        .unwrap();
    let sha_one_hex: String = sha_one.iter().map(|b| format!("{b:02x}")).collect();
    // A second staged image of the same agent, bound to a *different* approval id.
    sqlx::query(
        "UPDATE approval SET payload = jsonb_set(jsonb_set(payload, \
             '{action,args,avatar,imageId}', to_jsonb($2::text)), \
             '{action,pins,avatar,imageId}', to_jsonb($2::text)) WHERE id = $1",
    )
    .bind(approval_one)
    .bind(Uuid::new_v4().to_string())
    .execute(&su)
    .await
    .unwrap();
    let (status, _h, swapped) = decide_as(
        &client,
        &base,
        ws,
        &fixture.human_jwt,
        approval_one,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{swapped}");
    assert_eq!(swapped["status"], "action_args_invalid");
    // Point it back at a REAL staged row that belongs to another approval: stage a
    // second row bound to nothing and re-point args+pins at it.
    let other_image: Uuid = sqlx::query_scalar(
        "INSERT INTO agent_avatar_image (workspace_id, member_id, proposed_by, source, mime, \
            width, height, size_bytes, sha256, bytes) \
         SELECT workspace_id, member_id, proposed_by, source, mime, width, height, size_bytes, \
                sha256, bytes FROM agent_avatar_image WHERE id = $1 RETURNING id",
    )
    .bind(image_one)
    .fetch_one(&su)
    .await
    .unwrap();
    sqlx::query(
        "UPDATE approval SET payload = jsonb_set(jsonb_set(payload, \
             '{action,args,avatar,imageId}', to_jsonb($2::text)), \
             '{action,pins,avatar,imageId}', to_jsonb($2::text)) WHERE id = $1",
    )
    .bind(approval_one)
    .bind(other_image.to_string())
    .execute(&su)
    .await
    .unwrap();
    let (status, _h, swapped) = decide_as(
        &client,
        &base,
        ws,
        &fixture.human_jwt,
        approval_one,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(
        status, 409,
        "an unbound staged row is not this approval's: {swapped}"
    );
    assert_eq!(swapped["status"], "action_args_invalid");
    // Restore and approve for real.
    sqlx::query(
        "UPDATE approval SET payload = jsonb_set(jsonb_set(payload, \
             '{action,args,avatar,imageId}', to_jsonb($2::text)), \
             '{action,pins,avatar,imageId}', to_jsonb($2::text)) WHERE id = $1",
    )
    .bind(approval_one)
    .bind(image_one.to_string())
    .execute(&su)
    .await
    .unwrap();
    sqlx::query("DELETE FROM agent_avatar_image WHERE id=$1")
        .bind(other_image)
        .execute(&su)
        .await
        .unwrap();

    // ---- approve: the server's bytes are what is served --------------------------
    let (status, _h, approved) = decide_as(
        &client,
        &base,
        ws,
        &owner_jwt,
        approval_one,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(approved["result"]["actionId"], "agent.profile.update");
    let url = format!("{base}/v1/workspaces/{ws}/members/{agent}/avatar/content?v={image_one}");
    let served = client
        .get(&url)
        .bearer_auth(&owner_jwt)
        .send()
        .await
        .unwrap();
    assert_eq!(served.status().as_u16(), 200);
    let bytes_one: Vec<u8> = sqlx::query_scalar("SELECT bytes FROM agent_avatar_image WHERE id=$1")
        .bind(image_one)
        .fetch_one(&su)
        .await
        .unwrap();
    assert_eq!(served.bytes().await.unwrap().to_vec(), bytes_one);
    let _ = sha_one_hex;
    let audit: Value = sqlx::query_scalar(
        "SELECT detail FROM audit_log WHERE workspace_id=$1 AND action='agent.avatar.updated' \
          ORDER BY created_at DESC LIMIT 1",
    )
    .bind(ws)
    .fetch_one(&su)
    .await
    .expect("an avatar audit row");
    assert_eq!(audit["origin"], "generated");
    assert!(audit["sha256_prefix"].as_str().unwrap().len() == 12);
    assert!(!audit.to_string().contains("dataBase64"));
    let roster: Value = client
        .get(format!("{base}/v1/workspaces/{ws}/roster"))
        .bearer_auth(&owner_jwt)
        .send()
        .await
        .unwrap()
        .json()
        .await
        .unwrap();
    let members = roster["members"].as_array().or(roster.as_array()).unwrap();
    let me = members
        .iter()
        .find(|m| m["id"] == json!(agent.to_string()))
        .unwrap();
    assert_eq!(
        me["avatarUrl"],
        json!(format!(
            "/v1/workspaces/{ws}/members/{agent}/avatar/content?v={image_one}"
        ))
    );

    // ---- a preset replaces the image; the image row is deleted -------------------
    let (status, preset) = propose(json!({"source": "preset", "presetId": "comet"})).await;
    assert_eq!(status, 200, "{preset}");
    let approval_preset = proposed_approval_3706(&preset);
    let (status, _h, done) = decide_as(
        &client,
        &base,
        ws,
        &owner_jwt,
        approval_preset,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{done}");
    assert_eq!(
        staged_rows_3787(&su, ws).await,
        0,
        "the image row went with the switch"
    );
    let (preset_value, pointer): (Option<String>, Option<Uuid>) = sqlx::query_as(
        "SELECT a.config->>'avatarPreset', m.avatar_image_id FROM member m \
           JOIN agent a ON a.member_id = m.id WHERE m.id=$1",
    )
    .bind(agent)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!((preset_value.as_deref(), pointer), (Some("comet"), None));
    // The same preset again is not a proposal.
    let (status, again) = propose(json!({"source": "preset", "presetId": "comet"})).await;
    assert_eq!(status, 400, "{again}");
    // null removes it.
    let (status, clear) = propose(Value::Null).await;
    assert_eq!(status, 200, "{clear}");
    let approval_clear = proposed_approval_3706(&clear);
    let (status, _h, done) = decide_as(
        &client,
        &base,
        ws,
        &owner_jwt,
        approval_clear,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{done}");
    let preset_value: Option<String> =
        sqlx::query_scalar("SELECT config->>'avatarPreset' FROM agent WHERE member_id=$1")
            .bind(agent)
            .fetch_one(&su)
            .await
            .unwrap();
    assert_eq!(preset_value, None);

    // ---- an overdue proposal's staged image dies with it -------------------------
    let (status, last) =
        propose(json!({"source": "generated", "dataBase64": b64_3787(&tiny_png_3787())})).await;
    assert_eq!(status, 200, "{last}");
    let approval_last = proposed_approval_3706(&last);
    assert_eq!(staged_rows_3787(&su, ws).await, 1);
    sqlx::query("UPDATE approval SET expires_at = now() - interval '1 minute' WHERE id=$1")
        .bind(approval_last)
        .execute(&su)
        .await
        .unwrap();
    let (status, _h, expired) = decide_as(
        &client,
        &base,
        ws,
        &owner_jwt,
        approval_last,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{expired}");
    assert_eq!(expired["status"], "expired");
    assert_eq!(
        staged_rows_3787(&su, ws).await,
        0,
        "an expired proposal's image is deleted"
    );
}

/// **A workspace file as the avatar (source (a)) and the read path that names it.**
/// `oort_conversation_read` shows image attachments only (an id, never the Drive
/// file id); a visible image becomes a staged, re-encoded avatar; everything the
/// agent could not read — a private channel it is not in, a non-image, a pending
/// upload, a deleted message — is the one refusal.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_workspace_image_can_be_the_avatar_only_if_the_agent_could_read_it() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let drive = Arc::new(MemDrive3787::default());
    let base = start_server_with_drive_3787(app.clone(), drive.clone()).await;
    let fixture_channel = fixture.channel;
    let client = reqwest::Client::new();
    let ws = fixture.workspace;
    let agent = fixture.hosted_agent;
    let (owner, _owner_jwt) = seed_human_3708(&su, &fixture, "owner", "member").await;
    set_agent_owner_3708(&su, agent, Some(owner)).await;
    tidy_agent_3708(&su, agent, "Hermes").await;

    let png = tiny_png_3787();
    for id in ["drive-ok", "drive-pending", "drive-hidden", "drive-unbound"] {
        drive.files.lock().unwrap().insert(id.into(), png.clone());
    }
    drive
        .files
        .lock()
        .unwrap()
        .insert("drive-text".into(), b"hello".to_vec());

    // A human message with attachments in the approved channel, and one in the
    // private channel the agent is not part of.
    let message = |channel: Uuid, body: &str| {
        let body = body.to_string();
        let su = su.clone();
        let human = fixture.human;
        async move {
            sqlx::query_scalar::<_, Uuid>(
                "INSERT INTO message (workspace_id, channel_id, author_member_id, seq, body, \
                    client_msg_id, hlc_ts, hlc_count) \
                 SELECT $1, $2, $3, COALESCE(max(seq),0)+1, $4, gen_random_uuid(), 1, 0 \
                   FROM message WHERE channel_id = $2 RETURNING id",
            )
            .bind(ws)
            .bind(channel)
            .bind(human)
            .bind(body)
            .fetch_one(&su)
            .await
            .expect("seed message")
        }
    };
    let visible_msg = message(fixture.channel, "my logo").await;
    let private_msg = message(fixture.private_channel, "secret logo").await;
    // Rows seeded straight into `message` bypass the per-channel counter the REST
    // send reads: bring it up to the highest seq used, or the next real send collides.
    sqlx::query(
        "UPDATE channel_seq SET last_seq = GREATEST(last_seq, \
            (SELECT COALESCE(max(seq), 0) FROM message m WHERE m.channel_id = channel_seq.channel_id)) \
          WHERE workspace_id = $1",
    )
    .bind(ws)
    .execute(&su)
    .await
    .unwrap();
    let attach = |channel: Uuid, msg: Option<Uuid>, drive_id: &str, mime: &str, status: &str| {
        let (su, human, drive_id, mime, status) = (
            su.clone(),
            fixture.human,
            drive_id.to_string(),
            mime.to_string(),
            status.to_string(),
        );
        async move {
            sqlx::query_scalar::<_, Uuid>(
                "INSERT INTO attachment (workspace_id, channel_id, uploader_member_id, message_id, \
                    drive_file_id, name, mime, size_bytes, status) \
                 VALUES ($1,$2,$3,$4,$5,'logo.png',$6,70,$7) RETURNING id",
            )
            .bind(ws)
            .bind(channel)
            .bind(human)
            .bind(msg)
            .bind(drive_id)
            .bind(mime)
            .bind(status)
            .fetch_one(&su)
            .await
            .expect("seed attachment")
        }
    };
    let good = attach(
        fixture.channel,
        Some(visible_msg),
        "drive-ok",
        "image/png",
        "complete",
    )
    .await;
    let text_file = attach(
        fixture.channel,
        Some(visible_msg),
        "drive-text",
        "text/plain",
        "complete",
    )
    .await;
    let pending = attach(
        fixture.channel,
        Some(visible_msg),
        "drive-pending",
        "image/png",
        "pending",
    )
    .await;
    let hidden = attach(
        fixture.private_channel,
        Some(private_msg),
        "drive-hidden",
        "image/png",
        "complete",
    )
    .await;
    let unbound = attach(
        fixture.channel,
        None,
        "drive-unbound",
        "image/png",
        "complete",
    )
    .await;

    // ---- the read path: images only, ids only ------------------------------------
    let (status, read) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_conversation_read",
        json!({"channelId": fixture.channel}),
    )
    .await;
    assert_eq!(status, 200, "{read}");
    let rendered = read.to_string();
    assert!(
        rendered.contains(&good.to_string()),
        "the image attachment id is shown: {rendered}"
    );
    for absent in [text_file, pending, unbound, hidden] {
        assert!(
            !rendered.contains(&absent.to_string()),
            "{absent} must not be shown"
        );
    }
    assert!(
        !rendered.contains("drive-ok") && !rendered.contains("drive-text"),
        "no Drive id"
    );
    assert!(rendered.contains("imageAttachments"));

    // ---- what the agent cannot read is one refusal --------------------------------
    let mut answers = Vec::new();
    for id in [text_file, pending, unbound, hidden, Uuid::new_v4()] {
        let (status, refused) = try_propose_action_3706(
            &client,
            &base,
            &su,
            &fixture,
            "agent.profile.update",
            json!({"avatar": {"source": "attachment", "attachmentId": id.to_string()}}),
        )
        .await;
        answers.push((status, refused["error"].clone()));
        assert_eq!(status, 400, "{id}: {refused}");
    }
    assert!(answers.iter().all(|a| a.1 == answers[0].1), "{answers:?}");
    assert_eq!(staged_rows_3787(&su, ws).await, 0);

    // ---- a deleted message hides its file -----------------------------------------
    sqlx::query("UPDATE message SET state = 'deleted' WHERE id = $1")
        .bind(visible_msg)
        .execute(&su)
        .await
        .unwrap();
    let (status, refused) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.profile.update",
        json!({"avatar": {"source": "attachment", "attachmentId": good.to_string()}}),
    )
    .await;
    assert_eq!(status, 400, "{refused}");
    sqlx::query("UPDATE message SET state = 'sent' WHERE id = $1")
        .bind(visible_msg)
        .execute(&su)
        .await
        .unwrap();

    // ---- the readable image becomes a staged, re-encoded avatar ---------------------
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.profile.update",
        json!({"avatar": {"source": "attachment", "attachmentId": good.to_string()}}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval = proposed_approval_3706(&proposed);
    let (origin, bound, source): (String, Option<Uuid>, String) = sqlx::query_as(
        "SELECT source, approval_id, source FROM agent_avatar_image WHERE approval_id=$1",
    )
    .bind(approval)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(
        (origin.as_str(), bound, source.as_str()),
        ("attachment", Some(approval), "attachment")
    );
    let payload: Value = sqlx::query_scalar("SELECT payload FROM approval WHERE id=$1")
        .bind(approval)
        .fetch_one(&su)
        .await
        .unwrap();
    assert!(
        !payload.to_string().contains(&good.to_string()),
        "the attachment id is not stored"
    );
    assert!(!payload.to_string().contains("drive-ok"));

    // ---- a channel the agent left hides the file even though the row is intact -----
    // (Asked at the database function, not through a mention: an agent that has left
    // the room cannot be mentioned into a run.)
    let visible_before = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move {
            momo_messaging::find_visible_image_attachment_in_tx(
                conn,
                ws,
                agent,
                &[fixture_channel],
                good,
                5 << 20,
            )
            .await
        })
    })
    .await
    .unwrap();
    assert!(
        visible_before.is_some(),
        "control: visible while the agent is a member"
    );
    sqlx::query("UPDATE membership SET left_at = now() WHERE channel_id=$1 AND member_id=$2")
        .bind(fixture.channel)
        .bind(agent)
        .execute(&su)
        .await
        .unwrap();
    let visible_after = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move {
            momo_messaging::find_visible_image_attachment_in_tx(
                conn,
                ws,
                agent,
                &[fixture_channel],
                good,
                5 << 20,
            )
            .await
        })
    })
    .await
    .unwrap();
    assert!(
        visible_after.is_none(),
        "an agent that left the channel cannot use its files"
    );
    // …and a file outside the connection's approved channels is invisible too.
    sqlx::query("UPDATE membership SET left_at = NULL WHERE channel_id=$1 AND member_id=$2")
        .bind(fixture.channel)
        .bind(agent)
        .execute(&su)
        .await
        .unwrap();
    let not_approved = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move {
            momo_messaging::find_visible_image_attachment_in_tx(
                conn,
                ws,
                agent,
                &[Uuid::new_v4()],
                good,
                5 << 20,
            )
            .await
        })
    })
    .await
    .unwrap();
    assert!(
        not_approved.is_none(),
        "an unapproved channel hides its files"
    );
    // …and a half tombstone (only `deleted_at` written, `state` untouched) hides it too: ADR-0151
    // amendment 2 D1 reads both columns. Restored before the assertion so a failure leaves no mark.
    sqlx::query(
        "UPDATE message SET deleted_at = now() \
          WHERE id = (SELECT message_id FROM attachment WHERE id = $1)",
    )
    .bind(good)
    .execute(&su)
    .await
    .unwrap();
    let half_tombstone = tenant_3786(&app, ws, move |conn| {
        Box::pin(async move {
            momo_messaging::find_visible_image_attachment_in_tx(
                conn,
                ws,
                agent,
                &[fixture_channel],
                good,
                5 << 20,
            )
            .await
        })
    })
    .await
    .unwrap();
    sqlx::query(
        "UPDATE message SET deleted_at = NULL \
          WHERE id = (SELECT message_id FROM attachment WHERE id = $1)",
    )
    .bind(good)
    .execute(&su)
    .await
    .unwrap();
    assert!(
        half_tombstone.is_none(),
        "a message with only deleted_at set hides its file from the agent"
    );
}

async fn agent_invite_state_3788(
    su: &PgPool,
    workspace: Uuid,
    handle: &str,
) -> Option<(Uuid, Uuid, bool, String)> {
    sqlx::query_as::<_, (Uuid, Uuid, bool, String)>(
        "SELECT m.id, a.owner_human_id, ap.paused, hc.status::text \
           FROM member m \
           JOIN agent a ON a.member_id = m.id AND a.workspace_id = m.workspace_id \
           JOIN agent_profile ap ON ap.agent_member_id = m.id AND ap.workspace_id = m.workspace_id \
           JOIN hosted_agent_connection hc ON hc.agent_member_id = m.id \
            AND hc.workspace_id = m.workspace_id \
          WHERE m.workspace_id = $1 AND m.handle = $2 AND m.kind = 'agent'",
    )
    .bind(workspace)
    .bind(handle)
    .fetch_optional(su)
    .await
    .expect("read the invited agent")
}

async fn connection_count_3788(su: &PgPool, workspace: Uuid) -> i64 {
    sqlx::query_scalar("SELECT count(*) FROM hosted_agent_connection WHERE workspace_id=$1")
        .bind(workspace)
        .fetch_one(su)
        .await
        .unwrap()
}

async fn member_count_3788(su: &PgPool, workspace: Uuid) -> i64 {
    sqlx::query_scalar("SELECT count(*) FROM member WHERE workspace_id=$1")
        .bind(workspace)
        .fetch_one(su)
        .await
        .unwrap()
}

/// **agent.invite (증보 v3 V3-3, #3788), end to end.** Hostile spellings are one
/// refusal and create nothing; a non-admin decider is `role_required` and nothing
/// exists; the admin's approval creates the member, agent, paused profile and a
/// `pairing_pending` connection in one transaction, the approver is the owner, the
/// pairing code is in the response alone (`no-store`) and in no durable store, and
/// a replay does not show it again. (The approver\'s hand-over choice is the next
/// test.)
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn an_approved_agent_invite_creates_the_agent_for_the_approver_and_shows_the_code_once() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (_plain, plain_jwt) = seed_human_3708(&su, &fixture, "plain", "member").await;

    // ---- hostile spellings: one refusal, nothing written --------------------
    let taken_handle = tidy_agent_3708(&su, fixture.managed_agent, "Taken Bot").await;
    sqlx::query(
        "INSERT INTO member(id, workspace_id, kind, display_name, handle, deleted_at) \
         VALUES($1,$2,'human','Gone Ghost','ghost-handle', now())",
    )
    .bind(Uuid::new_v4())
    .bind(fixture.workspace)
    .execute(&su)
    .await
    .unwrap();
    let members_before = member_count_3788(&su, fixture.workspace).await;
    let mut answers = Vec::new();
    for hostile in [
        json!({"platform": "grok_bot", "displayName": "Muse Writer", "handle": "muse-writer", "ownerOnly": true}),
        json!({"platform": "grok_bot", "displayName": "Muse Writer", "handle": "muse-writer", "channels": ["x"]}),
        json!({"platform": "grok_bot", "displayName": "Muse Writer", "handle": "muse-writer", "scopes": ["workspace:propose"]}),
        json!({"platform": "grok_bot", "displayName": "Muse Writer", "handle": "muse-writer", "ownerHumanId": Uuid::new_v4()}),
        json!({"platform": "skynet", "displayName": "Muse Writer", "handle": "muse-writer"}),
        json!({"displayName": "Muse Writer", "handle": "muse-writer"}),
        json!({"platform": "muse", "handle": "muse-writer"}),
        json!({"platform": "muse", "displayName": "Muse Writer"}),
        json!({"platform": "muse", "displayName": "see https://evil.example", "handle": "muse-writer"}),
        json!({"platform": "muse", "displayName": "[docs](http://evil.example)", "handle": "muse-writer"}),
        json!({"platform": "muse", "displayName": "zero\u{200B}width", "handle": "muse-writer"}),
        json!({"platform": "muse", "displayName": "Admin", "handle": "muse-writer"}),
        json!({"platform": "muse", "displayName": "Muse Writer", "handle": "x"}),
        json!({"platform": "muse", "displayName": "Muse Writer", "handle": "Bad Handle!"}),
        json!({"platform": "muse", "displayName": "Muse Writer", "handle": taken_handle}),
        json!({"platform": "muse", "displayName": "Person plain", "handle": "muse-writer"}),
        // Review of #3801: the handle is spoken as @handle, so it gets the reserved
        // words, the mention-overlap rule and the deleted members' handles too.
        json!({"platform": "muse", "displayName": "Muse Writer", "handle": "admin"}),
        json!({"platform": "muse", "displayName": "Muse Writer", "handle": "everyone"}),
        json!({"platform": "muse", "displayName": "Muse Writer", "handle": "ghost-handle"}),
        json!({"platform": "muse", "displayName": "Muse Writer", "handle": "person"}),
        json!({}),
    ] {
        let (status, refused) = try_propose_action_3706(
            &client,
            &base,
            &su,
            &fixture,
            "agent.invite",
            hostile.clone(),
        )
        .await;
        answers.push((status, refused["error"].clone()));
        assert_eq!(status, 400, "{hostile} must be refused: {refused}");
    }
    assert!(answers.iter().all(|a| a.1 == answers[0].1), "{answers:?}");
    assert_eq!(
        member_count_3788(&su, fixture.workspace).await,
        members_before
    );

    // A banned handle is refused at the proposal too.
    sqlx::query(
        "INSERT INTO workspace_ban(workspace_id, handle_norm, created_by) VALUES($1,'banned-bot',$2)",
    )
    .bind(fixture.workspace)
    .bind(fixture.human)
    .execute(&su)
    .await
    .unwrap();
    let (status, refused) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.invite",
        json!({"platform": "dots", "displayName": "Banned Bot", "handle": "banned-bot"}),
    )
    .await;
    assert_eq!(status, 400, "{refused}");

    // ---- a good proposal: the card says what approving does -----------------
    let good = json!({"platform": "muse", "displayName": "Muse Writer", "handle": "muse-writer"});
    let (status, proposed) =
        try_propose_action_3706(&client, &base, &su, &fixture, "agent.invite", good.clone()).await;
    assert_eq!(status, 200, "{proposed}");
    let approval = proposed_approval_3706(&proposed);
    let card: Value = sqlx::query_scalar("SELECT props FROM message WHERE id=$1")
        .bind(Uuid::parse_str(structured(&proposed)["cardMessageId"].as_str().unwrap()).unwrap())
        .fetch_one(&su)
        .await
        .unwrap();
    assert_eq!(card["action"]["id"], json!("agent.invite"));
    assert_eq!(card["action"]["required_role"], json!("admin"));
    let rows = card["action"]["rows"].as_array().unwrap().clone();
    let row = |label: &str| {
        rows.iter()
            .find(|r| r["label"] == label)
            .unwrap_or_else(|| panic!("{label} in {rows:?}"))["value"]
            .as_str()
            .unwrap()
            .to_string()
    };
    assert_eq!(row("플랫폼"), "Muse");
    assert!(
        row("새 에이전트").contains("Muse Writer") && row("새 에이전트").contains("muse-writer")
    );
    assert_eq!(row("소유자"), "승인한 사람");
    assert_eq!(
        member_count_3788(&su, fixture.workspace).await,
        members_before,
        "proposing creates nobody"
    );

    // ---- a non-admin is refused; nothing exists -----------------------------
    let (status, _h, refused) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &plain_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 403, "{refused}");
    assert_eq!(refused["status"], "role_required");
    assert_eq!(approval_status_3708(&su, approval).await, "pending");
    assert!(
        agent_invite_state_3788(&su, fixture.workspace, "muse-writer")
            .await
            .is_none()
    );

    // ---- the admin approves --------------------------------------------------
    let decision_id = Uuid::new_v4();
    let (status, headers, approved) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval,
        true,
        decision_id,
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(approved["result"]["actionId"], json!("agent.invite"));
    assert_eq!(
        headers
            .get("cache-control")
            .and_then(|v| v.to_str().ok())
            .unwrap_or(""),
        "no-store"
    );
    let secret = &approved["result"]["secretOnce"];
    assert_eq!(secret["kind"], json!("pairing_credential"), "{approved}");
    let pairing = secret["value"].as_str().expect("the code").to_string();
    assert!(pairing.len() >= 20, "a real credential");
    let (new_agent, owner, paused, connection) =
        agent_invite_state_3788(&su, fixture.workspace, "muse-writer")
            .await
            .expect("the agent exists");
    assert_eq!(owner, fixture.human, "the approver owns it");
    assert!(paused, "born paused");
    assert_eq!(connection, "pairing_pending");
    assert_eq!(
        member_count_3788(&su, fixture.workspace).await,
        members_before + 1
    );
    assert_eq!(
        approved["result"]["ref"]["id"],
        json!(new_agent.to_string())
    );

    // The code is in no durable store.
    let durable = durable_text(&su, fixture.workspace).await;
    assert!(!durable.contains(&pairing), "pairing code leaked");
    let audit: Value = sqlx::query_scalar(
        "SELECT detail FROM audit_log WHERE workspace_id=$1 AND action='agent.invited'",
    )
    .bind(fixture.workspace)
    .fetch_one(&su)
    .await
    .expect("the invite audit row");
    assert_eq!(audit["via_agent"], json!(fixture.hosted_agent.to_string()));
    assert_eq!(audit["approval_id"], json!(approval.to_string()));
    assert_eq!(audit["platform"], json!("muse"));
    assert!(!audit.to_string().contains(&pairing));

    // A replay answers the same receipt without the code.
    let (status, _h, replay) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval,
        true,
        decision_id,
    )
    .await;
    assert_eq!(status, 200, "{replay}");
    assert!(replay["result"].get("secretOnce").is_none(), "{replay}");
    assert_eq!(
        member_count_3788(&su, fixture.workspace).await,
        members_before + 1
    );
}

/// A handle that became unavailable between the card and the decision (here a
/// *deleted* member still holds it, which the roster check does not see) refuses
/// the decision as stale with **nothing written** — no member, no connection — and
/// the approval stays pending.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn an_agent_invite_whose_handle_was_taken_meanwhile_creates_nothing() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (status, proposed) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "agent.invite",
        json!({"platform": "dots", "displayName": "Dots Helper", "handle": "dots-helper"}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    let approval = proposed_approval_3706(&proposed);
    let members_before = member_count_3788(&su, fixture.workspace).await;
    let connections_before = connection_count_3788(&su, fixture.workspace).await;
    let ghost = Uuid::new_v4();
    sqlx::query(
        "INSERT INTO member(id, workspace_id, kind, display_name, handle, deleted_at) \
         VALUES($1,$2,'human','Gone','dots-helper', now())",
    )
    .bind(ghost)
    .bind(fixture.workspace)
    .execute(&su)
    .await
    .unwrap();
    let (status, _h, refused) = decide_as(
        &client,
        &base,
        fixture.workspace,
        &fixture.human_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{refused}");
    assert_eq!(refused["status"], "action_args_invalid");
    assert_eq!(approval_status_3708(&su, approval).await, "pending");
    assert_eq!(
        member_count_3788(&su, fixture.workspace).await,
        members_before + 1,
        "only the ghost row the test added"
    );
    let connections_after = connection_count_3788(&su, fixture.workspace).await;
    assert_eq!(
        connections_after, connections_before,
        "no connection was made"
    );
}

async fn decide_with_flag_3789(
    client: &reqwest::Client,
    base: &str,
    fixture: &Fixture,
    approval: Uuid,
    approve: bool,
    deliver: bool,
) -> (u16, Value) {
    let response = client
        .post(format!(
            "{base}/v1/workspaces/{}/approvals/{approval}/decision",
            fixture.workspace
        ))
        .bearer_auth(&fixture.human_jwt)
        .json(&json!({
            "approvalId": approval, "approve": approve,
            "clientDecisionId": Uuid::new_v4(), "deliverSecretToAgent": deliver
        }))
        .send()
        .await
        .unwrap();
    (
        response.status().as_u16(),
        response.json::<Value>().await.unwrap_or(Value::Null),
    )
}

async fn claim_3789(
    client: &reqwest::Client,
    base: &str,
    fixture: &Fixture,
    approval: Uuid,
) -> (u16, Value) {
    call(
        client,
        base,
        &fixture.hosted_bearer,
        "oort_action_claim_secret",
        json!({"handle": handle_of_3789(approval), "approvalId": approval}),
    )
    .await
}

async fn pairing_hash_3789(su: &PgPool, workspace: Uuid, handle: &str) -> Vec<u8> {
    sqlx::query_scalar(
        "SELECT hc.pairing_challenge_hash FROM hosted_agent_connection hc \
           JOIN member m ON m.id = hc.agent_member_id AND m.workspace_id = hc.workspace_id \
          WHERE hc.workspace_id=$1 AND m.handle=$2",
    )
    .bind(workspace)
    .bind(handle)
    .fetch_one(su)
    .await
    .expect("the pairing hash")
}

async fn propose_invite_agent_3789(
    client: &reqwest::Client,
    base: &str,
    su: &PgPool,
    fixture: &Fixture,
    name: &str,
    handle: &str,
) -> Uuid {
    let (status, proposed) = try_propose_action_3706(
        client,
        base,
        su,
        fixture,
        "agent.invite",
        json!({"platform": "other", "displayName": name, "handle": handle}),
    )
    .await;
    assert_eq!(status, 200, "{proposed}");
    proposed_approval_3706(&proposed)
}

/// **The claim call for `agent.invite` (ADR-0186 증보 v3 V3-3a/V3-4, #3789).** The
/// approver\'s checkbox decides who sees the pairing code: unchecked, the approver
/// alone (`secretOnce`); checked, the proposing agent alone, once, within 30
/// minutes, minted at the claim (the hash on the connection changes, so whatever
/// existed before is dead). Every other caller or state is the one `unavailable`.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn an_agent_receives_a_pairing_code_only_when_the_approver_chose_to_hand_it_over() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();

    // ---- checked: no secretOnce, then one claim -----------------------------
    let a = propose_invite_agent_3789(
        &client,
        &base,
        &su,
        &fixture,
        "Alpha Scribe",
        "alpha-scribe",
    )
    .await;
    let (status, _) = claim_3789(&client, &base, &fixture, a).await;
    assert_eq!(status, 409, "a pending approval grants nothing");
    let (status, approved) = decide_with_flag_3789(&client, &base, &fixture, a, true, true).await;
    assert_eq!(status, 200, "{approved}");
    assert!(approved["result"].get("secretOnce").is_none(), "{approved}");
    let before = pairing_hash_3789(&su, fixture.workspace, "alpha-scribe").await;
    let grant: Value =
        sqlx::query_scalar("SELECT payload->'secretClaim' FROM approval WHERE id=$1")
            .bind(a)
            .fetch_one(&su)
            .await
            .unwrap();
    assert_eq!(grant["allowed"], json!(true));
    assert_eq!(grant["kind"], json!("pairing"));
    assert!(grant.get("claimedAtMs").is_none());
    let result_rows: Value = sqlx::query_scalar(
        "SELECT props->'result'->'rows' FROM message \
          WHERE workspace_id=$1 AND type='approval_request' AND props->'result'->>'status'='executed' ORDER BY seq DESC LIMIT 1",
    )
    .bind(fixture.workspace)
    .fetch_one(&su)
    .await
    .unwrap();
    assert!(
        result_rows
            .as_array()
            .unwrap()
            .contains(&json!({"label": "연결 코드", "value": "에이전트가 받아요"})),
        "{result_rows}"
    );
    let (status, claimed) = claim_3789(&client, &base, &fixture, a).await;
    assert_eq!(status, 200, "{claimed}");
    let received = structured(&claimed);
    assert_eq!(received["actionId"], json!("agent.invite"));
    assert_eq!(received["kind"], json!("pairing"));
    let pairing = received["value"].as_str().expect("the code").to_string();
    assert!(received["expiresAtMs"].as_i64().unwrap() > 0);
    let after = pairing_hash_3789(&su, fixture.workspace, "alpha-scribe").await;
    assert_ne!(
        before, after,
        "minted at the claim: the earlier value is dead"
    );
    let matches: bool = sqlx::query_scalar("SELECT $1::bytea = digest($2::text, 'sha256')")
        .bind(&after)
        .bind(&pairing)
        .fetch_one(&su)
        .await
        .unwrap();
    assert!(
        matches,
        "the claimed code is the one the connection now holds"
    );
    assert!(!durable_text(&su, fixture.workspace)
        .await
        .contains(&pairing));
    let (status, again) = claim_3789(&client, &base, &fixture, a).await;
    assert_eq!((status, error_code(&again)), (409, -32006), "{again}");
    let audit: Vec<Value> = sqlx::query_scalar(
        "SELECT detail FROM audit_log WHERE workspace_id=$1 AND action='agent.secret.claimed'",
    )
    .bind(fixture.workspace)
    .fetch_all(&su)
    .await
    .unwrap();
    assert_eq!(audit.len(), 1);
    assert_eq!(audit[0]["kind"], json!("pairing"));
    assert!(!audit[0].to_string().contains(&pairing));

    // ---- unchecked: the approver sees it, the agent gets nothing -------------
    let b = propose_invite_agent_3789(&client, &base, &su, &fixture, "Bravo Clerk", "bravo-clerk")
        .await;
    let (status, approved) = decide_with_flag_3789(&client, &base, &fixture, b, true, false).await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(
        approved["result"]["secretOnce"]["kind"],
        json!("pairing_credential")
    );
    let (status, refused) = claim_3789(&client, &base, &fixture, b).await;
    let unknown = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_action_claim_secret",
        json!({"handle": handle_of_3789(b), "approvalId": Uuid::new_v4()}),
    )
    .await;
    assert_eq!((status, error_code(&refused)), (409, -32004), "{refused}");
    assert_eq!(
        (unknown.0, error_code(&unknown.1)),
        (409, -32004),
        "an approval that does not exist answers the same"
    );

    // ---- rejected: nothing to claim ------------------------------------------
    let d = propose_invite_agent_3789(
        &client,
        &base,
        &su,
        &fixture,
        "Delta Auditor",
        "delta-auditor",
    )
    .await;
    let (status, _) = decide_with_flag_3789(&client, &base, &fixture, d, false, false).await;
    assert_eq!(status, 200);
    let (status, refused) = claim_3789(&client, &base, &fixture, d).await;
    assert_eq!((status, error_code(&refused)), (409, -32004), "{refused}");

    // ---- past the 30 minutes: the value never leaves --------------------------
    let e =
        propose_invite_agent_3789(&client, &base, &su, &fixture, "Echo Pilot", "echo-pilot").await;
    let (status, _) = decide_with_flag_3789(&client, &base, &fixture, e, true, true).await;
    assert_eq!(status, 200);
    sqlx::query(
        "UPDATE approval SET payload = jsonb_set(payload, '{secretClaim,deadlineMs}', '1') WHERE id=$1",
    )
    .bind(e)
    .execute(&su)
    .await
    .unwrap();
    let before = pairing_hash_3789(&su, fixture.workspace, "echo-pilot").await;
    let (status, late) = claim_3789(&client, &base, &fixture, e).await;
    assert_eq!((status, error_code(&late)), (409, -32007), "{late}");
    assert_eq!(
        before,
        pairing_hash_3789(&su, fixture.workspace, "echo-pilot").await,
        "a refused claim mints nothing"
    );

    // ---- somebody else\'s approval is the same \'unavailable\' --------------------
    let f = propose_invite_agent_3789(
        &client,
        &base,
        &su,
        &fixture,
        "Foxtrot Mapper",
        "foxtrot-mapper",
    )
    .await;
    let (status, _) = decide_with_flag_3789(&client, &base, &fixture, f, true, true).await;
    assert_eq!(status, 200);
    sqlx::query("UPDATE approval SET requested_by=$2 WHERE id=$1")
        .bind(f)
        .bind(fixture.managed_agent)
        .execute(&su)
        .await
        .unwrap();
    let (status, other) = claim_3789(&client, &base, &fixture, f).await;
    assert_eq!((status, error_code(&other)), (409, -32004), "{other}");

    // ---- two claims at once: exactly one wins --------------------------------
    let g = propose_invite_agent_3789(
        &client,
        &base,
        &su,
        &fixture,
        "Golf Courier",
        "golf-courier",
    )
    .await;
    let (status, _) = decide_with_flag_3789(&client, &base, &fixture, g, true, true).await;
    assert_eq!(status, 200);
    let (one, two) = tokio::join!(
        claim_3789(&client, &base, &fixture, g),
        claim_3789(&client, &base, &fixture, g)
    );
    let mut outcomes = vec![
        (one.0, if one.0 == 200 { 0 } else { error_code(&one.1) }),
        (two.0, if two.0 == 200 { 0 } else { error_code(&two.1) }),
    ];
    outcomes.sort();
    assert_eq!(outcomes, vec![(200, 0), (409, -32006)], "{one:?} {two:?}");

    // ---- malformed ids -------------------------------------------------------
    let (status, bad) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_action_claim_secret",
        json!({"handle": handle_of_3789(g), "approvalId": "nope"}),
    )
    .await;
    assert_eq!(status, 400, "{bad}");
    // A handle that is not a sealed lease handle of this connection is refused
    // before the approval is even looked up.
    let (status, forged) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_action_claim_secret",
        json!({"handle": "forged", "approvalId": g}),
    )
    .await;
    assert_eq!((status, error_code(&forged)), (403, -32003), "{forged}");
}

/// `invite.create` over the claim (V3-5): the approver is not shown a link; a
/// revoked invite cannot be claimed; the replacement keeps the card\'s ceilings.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_revoked_invite_cannot_be_claimed_and_a_flag_on_an_invite_is_refused() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let (approval, _card) = propose_invite(
        &client,
        &base,
        &su,
        &fixture,
        json!({"role": "admin", "maxUses": 3, "expiresInDays": 10}),
    )
    .await;
    // The hand-over box is `agent.invite`\'s; asking on an invite is refused.
    let (status, refused) =
        decide_with_flag_3789(&client, &base, &fixture, approval, true, true).await;
    assert_eq!(status, 400, "{refused}");
    let (status, approved) =
        decide_with_flag_3789(&client, &base, &fixture, approval, true, false).await;
    assert_eq!(status, 200, "{approved}");
    assert!(approved["result"].get("secretOnce").is_none());
    // The approver changed their mind.
    sqlx::query(
        "UPDATE invite_code SET revoked_at = now(), revoked_by = created_by, \
                revocation_reason = 'revoked' WHERE workspace_id=$1 AND id = $2",
    )
    .bind(fixture.workspace)
    .bind(Uuid::parse_str(approved["result"]["ref"]["id"].as_str().unwrap()).unwrap())
    .execute(&su)
    .await
    .unwrap();
    let (status, refused) = claim_3789(&client, &base, &fixture, approval).await;
    assert_eq!((status, error_code(&refused)), (409, -32004), "{refused}");
    let live: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM invite_code WHERE workspace_id=$1 AND revoked_at IS NULL",
    )
    .bind(fixture.workspace)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(live, 0, "nothing was minted for a revoked invite");

    // An approver who is no longer an admin when the claim arrives has no link
    // minted in their name (I2 review M2).
    let (second, _card) =
        propose_invite(&client, &base, &su, &fixture, json!({"role": "admin"})).await;
    let (status, approved) =
        decide_with_flag_3789(&client, &base, &fixture, second, true, false).await;
    assert_eq!(status, 200, "{approved}");
    sqlx::query(
        "UPDATE workspace_membership SET role='member' WHERE workspace_id=$1 AND member_id=$2",
    )
    .bind(fixture.workspace)
    .bind(fixture.human)
    .execute(&su)
    .await
    .unwrap();
    let (status, refused) = claim_3789(&client, &base, &fixture, second).await;
    assert_eq!((status, error_code(&refused)), (409, -32004), "{refused}");
    sqlx::query(
        "UPDATE workspace_membership SET role='owner' WHERE workspace_id=$1 AND member_id=$2",
    )
    .bind(fixture.workspace)
    .bind(fixture.human)
    .execute(&su)
    .await
    .unwrap();
    let (status, ok) = claim_3789(&client, &base, &fixture, second).await;
    assert_eq!(status, 200, "restored authority claims fine: {ok}");
}

/// ADR-0201 acceptance: a card the **team AI** raised is decided by the very same
/// route and executes with the **approver's** authority.
///
/// The proposal goes through `momo_workspace_actions::team_ai::propose_in_tx` (the function the
/// worker calls); the decision is the real HTTP route. What this proves that the
/// worker suite cannot: the extra `via_ai` key in the payload does not trip the
/// decision, the role gate still refuses a plain member (403 `role_required`, the
/// approval intact), an agent still cannot decide, and an admin's approval
/// creates the channel as *that admin* — the team AI never held the authority.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_team_ai_card_is_executed_by_the_approver_and_by_nobody_else() {
    use momo_workspace_actions::team_ai::{self, ProposalContext, ViaAi};

    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let plain_jwt = seed_plain_member(&su, &fixture).await;
    let (workspace, human, channel) = (fixture.workspace, fixture.human, fixture.channel);

    // The team AI, provisioned by the shipped function, seated in the channel.
    let team_ai_id = momo_db::with_tenant_tx(&su, workspace, move |conn| {
        Box::pin(async move { team_ai::enable_in_tx(conn, workspace, human).await })
    })
    .await
    .expect("enable");
    sqlx::query("INSERT INTO membership (workspace_id, channel_id, member_id) VALUES ($1,$2,$3)")
        .bind(workspace)
        .bind(channel)
        .bind(team_ai_id)
        .execute(&su)
        .await
        .unwrap();

    // The admin asks; a run is raised for the team AI.
    let name = format!("ta-{}", &Uuid::new_v4().simple().to_string()[..8]);
    let run_id = momo_db::with_tenant_tx(&su, workspace, move |conn| {
        Box::pin(async move {
            let sent = momo_messaging::send_message_in_tx(
                conn,
                workspace,
                momo_messaging::NewMessage::text(channel, human, "@oort-helper 채널 만들어줘".to_string()),
            )
            .await?;
            let created = momo_agent::create_agent_run_in_tx(
                conn,
                workspace,
                momo_agent::NewAgentRun {
                    channel_id: channel,
                    trigger: momo_agent::RunTrigger::Mention {
                        message_id: sent.message.id,
                        agent_member_id: team_ai_id,
                    },
                    parent_run_id: None,
                    max_steps: 50,
                    depth: 0,
                    input: json!({"schema": "momo.agent_run.input.v0", "surface": "mention", "prompt": "x", "depth": 0}),
                },
            )
            .await?;
            Ok(created.id)
        })
    })
    .await
    .unwrap();
    let args = json!({"name": name, "kind": "public"});
    let proposed = {
        let args = args.clone();
        momo_db::with_tenant_tx(&su, workspace, move |conn| {
            let args = args.clone();
            Box::pin(async move {
                let context = ProposalContext {
                    workspace_id: workspace,
                    run_id,
                    channel_id: channel,
                    agent_member_id: team_ai_id,
                    trigger_message_id: None,
                    now_ms: chrono::Utc::now().timestamp_millis(),
                    expires_at: chrono::Utc::now() + chrono::Duration::minutes(30),
                    via: ViaAi {
                        model: "m".into(),
                        latency_ms: 1,
                        prompt_tokens: 1,
                        completion_tokens: 1,
                        tools: Vec::new(),
                        model_calls: 1,
                        web_searches: 0,
                    },
                };
                team_ai::propose_in_tx(conn, &context, "channel.create", &args, None).await
            })
        })
        .await
        .expect("propose tx")
        .expect("a card")
    };
    let approval_id = proposed.approval_id;
    assert!(
        channel_row_3706(&su, workspace, &name).await.is_none(),
        "a proposal executes nothing"
    );

    // A plain member cannot decide it.
    let (status, _h, refused) = decide_as(
        &client,
        &base,
        workspace,
        &plain_jwt,
        approval_id,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 403, "{refused}");
    assert_eq!(refused["status"], "role_required");
    assert!(channel_row_3706(&su, workspace, &name).await.is_none());

    // The team AI cannot decide its own card (an agent bearer is not a human).
    let agent_bearer = raw_credential(workspace);
    let agent_try = client
        .post(format!("{base}/v1/workspaces/{workspace}/approvals/{approval_id}/decision"))
        .bearer_auth(&agent_bearer)
        .json(&json!({"approvalId": approval_id, "approve": true, "clientDecisionId": Uuid::new_v4()}))
        .send()
        .await
        .unwrap();
    assert!(
        matches!(agent_try.status().as_u16(), 401 | 403),
        "an agent cannot decide"
    );
    assert!(channel_row_3706(&su, workspace, &name).await.is_none());

    // The admin approves: the channel exists, made by the admin.
    let (status, _h, decided) = decide_as(
        &client,
        &base,
        workspace,
        &fixture.human_jwt,
        approval_id,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{decided}");
    let (_, kind, created_by) = channel_row_3706(&su, workspace, &name)
        .await
        .expect("the channel now exists");
    assert_eq!(kind, "public");
    assert_eq!(
        created_by, human,
        "executed with the APPROVER's authority, not the team AI's"
    );
    assert_ne!(created_by, team_ai_id);
}

/// ADR-0201 D8: the operator's switch provisions the team AI in the same
/// transaction, a plain member cannot flip it, the member id is not writable, and
/// "off" pauses the member instead of deleting it.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn the_team_ai_switch_provisions_pauses_and_cannot_be_forged() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let plain_jwt = seed_plain_member(&su, &fixture).await;
    let url = format!("{base}/v1/workspaces/{}/settings", fixture.workspace);
    let patch = |jwt: String, body: Value| {
        let (client, url) = (client.clone(), url.clone());
        async move {
            let response = client
                .patch(url)
                .bearer_auth(jwt)
                .json(&body)
                .send()
                .await
                .unwrap();
            (
                response.status().as_u16(),
                response.json::<Value>().await.unwrap_or(Value::Null),
            )
        }
    };

    let (status, _) = patch(plain_jwt.clone(), json!({"team_ai_fast_path": true})).await;
    assert!(
        matches!(status, 401 | 403),
        "a plain member cannot flip it: {status}"
    );
    let none: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM member WHERE workspace_id=$1 AND handle='oort-helper'",
    )
    .bind(fixture.workspace)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(none, 0);

    // The member id cannot be written by hand, and the flag must be a bool.
    let (status, _) = patch(
        fixture.human_jwt.clone(),
        json!({"team_ai_agent_member_id": Uuid::new_v4()}),
    )
    .await;
    assert_eq!(status, 400, "the nominee is server-written only");
    let (status, _) = patch(
        fixture.human_jwt.clone(),
        json!({"team_ai_fast_path": "yes"}),
    )
    .await;
    assert_eq!(status, 400);

    let (status, body) = patch(
        fixture.human_jwt.clone(),
        json!({"team_ai_fast_path": true}),
    )
    .await;
    assert_eq!(status, 200, "{body}");
    assert_eq!(body["team_ai_fast_path"], true);
    let member =
        Uuid::parse_str(body["team_ai_agent_member_id"].as_str().expect("member id")).unwrap();
    let (kind, owner): (String, Uuid) = sqlx::query_as(
        "SELECT m.kind::text, a.owner_human_id FROM member m JOIN agent a ON a.member_id=m.id WHERE m.id=$1",
    ).bind(member).fetch_one(&su).await.unwrap();
    assert_eq!(
        (kind.as_str(), owner),
        ("agent", fixture.human),
        "a first-class agent member owned by the operator"
    );
    let (paused, tools): (bool, Value) =
        sqlx::query_as("SELECT paused, enabled_tools FROM agent_profile WHERE agent_member_id=$1")
            .bind(member)
            .fetch_one(&su)
            .await
            .unwrap();
    assert!(!paused);
    assert_eq!(tools, json!(["workspace_action_propose"]));

    // Off pauses; on again reuses the same member.
    let (status, body) = patch(
        fixture.human_jwt.clone(),
        json!({"team_ai_fast_path": false}),
    )
    .await;
    assert_eq!(status, 200, "{body}");
    let paused: bool =
        sqlx::query_scalar("SELECT paused FROM agent_profile WHERE agent_member_id=$1")
            .bind(member)
            .fetch_one(&su)
            .await
            .unwrap();
    assert!(paused, "off pauses, it does not delete");
    let (_, body) = patch(
        fixture.human_jwt.clone(),
        json!({"team_ai_fast_path": true}),
    )
    .await;
    assert_eq!(body["team_ai_agent_member_id"], member.to_string());

    // `null` deletes the key, which means off: it must pause, not leave a live
    // member behind a switch that reads as unset.
    let (status, _) = patch(
        fixture.human_jwt.clone(),
        json!({"team_ai_fast_path": null}),
    )
    .await;
    assert_eq!(status, 200);
    let paused: bool =
        sqlx::query_scalar("SELECT paused FROM agent_profile WHERE agent_member_id=$1")
            .bind(member)
            .fetch_one(&su)
            .await
            .unwrap();
    assert!(paused, "null switches the team AI off");
}

// ---------------------------------------------------------------------------
// (#3831, ADR-0162 증보 4) oort_job_start — claim + start report + conversation
// ---------------------------------------------------------------------------

/// A human mentions the hosted agent in the approved channel; returns the run id.
async fn raise_mention_3831(
    client: &reqwest::Client,
    base: &str,
    su: &PgPool,
    fixture: &Fixture,
    text: &str,
) -> Uuid {
    let handle_name = hosted_handle(su, fixture.hosted_agent).await;
    let trigger: Value = client
        .post(format!(
            "{base}/v1/workspaces/{}/channels/{}/messages",
            fixture.workspace, fixture.channel
        ))
        .bearer_auth(&fixture.human_jwt)
        .json(&json!({
            "clientMsgId": Uuid::new_v4(),
            "body": format!("@{handle_name} {text}")
        }))
        .send()
        .await
        .expect("mention send")
        .json()
        .await
        .expect("mention body");
    assert!(trigger["id"].is_string(), "{trigger}");
    sqlx::query_scalar(
        "SELECT id FROM agent_run WHERE workspace_id=$1 AND agent_member_id=$2 \
          ORDER BY created_at DESC LIMIT 1",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_agent)
    .fetch_one(su)
    .await
    .expect("the run the mention raised")
}

async fn set_approved_scopes_3831(su: &PgPool, fixture: &Fixture, scopes: &[&str]) {
    let scopes: Vec<String> = scopes.iter().map(|scope| (*scope).to_string()).collect();
    sqlx::query(
        "UPDATE hosted_agent_connection SET approved_scopes = $3 \
         WHERE workspace_id=$1 AND id=$2",
    )
    .bind(fixture.workspace)
    .bind(fixture.hosted_connection)
    .bind(scopes)
    .execute(su)
    .await
    .unwrap();
}

async fn lease_owner_3831(su: &PgPool, run: Uuid) -> Option<Uuid> {
    sqlx::query_scalar(
        "SELECT lease_owner FROM outbox WHERE kind='agent_job' \
           AND lower(payload->>'run_id') = lower($1::text)",
    )
    .bind(run.to_string())
    .fetch_one(su)
    .await
    .expect("the run's job row")
}

const ALL_HOSTED_SCOPES_3831: [&str; 7] = [
    "agent:port:connect",
    "agent:inbox:read",
    "messages:read",
    "messages:write",
    "agent:jobs:read",
    "agent:runs:callback",
    "workspace:propose",
];

#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn one_job_start_call_claims_reports_the_start_and_returns_the_conversation() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let run = raise_mention_3831(&client, &base, &su, &fixture, "작업해줘 3831").await;

    let (status, started) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_job_start",
        json!({}),
    )
    .await;
    assert_eq!(status, 200, "{started}");
    let answer = structured(&started);
    assert_eq!(answer["started"], json!(true), "{answer}");
    assert_eq!(answer["resumed"], json!(false));
    let handle = answer["job"]["leaseHandle"].as_str().expect("lease handle");
    assert!(answer["job"]["work"]["prompt"]
        .as_str()
        .unwrap()
        .contains("작업해줘 3831"));
    assert!(
        answer["job"]["work"].get("run_id").is_none()
            && answer["job"]["work"].get("runId").is_none(),
        "the run identity stays inside the sealed handle: {answer}"
    );
    // The conversation is the live latest page of the job's channel, under
    // `oort_conversation_read`'s own projection.
    let messages = answer["conversation"]["messages"]
        .as_array()
        .expect("conversation");
    assert!(
        messages.iter().any(|message| message["body"]
            .as_str()
            .unwrap_or_default()
            .contains("작업해줘 3831")),
        "{answer}"
    );
    assert!(answer["conversation"]["nextBefore"].is_i64());

    // ONE call produced the claim fact, the start fact and the stage marker.
    let ledger = ledger_3740(&su, fixture.workspace, run).await;
    let kinds = kinds_3740(&ledger);
    assert_eq!(
        kinds.iter().filter(|k| **k == "claimed").count(),
        1,
        "{kinds:?}"
    );
    assert_eq!(
        kinds.iter().filter(|k| **k == "started").count(),
        1,
        "{kinds:?}"
    );
    let stages: Vec<_> = ledger.iter().filter_map(|row| row.2.as_deref()).collect();
    assert_eq!(stages, ["시작: 요청 확인"]);
    let (steps, output) = run_record_3516(&su, run).await;
    assert_eq!(steps, 1);
    assert_eq!(output["stages"], json!(["시작: 요청 확인"]));
    let run_status: String = sqlx::query_scalar("SELECT status::text FROM agent_run WHERE id=$1")
        .bind(run)
        .fetch_one(&su)
        .await
        .unwrap();
    assert_eq!(run_status, "running");

    // The handle it returned is the real lease: it completes the run.
    let (status, done) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_run_complete",
        json!({"leaseHandle": handle, "status": "succeeded", "body": "끝"}),
    )
    .await;
    assert_eq!(status, 200, "{done}");
}

#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn job_start_is_idempotent_for_the_same_job_and_the_same_agent() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let run = raise_mention_3831(&client, &base, &su, &fixture, "한 번만 시작").await;
    let bearer = &fixture.hosted_bearer;

    let (_, first) = call(&client, &base, bearer, "oort_job_start", json!({})).await;
    let first = structured(&first).clone();
    let handle = first["job"]["leaseHandle"]
        .as_str()
        .expect("handle")
        .to_string();
    let owner = lease_owner_3831(&su, run).await;
    assert!(owner.is_some());
    let before = ledger_3740(&su, fixture.workspace, run).await;

    // A bare second call finds nothing more to claim and changes nothing.
    let (status, again) = call(&client, &base, bearer, "oort_job_start", json!({})).await;
    assert_eq!(status, 200, "{again}");
    assert_eq!(structured(&again)["job"], Value::Null);
    assert_eq!(structured(&again)["started"], json!(false));

    // Re-entry with the handle it already holds: the same job again, the same
    // conversation, and not one more ledger row, step, marker or lease.
    for _ in 0..2 {
        let (status, resumed) = call(
            &client,
            &base,
            bearer,
            "oort_job_start",
            json!({"leaseHandle": handle}),
        )
        .await;
        assert_eq!(status, 200, "{resumed}");
        let resumed = structured(&resumed);
        assert_eq!(resumed["resumed"], json!(true), "{resumed}");
        assert_eq!(resumed["started"], json!(true));
        assert_eq!(
            resumed["job"]["work"]["triggerMessageId"],
            first["job"]["work"]["triggerMessageId"]
        );
        assert_eq!(
            resumed["job"]["work"]["prompt"],
            first["job"]["work"]["prompt"]
        );
        assert_eq!(
            resumed["conversation"]["messages"],
            first["conversation"]["messages"]
        );
    }
    assert_eq!(ledger_3740(&su, fixture.workspace, run).await, before);
    assert_eq!(
        run_record_3516(&su, run).await.0,
        1,
        "one start report, one step"
    );
    assert_eq!(lease_owner_3831(&su, run).await, owner, "no second lease");

    // A handle that is not this agent's, and one whose job is settled, are refused.
    let (status, refused) = call(
        &client,
        &base,
        bearer,
        "oort_job_start",
        json!({"leaseHandle": "momo_lease_v1.AAAA"}),
    )
    .await;
    assert_eq!(status, 403, "{refused}");
    let (status, done) = call(
        &client,
        &base,
        bearer,
        "oort_run_complete",
        json!({"leaseHandle": handle, "status": "succeeded", "body": "끝"}),
    )
    .await;
    assert_eq!(status, 200, "{done}");
    let (status, settled) = call(
        &client,
        &base,
        bearer,
        "oort_job_start",
        json!({"leaseHandle": handle}),
    )
    .await;
    // #3903: a handle whose run is over is a CLOSED answer, not a generic refusal.
    assert_eq!(status, 200, "{settled}");
    assert_eq!(structured(&settled)["job"], Value::Null, "{settled}");
    assert_eq!(structured(&settled)["closed"], json!("run_settled"));
    assert_eq!(structured(&settled)["started"], json!(false));
}

#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn job_start_and_claim_never_expose_a_conversation_the_agent_may_not_read() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let bearer = &fixture.hosted_bearer;
    let secret_text = "상위비밀문장3831";

    // (1) No `messages:read` on the human's approval: the job is delivered and
    //     started, the conversation is simply absent, on BOTH composites.
    raise_mention_3831(&client, &base, &su, &fixture, secret_text).await;
    let without_read: Vec<&str> = ALL_HOSTED_SCOPES_3831
        .iter()
        .copied()
        .filter(|scope| *scope != "messages:read")
        .collect();
    set_approved_scopes_3831(&su, &fixture, &without_read).await;
    let (status, started) = call(&client, &base, bearer, "oort_job_start", json!({})).await;
    assert_eq!(status, 200, "{started}");
    let answer = structured(&started);
    assert_eq!(answer["started"], json!(true), "{answer}");
    assert!(answer["job"]["leaseHandle"].is_string());
    assert!(answer.get("conversation").is_none(), "{answer}");
    let (status, refused) = call(
        &client,
        &base,
        bearer,
        "oort_conversation_read",
        json!({"channelId": fixture.channel}),
    )
    .await;
    assert_ne!(status, 200, "the read tool itself is closed too: {refused}");
    // Release so the claim path below can lease it afresh.
    let handle = answer["job"]["leaseHandle"].as_str().unwrap();
    let (status, _) = call(
        &client,
        &base,
        bearer,
        "oort_job_release",
        json!({"leaseHandle": handle}),
    )
    .await;
    assert_eq!(status, 200);
    let (status, claimed) = call(&client, &base, bearer, "oort_jobs_claim", json!({})).await;
    assert_eq!(status, 200, "{claimed}");
    let job = &structured(&claimed)["jobs"][0];
    assert!(job["leaseHandle"].is_string(), "{claimed}");
    assert!(job.get("conversation").is_none(), "{claimed}");
    let (status, _) = call(
        &client,
        &base,
        bearer,
        "oort_run_complete",
        json!({"leaseHandle": job["leaseHandle"], "status": "succeeded", "body": "끝"}),
    )
    .await;
    assert_eq!(status, 200);

    // (2) Scope restored but the agent has left the channel: the lease still
    //     names the job, yet the channel's history is not this agent's to read.
    set_approved_scopes_3831(&su, &fixture, &ALL_HOSTED_SCOPES_3831).await;
    let _second = raise_mention_3831(&client, &base, &su, &fixture, secret_text).await;
    let _third = raise_mention_3831(&client, &base, &su, &fixture, secret_text).await;
    sqlx::query(
        "UPDATE membership SET left_at=now() WHERE workspace_id=$1 AND channel_id=$2 \
            AND member_id=$3",
    )
    .bind(fixture.workspace)
    .bind(fixture.channel)
    .bind(fixture.hosted_agent)
    .execute(&su)
    .await
    .unwrap();
    for tool in ["oort_job_start", "oort_jobs_claim"] {
        let (status, answer) = call(&client, &base, bearer, tool, json!({})).await;
        assert_eq!(status, 200, "{tool}: {answer}");
        let answer = structured(&answer);
        let carried = answer.to_string();
        // Whatever the composite delivers, no live conversation page rides along:
        // `conversation` is absent (the job's own `work.prompt` is the queued
        // snapshot both tools always had).
        assert!(!carried.contains("\"conversation\""), "{tool}: {answer}");
        let delivered = if tool == "oort_job_start" {
            &answer["job"]
        } else {
            &answer["jobs"][0]
        };
        assert!(
            delivered["leaseHandle"].is_string(),
            "the job itself is delivered (so the absence is the gate, not an empty claim): {tool}: {answer}"
        );
    }
}

#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn job_start_without_the_callback_scope_or_with_a_bad_stage_claims_nothing() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let bearer = &fixture.hosted_bearer;
    let run = raise_mention_3831(&client, &base, &su, &fixture, "아무것도 잡지 마").await;

    // No `agent:runs:callback`: the whole call is refused BEFORE the claim, so
    // there is no half-started job.
    let without_callback: Vec<&str> = ALL_HOSTED_SCOPES_3831
        .iter()
        .copied()
        .filter(|scope| *scope != "agent:runs:callback")
        .collect();
    set_approved_scopes_3831(&su, &fixture, &without_callback).await;
    let (status, refused) = call(&client, &base, bearer, "oort_job_start", json!({})).await;
    assert_eq!((status, error_code(&refused)), (403, -32003), "{refused}");
    assert_eq!(lease_owner_3831(&su, run).await, None, "nothing was leased");
    let before = ledger_3740(&su, fixture.workspace, run).await;
    assert!(!kinds_3740(&before).contains(&"claimed"));

    // A stage the shared rule refuses is judged before the claim too.
    set_approved_scopes_3831(&su, &fixture, &ALL_HOSTED_SCOPES_3831).await;
    for bad in ["a/b", "   ", "bad\u{7}"] {
        let (status, refused) = call(
            &client,
            &base,
            bearer,
            "oort_job_start",
            json!({"stage": bad}),
        )
        .await;
        assert_eq!(
            (status, error_code(&refused)),
            (400, -32602),
            "{bad:?}: {refused}"
        );
    }
    assert_eq!(
        lease_owner_3831(&su, run).await,
        None,
        "still nothing leased"
    );
    assert_eq!(ledger_3740(&su, fixture.workspace, run).await, before);

    // A named stage is the start report's marker.
    let (status, started) = call(
        &client,
        &base,
        bearer,
        "oort_job_start",
        json!({"stage": "시작: 코드 읽기"}),
    )
    .await;
    assert_eq!(status, 200, "{started}");
    assert_eq!(
        run_record_3516(&su, run).await.1["stages"],
        json!(["시작: 코드 읽기"])
    );
}

#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn claim_carries_the_live_conversation_bounded_to_the_context_window() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    for index in 0..40 {
        let sent: Value = client
            .post(format!(
                "{base}/v1/workspaces/{}/channels/{}/messages",
                fixture.workspace, fixture.channel
            ))
            .bearer_auth(&fixture.human_jwt)
            .json(&json!({"clientMsgId": Uuid::new_v4(), "body": format!("잡담 {index}")}))
            .send()
            .await
            .unwrap()
            .json()
            .await
            .unwrap();
        assert!(sent["id"].is_string(), "{sent}");
    }
    let long_body = "길".repeat(5_000);
    let sent: Value = client
        .post(format!(
            "{base}/v1/workspaces/{}/channels/{}/messages",
            fixture.workspace, fixture.channel
        ))
        .bearer_auth(&fixture.human_jwt)
        .json(&json!({"clientMsgId": Uuid::new_v4(), "body": long_body}))
        .send()
        .await
        .unwrap()
        .json()
        .await
        .unwrap();
    assert!(sent["id"].is_string(), "{sent}");
    raise_mention_3831(&client, &base, &su, &fixture, "맨 끝 요청").await;
    let (status, claimed) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_jobs_claim",
        json!({}),
    )
    .await;
    assert_eq!(status, 200, "{claimed}");
    let job = &structured(&claimed)["jobs"][0];
    let messages = job["conversation"]["messages"]
        .as_array()
        .expect("conversation");
    assert_eq!(messages.len(), 30, "bounded to the agent context window");
    assert!(
        messages[0]["body"].as_str().unwrap().contains("맨 끝 요청"),
        "newest first: {claimed}"
    );
    assert!(job["conversation"]["nextBefore"].is_i64());
    // One long message cannot make the composite's answer unbounded: it is cut
    // (and flagged) here, while `oort_conversation_read` still returns it whole.
    let long = messages
        .iter()
        .find(|message| message["bodyTruncated"] == json!(true))
        .expect("the 5000-character message is elided in the composite");
    assert_eq!(long["body"].as_str().unwrap().chars().count(), 2_000);
    let (status, whole) = call(
        &client,
        &base,
        &fixture.hosted_bearer,
        "oort_conversation_read",
        json!({"channelId": fixture.channel, "limit": 5}),
    )
    .await;
    assert_eq!(status, 200, "{whole}");
    assert!(structured(&whole)["messages"]
        .as_array()
        .unwrap()
        .iter()
        .any(|message| message["body"].as_str().unwrap_or_default().chars().count() == 5_000));
    // The queued snapshot is untouched and bounded by the same number.
    assert!(job["work"]["recentMessages"].as_array().unwrap().len() <= 30);
}

// ---------------------------------------------------------------------------
// (#3903, ADR-0162 증보 6) a settled run's job is never re-delivered; a parked or
// settled run answers `closed`; a stale handle is not a connection fault
// ---------------------------------------------------------------------------

async fn set_run_status_3903(su: &PgPool, run: Uuid, status: &str) {
    sqlx::query("UPDATE agent_run SET status = $2::run_status WHERE id = $1")
        .bind(run)
        .bind(status)
        .execute(su)
        .await
        .expect("move the run to the state under test");
}

async fn lapse_job_lease_3903(su: &PgPool, run: Uuid) {
    lapse_lease_3530(su, run).await;
}

async fn job_row_3903(su: &PgPool, run: Uuid) -> (String, Option<String>, bool) {
    sqlx::query_as(
        "SELECT status::text, last_error, lease_owner IS NOT NULL FROM outbox \
          WHERE kind='agent_job' AND lower(payload->>'run_id') = lower($1::text)",
    )
    .bind(run.to_string())
    .fetch_one(su)
    .await
    .expect("the run's job row")
}

/// RED PROOF (#3903, prod 2026-10-16: a `timed_out` run's job was re-claimed every
/// lease expiry for 12 hours, so the agent re-entered dead work on every wake).
/// Approval expiry/decision ends the RUN but leaves its job `pending`; once its lease
/// lapses the claim must not hand it out again, and the leftover is closed (`done`).
///
/// Tamper table:
///   * drop the `NOT EXISTS (agent_run ...)` clause in `CLAIMABLE_JOB_PREDICATE`
///       -> the settled run's job is delivered again by `oort_jobs_claim` / `oort_job_start`
///   * drop `retire_settled_run_hosted_jobs_in_tx` from the claim path -> the row stays `pending`
///   * retire a parked (`awaiting_approval`) run's job as well          -> the parked row turns `done`
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_settled_runs_leftover_job_is_closed_and_never_delivered_again_3903() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let bearer = &fixture.hosted_bearer;

    for (label, status) in [("timed_out", "timed_out"), ("succeeded", "succeeded")] {
        let run =
            raise_mention_3831(&client, &base, &su, &fixture, &format!("끝난 일 {label}")).await;
        let (_, first) = call(&client, &base, bearer, "oort_job_start", json!({})).await;
        assert!(structured(&first)["job"].is_object(), "{label}: {first}");
        // The run settles without the job (approval expiry / decision), the lease lapses.
        set_run_status_3903(&su, run, status).await;
        lapse_job_lease_3903(&su, run).await;

        let (code, claimed) = call(&client, &base, bearer, "oort_jobs_claim", json!({})).await;
        assert_eq!(code, 200, "{label}: {claimed}");
        assert_eq!(
            structured(&claimed)["jobs"],
            json!([]),
            "{label}: a settled run's job is not delivered again"
        );
        let (code, started) = call(&client, &base, bearer, "oort_job_start", json!({})).await;
        assert_eq!(code, 200, "{label}: {started}");
        assert_eq!(structured(&started)["job"], Value::Null, "{label}");
        let (job_status, last_error, leased) = job_row_3903(&su, run).await;
        assert_eq!(job_status, "done", "{label}: the leftover is closed");
        assert_eq!(
            last_error.as_deref(),
            Some("run already settled; job closed")
        );
        assert!(!leased, "{label}: its lease is gone");
    }

    // A PARKED run is not over: its job is not delivered again, but it is not closed.
    let parked = raise_mention_3831(&client, &base, &su, &fixture, "승인 기다리는 일").await;
    let (_, first) = call(&client, &base, bearer, "oort_job_start", json!({})).await;
    assert!(structured(&first)["job"].is_object(), "{first}");
    set_run_status_3903(&su, parked, "awaiting_approval").await;
    lapse_job_lease_3903(&su, parked).await;
    let (_, claimed) = call(&client, &base, bearer, "oort_jobs_claim", json!({})).await;
    assert_eq!(structured(&claimed)["jobs"], json!([]), "{claimed}");
    assert_eq!(job_row_3903(&su, parked).await.0, "pending");
}

/// RED PROOF (#3903): re-entering a job with the handle you hold, after the run was
/// parked for a person or settled, answers a closed `closed` value on a 200 instead of
/// re-sending the job (`started:false` with a live-looking job) or a bare 409.
/// Nothing is reported and nothing is claimed.
///
/// Tamper table:
///   * drop the `closed_reason` branch in `job_start`     -> a parked run gets its job back (`job` is an object)
///   * map the settled run to `awaiting_approval` (or the reverse) -> the two `closed` values swap
///   * let the closed branch send the start report        -> the ledger or the step count moves
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn re_entering_a_parked_or_settled_run_answers_closed_and_reports_nothing_3903() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let bearer = &fixture.hosted_bearer;
    let run = raise_mention_3831(&client, &base, &su, &fixture, "보류 뒤 재진입").await;
    let (_, first) = call(&client, &base, bearer, "oort_job_start", json!({})).await;
    let handle = structured(&first)["job"]["leaseHandle"]
        .as_str()
        .expect("handle")
        .to_string();
    let steps = run_record_3516(&su, run).await.0;
    let ledger = ledger_3740(&su, fixture.workspace, run).await;

    set_run_status_3903(&su, run, "awaiting_approval").await;
    let (code, parked) = call(
        &client,
        &base,
        bearer,
        "oort_job_start",
        json!({"leaseHandle": handle}),
    )
    .await;
    assert_eq!(code, 200, "{parked}");
    let parked = structured(&parked);
    assert_eq!(parked["job"], Value::Null, "{parked}");
    assert_eq!(parked["closed"], json!("run_awaiting_approval"));
    assert_eq!(
        (parked["started"].clone(), parked["resumed"].clone()),
        (json!(false), json!(true))
    );
    assert_eq!(
        run_record_3516(&su, run).await.0,
        steps,
        "no running report"
    );
    assert_eq!(
        ledger_3740(&su, fixture.workspace, run).await,
        ledger,
        "the closed answer writes no run event"
    );
    assert_eq!(
        job_row_3903(&su, run).await.0,
        "pending",
        "a parked job is not closed"
    );

    set_run_status_3903(&su, run, "timed_out").await;
    let (code, settled) = call(
        &client,
        &base,
        bearer,
        "oort_job_start",
        json!({"leaseHandle": handle}),
    )
    .await;
    assert_eq!(code, 200, "{settled}");
    assert_eq!(structured(&settled)["job"], Value::Null);
    assert_eq!(structured(&settled)["closed"], json!("run_settled"));
    assert_eq!(job_row_3903(&su, run).await.0, "done");

    // The agent's own event on the over run is still the plain refusal it always was.
    let (code, event) = call(
        &client,
        &base,
        bearer,
        "oort_run_event",
        json!({"leaseHandle": handle, "status": "running"}),
    )
    .await;
    assert_eq!((code, error_code(&event)), (409, -32005), "{event}");
}

/// RED PROOF (#3903, prod: the badge stuck on 「호출이 거절됨」 because the agent's own
/// stale handle was recorded as a connection error). A refused or unopenable HANDLE
/// leaves `last_tool_error_at` empty and the wire answer unchanged (403 / -32003); a
/// refusal about the CONNECTION (a missing scope) still records `not_authorized`.
///
/// Tamper table:
///   * make `bound_handle` return `NotAuthorized` again -> the garbage handle sets `last_tool_error_at`
///   * stop recording the scope refusal                -> the connection fault leaves no error
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn a_stale_handle_is_not_a_connection_fault_but_a_missing_scope_is_3903() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let bearer = &fixture.hosted_bearer;
    let _ = raise_mention_3831(&client, &base, &su, &fixture, "낡은 handle").await;
    let (_, first) = call(&client, &base, bearer, "oort_job_start", json!({})).await;
    assert!(structured(&first)["job"].is_object(), "{first}");

    for (tool, args) in [
        (
            "oort_run_event",
            json!({"leaseHandle": "momo_lease_v1.AAAA", "status": "running"}),
        ),
        (
            "oort_job_start",
            json!({"leaseHandle": "momo_lease_v1.AAAA"}),
        ),
        (
            "oort_job_renew",
            json!({"leaseHandle": "momo_lease_v1.AAAA"}),
        ),
    ] {
        let (code, refused) = call(&client, &base, bearer, tool, args).await;
        assert_eq!(
            (code, error_code(&refused)),
            (403, -32003),
            "{tool}: {refused}"
        );
    }
    let row = liveness_row_3742(&su, &fixture).await.expect("row");
    assert!(
        row.3.is_none(),
        "a stale handle is the agent's own flow: {row:?}"
    );
    let liveness = connection_liveness_3742(&client, &base, &fixture).await;
    assert_ne!(liveness["state"], json!("error"), "{liveness}");

    let without_callback: Vec<&str> = ALL_HOSTED_SCOPES_3831
        .iter()
        .copied()
        .filter(|scope| *scope != "agent:runs:callback")
        .collect();
    set_approved_scopes_3831(&su, &fixture, &without_callback).await;
    let (code, refused) = call(&client, &base, bearer, "oort_job_start", json!({})).await;
    assert_eq!((code, error_code(&refused)), (403, -32003), "{refused}");
    let row = liveness_row_3742(&su, &fixture).await.expect("row");
    assert!(
        row.3.is_some(),
        "a connection fault is still recorded: {row:?}"
    );
    assert_eq!(row.4.as_deref(), Some("not_authorized"));
}

