/// The three switches as stored: (unfurl enabled row, memory workspace row, tier row).
async fn helper_settings_state_3900(
    su: &PgPool,
    workspace: Uuid,
) -> (
    Option<bool>,
    Option<(bool, bool)>,
    Option<(String, Option<String>)>,
) {
    let unfurl: Option<bool> =
        sqlx::query_scalar("SELECT enabled FROM workspace_unfurl_setting WHERE workspace_id=$1")
            .bind(workspace)
            .fetch_optional(su)
            .await
            .unwrap();
    let memory: Option<(bool, bool)> = sqlx::query_as(
        "SELECT enabled, paused FROM mem_settings WHERE workspace_id=$1 AND scope='workspace'",
    )
    .bind(workspace)
    .fetch_optional(su)
    .await
    .unwrap();
    let tier: Option<(String, Option<String>)> = sqlx::query_as(
        "SELECT mode, auto_target FROM work_tier_policy WHERE workspace_id=$1 AND member_id IS NULL",
    )
    .bind(workspace)
    .fetch_optional(su)
    .await
    .unwrap();
    (unfurl, memory, tier)
}

/// ADR-0201 증보 v2 H13-A15 — for each of the three helper-only settings actions:
/// the card changes nothing before a decision; a plain member's approval is 403
/// `role_required` and changes nothing; an agent bearer cannot decide; the admin's
/// approval executes **exactly the card's args** (stored row == payload args, and
/// the REST route's own GET reads the same values), as the approver, with the REST
/// route's audit row carrying `via_agent`.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn the_helper_settings_cards_execute_as_the_approver_and_nobody_else() {
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let worker = momo_worker_pool_3900().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let plain_jwt = seed_plain_member(&su, &fixture).await;
    let workspace = fixture.workspace;
    let helper = enable_helper_3900(&su, &fixture).await;

    let start = helper_settings_state_3900(&su, workspace).await;
    assert_eq!(start, (None, None, None), "a fresh workspace has no rows");

    for (action_id, args, required_role, audit_action, row_label) in [
        (
            "workspace.unfurl.update",
            json!({"enabled": false}),
            "workspace_operator",
            "unfurl_setting.updated",
            ("링크 미리보기", "켜짐 → 꺼짐"),
        ),
        (
            "workspace.memory.update",
            json!({"enabled": false, "paused": true}),
            "admin",
            "memory.settings.updated",
            ("팀 기억", "끄기 — 새 요약을 만들지 않아요"),
        ),
        (
            "workspace.work_tier.update",
            json!({"mode": "auto", "autoTarget": "cloud"}),
            "admin",
            "work.tier_policy.changed",
            (
                "작업 이어가기",
                "연결 끊김 시 묻기 → 자동 재개 · oort Cloud",
            ),
        ),
    ] {
        let state_before = helper_settings_state_3900(&su, workspace).await;
        let proposed = helper_propose_3900(&su, &worker, &fixture, helper, action_id, args.clone())
            .await
            .unwrap_or_else(|refusal| panic!("{action_id}: {refusal:?}"));
        let approval = proposed.approval_id;
        let (rows, role) = card_rows_3900(&su, proposed.card_message_id).await;
        assert_eq!(role, json!(required_role), "{action_id}");
        assert!(
            rows.as_array()
                .unwrap()
                .iter()
                .any(|row| row["label"] == row_label.0 && row["value"] == row_label.1),
            "{action_id}: {rows}"
        );
        assert_eq!(approval_args_3900(&su, approval).await, args, "{action_id}");
        assert_eq!(
            helper_settings_state_3900(&su, workspace).await,
            state_before,
            "{action_id}: a proposal executes nothing"
        );

        // A plain member cannot approve: 403 role_required, nothing changes.
        let (status, _h, refused) = decide_as(
            &client,
            &base,
            workspace,
            &plain_jwt,
            approval,
            true,
            Uuid::new_v4(),
        )
        .await;
        assert_eq!(status, 403, "{action_id}: {refused}");
        assert_eq!(refused["status"], "role_required", "{action_id}");
        assert_eq!(
            helper_settings_state_3900(&su, workspace).await,
            state_before
        );

        // An agent cannot decide at all.
        let agent_try = client
            .post(format!(
                "{base}/v1/workspaces/{workspace}/approvals/{approval}/decision"
            ))
            .bearer_auth(&fixture.hosted_bearer)
            .json(&json!({"approvalId": approval, "approve": true,
                          "clientDecisionId": Uuid::new_v4()}))
            .send()
            .await
            .unwrap();
        assert!(
            matches!(agent_try.status().as_u16(), 401 | 403),
            "{action_id}: an agent decided"
        );
        assert_eq!(
            helper_settings_state_3900(&su, workspace).await,
            state_before
        );

        // The owner approves: the change is the card's args, made as the owner.
        let (status, _h, approved) = decide_as(
            &client,
            &base,
            workspace,
            &fixture.human_jwt,
            approval,
            true,
            Uuid::new_v4(),
        )
        .await;
        assert_eq!(status, 200, "{action_id}: {approved}");
        assert_eq!(approved["result"]["actionId"], json!(action_id));
        assert_eq!(
            approved["result"]["ref"],
            json!({"type": "workspace_settings", "id": workspace.to_string()})
        );
        let (unfurl, memory, tier) = helper_settings_state_3900(&su, workspace).await;
        match action_id {
            "workspace.unfurl.update" => {
                assert_eq!(unfurl, Some(args["enabled"].as_bool().unwrap()));
                let updated_by: Option<Uuid> = sqlx::query_scalar(
                    "SELECT updated_by FROM workspace_unfurl_setting WHERE workspace_id=$1",
                )
                .bind(workspace)
                .fetch_one(&su)
                .await
                .unwrap();
                assert_eq!(updated_by, Some(fixture.human), "written as the approver");
                let rest: Value = client
                    .get(format!("{base}/v1/workspaces/{workspace}/unfurl-settings"))
                    .bearer_auth(&fixture.human_jwt)
                    .send()
                    .await
                    .unwrap()
                    .json()
                    .await
                    .unwrap();
                assert_eq!(rest["enabled"], args["enabled"], "{rest}");
            }
            "workspace.memory.update" => {
                assert_eq!(
                    memory,
                    Some((
                        args["enabled"].as_bool().unwrap(),
                        args["paused"].as_bool().unwrap()
                    ))
                );
                let rest: Value = client
                    .get(format!("{base}/v1/workspaces/{workspace}/memory/settings"))
                    .bearer_auth(&fixture.human_jwt)
                    .send()
                    .await
                    .unwrap()
                    .json()
                    .await
                    .unwrap();
                assert_eq!(rest["workspace"]["enabled"], args["enabled"], "{rest}");
                assert_eq!(rest["workspace"]["paused"], args["paused"], "{rest}");
            }
            _ => {
                assert_eq!(
                    tier,
                    Some((
                        args["mode"].as_str().unwrap().to_string(),
                        args["autoTarget"].as_str().map(str::to_string)
                    ))
                );
                let rest: Value = client
                    .get(format!("{base}/v1/workspaces/{workspace}/work-tier-policy"))
                    .bearer_auth(&fixture.human_jwt)
                    .send()
                    .await
                    .unwrap()
                    .json()
                    .await
                    .unwrap();
                assert_eq!(rest["workTierPolicy"]["mode"], args["mode"], "{rest}");
                assert_eq!(
                    rest["workTierPolicy"]["autoTarget"], args["autoTarget"],
                    "{rest}"
                );
            }
        }
        // The REST route's own audit row, by the approver, naming the helper.
        let (actor, detail): (Option<Uuid>, Value) = sqlx::query_as(
            "SELECT actor_member_id, detail FROM audit_log \
              WHERE workspace_id=$1 AND action=$2 ORDER BY created_at DESC LIMIT 1",
        )
        .bind(workspace)
        .bind(audit_action)
        .fetch_one(&su)
        .await
        .unwrap();
        assert_eq!(actor, Some(fixture.human), "{action_id}");
        assert_eq!(
            detail["via_agent"],
            json!(helper.to_string()),
            "{action_id}"
        );
        assert_eq!(detail["approval_id"], json!(approval.to_string()));
    }
}

/// ADR-0201 증보 v2 H13-A13·A14 + H7 (#3889) — what never becomes a card:
/// * the helper-only ids (the three settings actions and `plugin.install`) through
///   the Agent Port (`oort_action_propose`) — refused like an unknown id, zero
///   approvals;
/// * an unknown or V9-closed settings key, and `memory {enabled:true}`, from the
///   helper — `InvalidArguments`, zero approvals;
/// * `plugin.install` with an id outside the official four, or with any key but
///   `pluginId`, from the helper — `InvalidArguments`, zero approvals.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn the_helper_only_and_declared_actions_make_no_card_where_they_must_not() {
    use momo_workspace_actions::team_ai::ProposalRefusal;

    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let worker = momo_worker_pool_3900().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let workspace = fixture.workspace;
    let helper = enable_helper_3900(&su, &fixture).await;

    // ---- the Agent Port refuses the helper-only ids -------------------------
    for (action_id, args) in [
        ("workspace.unfurl.update", json!({"enabled": false})),
        ("workspace.memory.update", json!({"enabled": false})),
        (
            "workspace.work_tier.update",
            json!({"mode": "auto", "autoTarget": "cloud"}),
        ),
        (
            "plugin.install",
            json!({"pluginId": "com.momo.plugins.github"}),
        ),
    ] {
        let before = approval_count_3900(&su, workspace).await;
        let (status, refused) =
            try_propose_action_3706(&client, &base, &su, &fixture, action_id, args).await;
        assert_ne!(status, 200, "{action_id}: {refused}");
        assert!(
            structured(&refused).get("approvalId").is_none(),
            "{action_id}: {refused}"
        );
        assert_eq!(
            approval_count_3900(&su, workspace).await,
            before,
            "{action_id}"
        );
    }
    // The same refusal an unknown id gets — no oracle for what exists.
    let (unknown_status, unknown) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "workspace.nonexistent.update",
        json!({"enabled": false}),
    )
    .await;
    let (helper_only_status, helper_only) = try_propose_action_3706(
        &client,
        &base,
        &su,
        &fixture,
        "workspace.unfurl.update",
        json!({"enabled": false}),
    )
    .await;
    assert_eq!(helper_only_status, unknown_status);
    assert_eq!(error_code(&helper_only), error_code(&unknown));

    // ---- the helper: closed and unknown keys, memory on ---------------------
    let before = approval_count_3900(&su, workspace).await;
    for (action_id, args) in [
        (
            "workspace.settings.update",
            json!({"allowedAgentModels": ["x"]}),
        ),
        (
            "workspace.settings.update",
            json!({"welcomeAgentMemberId": helper.to_string()}),
        ),
        (
            "workspace.settings.update",
            json!({"welcomePrompt": "hi", "team_ai_fast_path": false}),
        ),
        (
            "workspace.unfurl.update",
            json!({"enabled": false, "bogus": 1}),
        ),
        ("workspace.memory.update", json!({"enabled": true})),
        (
            "workspace.work_tier.update",
            json!({"mode": "ask", "autoTarget": "cloud"}),
        ),
        (
            "workspace.work_tier.update",
            json!({"mode": "auto", "autoTarget": Uuid::new_v4().to_string()}),
        ),
        ("plugin.install", json!({})),
        ("plugin.install", json!({"pluginId": "external_webhook"})),
        (
            "plugin.install",
            json!({"pluginId": "com.momo.plugins.nope"}),
        ),
        (
            "plugin.install",
            json!({"pluginId": "com.momo.plugins.github", "enabled": false}),
        ),
        (
            "plugin.install",
            json!({"pluginId": "com.momo.plugins.github", "accessToken": "sk-x"}),
        ),
    ] {
        let refused = helper_propose_3900(&su, &worker, &fixture, helper, action_id, args.clone())
            .await
            .expect_err("no card");
        assert_eq!(
            refused,
            ProposalRefusal::InvalidArguments,
            "{action_id} {args}"
        );
    }
    // A change to what is already so is not a proposal (unfurl starts on).
    let refused = helper_propose_3900(
        &su,
        &worker,
        &fixture,
        helper,
        "workspace.unfurl.update",
        json!({"enabled": true}),
    )
    .await
    .expect_err("nothing to change");
    assert_eq!(refused, ProposalRefusal::InvalidArguments);
    assert_eq!(approval_count_3900(&su, workspace).await, before);
}

// ---------------------------------------------------------------------------
// ADR-0201 증보 v2 H7 (#3889) — the `plugin.install` card
// ---------------------------------------------------------------------------

/// `(enabled, installed_by, revoked)` of the workspace's install row, if any.
async fn plugin_install_state_3889(
    su: &PgPool,
    workspace: Uuid,
    plugin: &str,
) -> Option<(bool, Uuid, bool)> {
    sqlx::query_as(
        "SELECT enabled, installed_by, revoked_at IS NOT NULL FROM workspace_plugin_install \
          WHERE workspace_id = $1 AND plugin_id = $2",
    )
    .bind(workspace)
    .bind(plugin)
    .fetch_optional(su)
    .await
    .expect("install state")
}

/// The newest `plugin.installed` audit row of the workspace: actor, subject, run,
/// target type and the detail.
async fn plugin_installed_audit_3889(
    su: &PgPool,
    workspace: Uuid,
) -> (
    Option<Uuid>,
    Option<Uuid>,
    Option<Uuid>,
    Option<String>,
    Value,
) {
    sqlx::query_as(
        "SELECT actor_member_id, subject_member_id, run_id, target_type, detail FROM audit_log \
          WHERE workspace_id = $1 AND action = 'plugin.installed' \
          ORDER BY created_at DESC, id DESC LIMIT 1",
    )
    .bind(workspace)
    .fetch_one(su)
    .await
    .expect("a plugin.installed audit row")
}

/// The rest of an audit detail once the card's own provenance keys are removed.
fn without_provenance_3889(mut detail: Value) -> Value {
    if let Some(object) = detail.as_object_mut() {
        object.remove("via_agent");
        object.remove("approval_id");
    }
    detail
}

/// ADR-0201 증보 v2 H7 / ADR-0186 D2 (#3889) — the app-install card, end to end:
/// * a proposal installs nothing and shows the app, its version and **where it
///   reaches out to** (ADR-0113 D5);
/// * a plain member's approval is 403 `role_required`, nothing is installed, the
///   card stays decidable; an agent cannot decide at all;
/// * the owner's approval installs **enabled**, as the approver, with
///   `plugin.installed` audit naming the helper (`via_agent`), the approval and the
///   run — and the effect equals the REST route's: uninstalling and installing
///   through `POST …/install` leaves the same row state and the same audit detail
///   (minus the card's provenance);
/// * a rejected card installs nothing;
/// * a manifest that changed after the card was drawn (the egress the approver
///   read is no longer the egress) makes the approval a 409 `action_args_invalid`
///   and installs nothing — the digest pin is what holds this;
/// * an install made through REST in the meantime makes the card stale, not a
///   second install.
#[tokio::test]
#[ignore = "needs verifier-owned isolated PostgreSQL 18"]
async fn the_plugin_install_card_installs_as_the_approver_and_equals_the_rest_route() {
    const GITHUB: &str = "com.momo.plugins.github";
    ensure_schema_and_roles();
    let su = superuser_pool().await;
    let app = momo_app_pool().await;
    let worker = momo_worker_pool_3900().await;
    let fixture = seed(&su).await;
    let base = start_server(app, true).await;
    let client = reqwest::Client::new();
    let plain_jwt = seed_plain_member(&su, &fixture).await;
    let workspace = fixture.workspace;
    let helper = enable_helper_3900(&su, &fixture).await;
    let install_path = format!("{base}/v1/workspaces/{workspace}/plugins/{GITHUB}/install");

    // ---- 1. a proposal: a card that says what it will do, and nothing done ----
    let proposed = helper_propose_3900(
        &su,
        &worker,
        &fixture,
        helper,
        "plugin.install",
        json!({"pluginId": GITHUB}),
    )
    .await
    .unwrap_or_else(|refusal| panic!("plugin.install: {refusal:?}"));
    let approval = proposed.approval_id;
    let (rows, role) = card_rows_3900(&su, proposed.card_message_id).await;
    assert_eq!(role, json!("admin"));
    let shown = rows.to_string();
    for must_show in [
        "GitHub 1.1.0",
        "api.githubcopilot.com",
        "설치 안 됨 → 설치됨(켜짐)",
    ] {
        assert!(shown.contains(must_show), "{must_show} missing: {shown}");
    }
    assert_eq!(
        approval_args_3900(&su, approval).await,
        json!({"pluginId": GITHUB})
    );
    assert_eq!(
        plugin_install_state_3889(&su, workspace, GITHUB).await,
        None
    );

    // ---- 2. who may decide ----------------------------------------------------
    let (status, _h, refused) = decide_as(
        &client,
        &base,
        workspace,
        &plain_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 403, "{refused}");
    assert_eq!(refused["status"], "role_required");
    assert_eq!(
        plugin_install_state_3889(&su, workspace, GITHUB).await,
        None,
        "a plain member's approval installs nothing"
    );
    let agent_try = client
        .post(format!(
            "{base}/v1/workspaces/{workspace}/approvals/{approval}/decision"
        ))
        .bearer_auth(&fixture.hosted_bearer)
        .json(&json!({"approvalId": approval, "approve": true,
                      "clientDecisionId": Uuid::new_v4()}))
        .send()
        .await
        .unwrap();
    assert!(
        matches!(agent_try.status().as_u16(), 401 | 403),
        "an agent decided"
    );
    assert_eq!(
        plugin_install_state_3889(&su, workspace, GITHUB).await,
        None
    );

    // ---- 3. the owner approves: the install, as the owner, naming the helper ----
    let (status, _h, approved) = decide_as(
        &client,
        &base,
        workspace,
        &fixture.human_jwt,
        approval,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{approved}");
    assert_eq!(approved["result"]["actionId"], json!("plugin.install"));
    assert_eq!(
        approved["result"]["ref"],
        json!({"type": "workspace_settings", "id": workspace.to_string()})
    );
    let by_card = plugin_install_state_3889(&su, workspace, GITHUB)
        .await
        .expect("installed by the card");
    assert_eq!(
        by_card,
        (true, fixture.human, false),
        "enabled, by the approver"
    );
    let (actor, subject, run, target_type, detail) =
        plugin_installed_audit_3889(&su, workspace).await;
    assert_eq!(actor, Some(fixture.human));
    assert_eq!(
        subject,
        Some(helper),
        "the audit is about the helper's proposal"
    );
    assert!(run.is_some(), "and carries the run");
    assert_eq!(target_type.as_deref(), Some("plugin_install"));
    assert_eq!(detail["via_agent"], json!(helper.to_string()));
    assert_eq!(detail["approval_id"], json!(approval.to_string()));
    assert_eq!(detail["plugin_id"], json!(GITHUB));
    assert_eq!(detail["egress_domains"], json!(["api.githubcopilot.com"]));
    // The outcome remains on the helper's existing approval card.
    let outcome: Option<String> = sqlx::query_scalar(
        "SELECT body FROM message WHERE workspace_id = $1 AND author_member_id = $2 \
         AND type = 'approval_request' AND props->'result'->>'status'='executed' ORDER BY seq DESC LIMIT 1",
    )
    .bind(workspace)
    .bind(helper)
    .fetch_optional(&su)
    .await
    .unwrap();
    assert_eq!(outcome.as_deref(), Some("GitHub 앱을 설치했어요"));
    // No grant came with it: connecting is each member's own consent (D2).
    let grants: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM plugin_grant WHERE workspace_id = $1 AND plugin_id = $2",
    )
    .bind(workspace)
    .bind(GITHUB)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(grants, 0);

    // ---- 4. the same effect as the REST route ---------------------------------
    let removed = client
        .delete(&install_path)
        .bearer_auth(&fixture.human_jwt)
        .send()
        .await
        .unwrap();
    assert_eq!(removed.status().as_u16(), 200);
    let reinstalled = client
        .post(&install_path)
        .bearer_auth(&fixture.human_jwt)
        .header("content-type", "application/json")
        .body(r#"{"enabled":true}"#)
        .send()
        .await
        .unwrap();
    assert_eq!(
        reinstalled.status().as_u16(),
        200,
        "the row existed: restored"
    );
    let by_rest = plugin_install_state_3889(&su, workspace, GITHUB)
        .await
        .expect("installed by REST");
    assert_eq!(
        by_rest, by_card,
        "the card and the route leave the same row state"
    );
    let (rest_actor, rest_subject, rest_run, rest_target, rest_detail) =
        plugin_installed_audit_3889(&su, workspace).await;
    assert_eq!(rest_actor, actor);
    assert_eq!(
        rest_subject,
        Some(fixture.human),
        "REST: the actor is its own subject"
    );
    assert!(rest_run.is_none());
    assert_eq!(rest_target, target_type);
    assert!(rest_detail.get("via_agent").is_none(), "{rest_detail}");
    assert_eq!(
        without_provenance_3889(detail),
        without_provenance_3889(rest_detail),
        "the same audit detail once the card's provenance keys are set aside"
    );

    // ---- 5. a rejected card installs nothing -----------------------------------
    let removed = client
        .delete(&install_path)
        .bearer_auth(&fixture.human_jwt)
        .send()
        .await
        .unwrap();
    assert_eq!(removed.status().as_u16(), 200);
    let proposed = helper_propose_3900(
        &su,
        &worker,
        &fixture,
        helper,
        "plugin.install",
        json!({"pluginId": GITHUB}),
    )
    .await
    .expect("a card for a removed app");
    let (rows, _) = card_rows_3900(&su, proposed.card_message_id).await;
    assert!(
        rows.to_string().contains("설치 해제됨 → 설치됨(켜짐)"),
        "an uninstalled app reads as 설치 해제됨: {rows}"
    );
    let (status, _h, rejected) = decide_as(
        &client,
        &base,
        workspace,
        &fixture.human_jwt,
        proposed.approval_id,
        false,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 200, "{rejected}");
    let state = plugin_install_state_3889(&su, workspace, GITHUB).await;
    assert_eq!(
        state.map(|(enabled, _, revoked)| (enabled, revoked)),
        Some((false, true)),
        "still uninstalled after a rejection"
    );

    // ---- 6. a manifest that changed under the card re-asks ----------------------
    let proposed = helper_propose_3900(
        &su,
        &worker,
        &fixture,
        helper,
        "plugin.install",
        json!({"pluginId": GITHUB}),
    )
    .await
    .expect("a card");
    let (manifest_text, digest): (String, String) = sqlx::query_as(
        "SELECT manifest::text, manifest_digest FROM plugin_registry WHERE plugin_id = $1",
    )
    .bind(GITHUB)
    .fetch_one(&su)
    .await
    .unwrap();
    let mut widened: Value = serde_json::from_str(&manifest_text).unwrap();
    widened["momo"]["egressDomains"] = json!(["api.githubcopilot.com", "evil.example.com"]);
    sqlx::query(
        "UPDATE plugin_registry SET manifest = $2::jsonb, \
                manifest_digest = 'sha256:' || encode(sha256(convert_to(($2::jsonb)::text, 'UTF8')), 'hex') \
          WHERE plugin_id = $1",
    )
    .bind(GITHUB)
    .bind(widened.to_string())
    .execute(&su)
    .await
    .unwrap();
    let (status, _h, stale) = decide_as(
        &client,
        &base,
        workspace,
        &fixture.human_jwt,
        proposed.approval_id,
        true,
        Uuid::new_v4(),
    )
    .await;
    // Put the registry row back before anything can fail on its state.
    sqlx::query("UPDATE plugin_registry SET manifest = $2::jsonb, manifest_digest = $3 WHERE plugin_id = $1")
        .bind(GITHUB)
        .bind(&manifest_text)
        .bind(&digest)
        .execute(&su)
        .await
        .unwrap();
    assert_eq!(status, 409, "{stale}");
    assert_eq!(stale["status"], "action_args_invalid");
    let state = plugin_install_state_3889(&su, workspace, GITHUB).await;
    assert_eq!(
        state.map(|(enabled, _, revoked)| (enabled, revoked)),
        Some((false, true)),
        "the approver never consented to the widened egress"
    );

    // ---- 7. an install made meanwhile makes the card stale, not a second install --
    let reinstalled = client
        .post(&install_path)
        .bearer_auth(&fixture.human_jwt)
        .header("content-type", "application/json")
        .body(r#"{"enabled":true}"#)
        .send()
        .await
        .unwrap();
    assert_eq!(reinstalled.status().as_u16(), 200);
    let audits = sqlx::query_scalar::<_, i64>(
        "SELECT count(*) FROM audit_log WHERE workspace_id = $1 AND action = 'plugin.installed'",
    )
    .bind(workspace)
    .fetch_one(&su)
    .await
    .unwrap();
    let (status, _h, stale) = decide_as(
        &client,
        &base,
        workspace,
        &fixture.human_jwt,
        proposed.approval_id,
        true,
        Uuid::new_v4(),
    )
    .await;
    assert_eq!(status, 409, "{stale}");
    assert_eq!(stale["status"], "action_args_invalid");
    let after = sqlx::query_scalar::<_, i64>(
        "SELECT count(*) FROM audit_log WHERE workspace_id = $1 AND action = 'plugin.installed'",
    )
    .bind(workspace)
    .fetch_one(&su)
    .await
    .unwrap();
    assert_eq!(
        after, audits,
        "the stale card installed nothing and wrote no audit row"
    );
}

// ---------------------------------------------------------------------------
// ADR-0186 증보 2026-10-25 v4 (#4385) — member.avatar.set
//
// 「이걸로 내 프로필 사진 바꿔줘」: an agent proposes that the PERSON WHO CALLED IT wear an
// image THAT PERSON attached in THIS conversation. Sabotage targets (recorded in the PR):
//   * `find_requester_attachment_in_tx`: drop `m.author_member_id = $4`  → another
//     person's file passes (`…refuses_every_picture_that_is_not_the_requesters_own`);
//   * same function: drop `a.channel_id = $3`                            → another
//     conversation's file passes (same test);
//   * `requester_of_run_in_tx`: drop `h.kind = 'human'` / the agent filter → an agent-written
//     trigger or another agent's run names a person (`…a_run_names_its_requester_only_…`);
//   * `execute_workspace_action`: drop the `person != input.member_id` gate → an admin
//     approves someone else's face (`…only_the_pictured_person_decides_and_previews`);
//   * `avatar_preview`: drop the `target != viewer` arm                   → an admin
//     previews it (same test);
//   * `settle_member_avatar_upload_in_tx`: drop `avatar_image_id = NULL`  → the person's
//     own upload dies on `member_avatar_exclusive_ck` (`…human_upload_and_removal_…`);
//   * `clear_own_member_avatar_in_tx`: drop the image branch              → 「내 사진 지우기」
//     leaves the agent-set picture on (same test).
// ---------------------------------------------------------------------------

async fn seed_message_4385(su: &PgPool, ws: Uuid, channel: Uuid, author: Uuid, body: &str) -> Uuid {
    let id = sqlx::query_scalar::<_, Uuid>(
        "INSERT INTO message (workspace_id, channel_id, author_member_id, seq, body, \
            client_msg_id, hlc_ts, hlc_count) \
         SELECT $1, $2, $3, COALESCE(max(seq),0)+1, $4, gen_random_uuid(), 1, 0 \
           FROM message WHERE channel_id = $2 RETURNING id",
    )
    .bind(ws)
    .bind(channel)
    .bind(author)
    .bind(body)
    .fetch_one(su)
    .await
    .expect("seed message");
    // Rows seeded straight into `message` bypass the per-channel counter the REST send
    // reads: bring it up to the highest seq used, or the next real send collides.
    sqlx::query(
        "UPDATE channel_seq SET last_seq = GREATEST(last_seq, \
            (SELECT COALESCE(max(seq), 0) FROM message m WHERE m.channel_id = channel_seq.channel_id)) \
          WHERE workspace_id = $1",
    )
    .bind(ws)
    .execute(su)
    .await
    .expect("bump channel_seq");
    id
}

#[allow(clippy::too_many_arguments)]
async fn seed_attachment_4385(
    su: &PgPool,
    ws: Uuid,
    channel: Uuid,
    uploader: Uuid,
    message: Option<Uuid>,
    drive_id: &str,
    mime: &str,
    status: &str,
) -> Uuid {
    sqlx::query_scalar::<_, Uuid>(
        "INSERT INTO attachment (workspace_id, channel_id, uploader_member_id, message_id, \
            drive_file_id, name, mime, size_bytes, status) \
         VALUES ($1,$2,$3,$4,$5,'me.png',$6,70,$7) RETURNING id",
    )
    .bind(ws)
    .bind(channel)
    .bind(uploader)
    .bind(message)
    .bind(drive_id)
    .bind(mime)
    .bind(status)
    .fetch_one(su)
    .await
    .expect("seed attachment")
}

/// The person mentions the agent in the fixture channel (their own JWT: the **trigger
/// author is the requester**), the agent claims the job and proposes
/// `member.avatar.set` with `args`.
async fn propose_member_avatar_4385(
    client: &reqwest::Client,
    base: &str,
    su: &PgPool,
    fixture: &Fixture,
    requester_jwt: &str,
    args: Value,
) -> (u16, Value) {
    propose_requester_action_4791(
        client,
        base,
        su,
        fixture,
        requester_jwt,
        "member.avatar.set",
        args,
    )
    .await
}

async fn propose_requester_action_4791(
    client: &reqwest::Client,
    base: &str,
    su: &PgPool,
    fixture: &Fixture,
    requester_jwt: &str,
    action_id: &str,
    args: Value,
) -> (u16, Value) {
    let handle_name = hosted_handle(su, fixture.hosted_agent).await;
    let words = match action_id {
        "member.display_name.set" => "내 이름을 바꿔 줘",
        "agent.rename" => "네 이름을 바꿔 줘",
        "agent.profile.update" => "네 사진을 이걸로 바꿔 줘",
        _ => "내 사진을 이걸로 바꿔 줘",
    };
    let trigger: Value = client
        .post(format!(
            "{base}/v1/workspaces/{}/channels/{}/messages",
            fixture.workspace, fixture.channel
        ))
        .bearer_auth(requester_jwt)
        .json(&json!({
            "clientMsgId": Uuid::new_v4(),
            "body": format!("@{handle_name} {words}")
        }))
        .send()
        .await
        .expect("mention send")
        .json()
        .await
        .expect("mention body");
    assert!(trigger["id"].is_string(), "{trigger}");
    let (status, claimed) = call(
        client,
        base,
        &fixture.hosted_bearer,
        "oort_jobs_claim",
        json!({"limit": 10}),
    )
    .await;
    assert_eq!(status, 200, "{claimed}");
    let handle = structured(&claimed)["jobs"][0]["leaseHandle"]
        .as_str()
        .expect("a lease handle")
        .to_string();
    let (status, answer) = call(
        client,
        base,
        &fixture.hosted_bearer,
        "oort_action_propose",
        json!({"handle": handle, "actionId": action_id, "args": args}),
    )
    .await;
    remember_handle_3789(&answer, &handle);
    (status, answer)
}

